local config = {
  ui_story_5075_50750100_1_dialog_content = "(Después de sobrevivir al largo y peligroso viaje de Shadowind a través del mar, finalmente llegamos a las costas de Longzhou.)",
  ui_story_5075_50750100_2_dialog_content = "(Yuebai y Zhong Xu tenían una entrega que hacer en nombre de su gremio, por lo que tuvieron que quedarse unos días más.)",
  ui_story_5075_50750100_3_dialog_content = "(El Gremio Lin nos invitó amablemente a viajar con ellos...)",
  ui_story_5075_50750100_4_dialog_content = "(Pero como enviado oficial de Astra, elegí seguir a Dantang y a Jiu a la capital del Reino de Ji primero.)",
  ui_story_5075_50750100_5_dialog_content = "Vieja Doncella del Dragón, a ti rezo.",
  ui_story_5075_50750100_6_dialog_content = "Por favor, no dejes que caiga la lluvia. El amanecer de mañana, el tofu seco será mi ofrenda para enviar—",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>Chapoteo.</color>",
  ui_story_5075_50750100_8_dialog_content = "¡Urgh!",
  ui_story_5075_50750100_9_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_5075_50750100_10_dialog_content = "Sé que te intriga el paisaje del Reino Ji, pero este barco fluvial no es el Shadowind.",
  ui_story_5075_50750100_11_dialog_content = "Por favor, trata de no quedar tan hipnotizado como para caer al agua.",
  ui_story_5075_50750100_12_dialog_content = "No fue fácil para mí conseguir un emisario tan apreciado como tú desde Astra.",
  ui_story_5075_50750100_13_dialog_content = "Has cruzado el océano y sobrevivido a los asaltos de los Eclipsites y piratas sin sufrir daño.",
  ui_story_5075_50750100_14_dialog_content = "No puedo soportar la culpa y la responsabilidad si te ahogas a pocos pasos del palacio.",
  ui_story_5075_50750100_15_dialog_content = "Jaja... Lo siento por preocuparte de esa manera.",
  ui_story_5075_50750100_16_dialog_content = "Me quedé tan atrapado escuchando la canción de ese barquero que olvidé que estaba en un barco yo mismo.",
  ui_story_5075_50750100_17_dialog_content = "He estado escuchando canciones así desde el puerto.",
  ui_story_5075_50750100_18_dialog_content = "Las notas son tan ligeras y rápidas, y parece que la letra está en un idioma local. ¿De qué están cantando?",
  ui_story_5075_50750100_19_dialog_content = "Esa es una canción de remo.",
  ui_story_5075_50750100_20_dialog_content = "Ji está lleno de lagos y ríos que proporcionan sustento a la gente. Naturalmente, eso hace que los barqueros y pescadores sean prevalentes.",
  ui_story_5075_50750100_21_dialog_content = "Con el tiempo, desarrollaron canciones para pescar y navegar.",
  ui_story_5075_50750100_22_dialog_content = "Exuberantes sean las montañas, clara sea el agua. Las flores estén floreciendo, los sauces sean elegantes. Eso es de lo que cantan.",
  ui_story_5075_50750100_23_dialog_content = "Y la melodía que acabas de escuchar era una que buscaba la bendición de las deidades.",
  ui_story_5075_50750100_24_dialog_content = "\"Dragón Doncella, por favor asegura un día soleado y una navegación tranquila.\"",
  ui_story_5075_50750100_25_dialog_content = "\"Te ofreceré delicioso tofu seco después de llegar a casa sano y salvo.\"",
  ui_story_5075_50750100_26_dialog_content = "Esa es la esencia de ello.",
  ui_story_5075_50750100_27_dialog_content = "¡Oh, la Doncella Dragón!",
  ui_story_5075_50750100_28_dialog_content = "¿No es <color=#FFB400>Doncella Dragón Sobre Mares Turbulentos</color> el nombre de esa danza que enseñaste a Vice en la Bahía Twin Pavilions?",
  ui_story_5075_50750100_29_dialog_content = "Recuerdo que dijiste que la gente costera de Longzhou realmente venera a la Doncella Dragón.",
  ui_story_5075_50750100_30_dialog_content = "... ¿Pero a las deidades realmente les gusta tanto el tofu seco?",
  ui_story_5075_50750100_31_dialog_content = "Bueno, no del todo. La ofrenda en la canción popular en realidad varía.",
  ui_story_5075_50750100_32_dialog_content = "La Doncella del Dragón no pide ofrendas, pero la gente aún las agrega a la canción para mostrar su agradecimiento.",
  ui_story_5075_50750100_33_dialog_content = "Ese hombre cantó sobre tofu seco probablemente porque eso es lo que tenía en casa.",
  ui_story_5075_50750100_34_dialog_content = "¿Y ella está bien con eso? Qué deidad tan curiosa.",
  ui_story_5075_50750100_35_dialog_content = "Pensé que había aprendido mucho sobre Longzhou en Twin Pavilions Bay...",
  ui_story_5075_50750100_36_dialog_content = "Pero ahora que estoy aquí, siento que aprendo algo nuevo con cada paso que doy.",
  ui_story_5075_50750100_37_dialog_content = "Solo desearía que Vice y Carleen estuvieran aquí para verlo también.",
  ui_story_5075_50750100_38_dialog_content = "Eso puede suceder antes de lo que piensas.",
  ui_story_5075_50750100_39_dialog_content = "¡Así es! Después de todo, nuestra misión es fortalecer las relaciones entre nuestras dos tierras.",
  ui_story_5075_50750100_40_dialog_content = "Si todo va bien, quizás mis amigos de Astra podrán visitar Longzhou y verlo todo por sí mismos.",
  ui_story_5075_50750100_41_dialog_content = "Así como intercambiar la estrategia y tecnología para oponerse a los Eclipsites.",
  ui_story_5075_50750100_42_dialog_content = "La comunicación y la cooperación solo pueden facilitar la paz para ambas personas.",
  ui_story_5075_50750100_43_dialog_content = "Creo que debemos contar contigo como el emisario para hacer esa visión realidad.",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>Ruido sordo.</color>",
  ui_story_5075_50750100_45_dialog_content = "Hemos llegado a la orilla, y el destino está adelante, Su Alteza y PlayerName.",
  ui_story_5075_50750100_46_dialog_content = "Tenemos que desembarcar aquí para entrar a la ciudad.",
  ui_story_5075_50750100_47_dialog_content = "Por favor espera un segundo, PlayerName.",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>Dantang se baja del barco, sonríe y hace una leve reverencia.</color>",
  ui_story_5075_50750100_49_dialog_content = "Soy la Princesa Zhuohua, encargada por el Rey de Ji para ser la embajadora en Astra.",
  ui_story_5075_50750100_50_dialog_content = "Su Excelencia ha aceptado mi invitación y ha viajado lejos hasta Longzhou.",
  ui_story_5075_50750100_51_dialog_content = "Por eso, permítame expresar una vez más mi gratitud y aprecio.",
  ui_story_5075_50750100_52_dialog_content = "Bienvenido a la <color=#FFB400>capital del Reino Ji</color>—",
  ui_story_5075_50750100_53_dialog_content = "<color=#FFB400>Haojin</color>.",
  ui_story_5075_50750100_54_dialog_content = "¡No lo menciones, y gracias por tenerme!",
  ui_story_5075_50750100_55_dialog_content = "Ahora es el momento de que cumpla mi parte del trato como enviado de Astra.",
  ui_story_5075_50750100_56_dialog_content = "Su Alteza, los asistentes reales han llegado. Debemos regresar al palacio y al rey.",
  ui_story_5075_50750100_57_dialog_content = "Bueno entonces, PlayerName...",
  ui_story_5075_50750100_58_dialog_content = "Saludos, Su Alteza, estimado emisario.",
  ui_story_5075_50750100_59_dialog_content = "Soy el administrador a cargo de la Casa de Huéspedes Real, y es un gran honor tenerlo como nuestro invitado, estimado emisario.",
  ui_story_5075_50750100_60_dialog_content = "La casa de huéspedes se encargará de todas las actividades diarias y los arreglos de seguridad para ti mientras estás en el Reino de Ji.",
  ui_story_5075_50750100_61_dialog_content = "Parece que debemos separarnos por ahora.",
  ui_story_5075_50750100_62_dialog_content = "Una vez que termine con los asuntos oficiales y Yuebai regrese en dos días, nos reuniremos de nuevo. Te llevaré a hacer un recorrido por Haojin.",
  ui_story_5075_50750100_63_dialog_content = "El Festival de Primavera estará sobre nosotros pronto. Es el momento más celebrado en Longzhou.",
  ui_story_5075_50750100_64_dialog_content = "Las calles estarán salpicadas de coloridas linternas, dragones danzantes, así como ferias con innumerables vendedores de aperitivos.",
  ui_story_5075_50750100_65_dialog_content = "Seguro que te dejará una impresión eterna.",
  ui_story_5075_50750100_66_dialog_content = "¡Esperándolo!",
  ui_story_5075_50750100_67_dialog_content = "(Poco sabíamos que un plan tan simple terminaría lleno de complicaciones...)",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>Casa de Huéspedes Real</color>",
  ui_story_5075_50750100_69_dialog_content = "Su Excelencia, por favor tome un poco de té.",
  ui_story_5075_50750100_70_dialog_content = "Es té de bambú amatista, elaborado con agua fresca de manantial recién bajada de la montaña, que ofrece un sabor puro y dulce sin igual.",
  ui_story_5075_50750100_71_dialog_content = "¡Es delicioso! Gracias.",
  ui_story_5075_50750100_72_dialog_content = "Estimado emisario, no estoy seguro de tus preferencias, así que he preparado una variedad de bocadillos.",
  ui_story_5075_50750100_73_dialog_content = "Aquí tenemos crema dorada crujiente, pastel de siete capas y bola de rocío de jade... Si prefieres algo diferente, solo avísanos.",
  ui_story_5075_50750100_74_dialog_content = "¡Esa es una gran variedad de bocadillos!",
  ui_story_5075_50750100_75_dialog_content = "Estimado emisario, permíteme ayudarte a cambiarte y bañarte.",
  ui_story_5075_50750100_76_dialog_content = "¡N-N-No gracias! ¡Puedo hacerlo yo mismo!",
  ui_story_5075_50750100_77_dialog_content = "U-Ustedes definitivamente saben cómo cuidar a los invitados...",
  ui_story_5075_50750100_78_dialog_content = "Me hace sentir bastante nervioso. No quiero arruinar la imagen de Astra haciendo algo mal, ¿sabes?",
  ui_story_5075_50750100_79_dialog_content = "Deberíamos ir al palacio mañana para discutir asuntos oficiales, así que no creo que vaya a estar aquí mucho tiempo.",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>Día Dos</color>",
  ui_story_5075_50750100_81_dialog_content = "¡Alguien viene! ¿Están aquí para llamarme al palacio?",
  ui_story_5075_50750100_82_dialog_content = "Estimado emisario, nuestro rey está encantado de saber que ha venido desde el extranjero.",
  ui_story_5075_50750100_83_dialog_content = "Así que me envió para entregarte sus regalos de bienvenida, incluyendo té y frutas raras, atuendos lujosos y seda, así como varias fragancias.",
  ui_story_5075_50750100_84_dialog_content = "¿Son todos estos realmente para mí? Pero...",
  ui_story_5075_50750100_85_dialog_content = "Ahora que los regalos han sido entregados, me disculparé.",
  ui_story_5075_50750100_86_dialog_content = "May disfrute de buena salud durante su estancia en Ji para aliviar la ansiedad de la Princesa Zhuohua, Su Excelencia.",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>Día Tres</color>",
  ui_story_5075_50750100_88_dialog_content = "... ¿Por qué aún no me han llamado al palacio?",
  ui_story_5075_50750100_89_dialog_content = "¿Se siente aburrido, Su Excelencia? ¿Qué tal un poco de ópera?",
  ui_story_5075_50750100_90_dialog_content = "Si te interesa, puedo conseguir algunos artistas de primera categoría para que hagan un espectáculo para ti.",
  ui_story_5075_50750100_91_dialog_content = "No me refería a eso...",
  ui_story_5075_50750100_92_dialog_content = "¿No es lo tuyo? ¿Qué tal algo de Pingtan o espectáculos callejeros?",
  ui_story_5075_50750100_93_dialog_content = "Si nada de eso te interesa, podrías probar las peleas de grillos, las peleas de codornices y muchas otras diversiones en la ciudad de Haojin.",
  ui_story_5075_50750100_94_dialog_content = "No, realmente no necesito nada de eso ahora mismo...",
  ui_story_5075_50750100_95_dialog_content = "¡Solo quiero ir a conocer al gobernante del Reino Ji!",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>Día Cuatro</color>",
  ui_story_5075_50750100_97_dialog_content = "Ah, por fin libre.",
  ui_story_5075_50750100_98_dialog_content = "¿Qué es este lugar? Con todas estas señales, dudo que el rey viva por aquí...",
  ui_story_5075_50750100_99_dialog_content = "Estimado emisario, en respuesta a tu pregunta, parece que has estado saltándote las comidas durante los últimos días, quizás debido al aburrimiento.",
  ui_story_5075_50750100_100_dialog_content = "Entonces, hablé con el mayordomo para establecer un horario divertido para ti.",
  ui_story_5075_50750100_101_dialog_content = "Para los que visitan Haojin por primera vez, el Templo de la Doncella Dragón en las Montañas del Sur es una visita obligada.",
  ui_story_5075_50750100_102_dialog_content = "Además de las magníficas escenas con picos imponentes y rocas intrincadas, se rumorea que existen milagros manifestados por la Doncella Dragón.",
  ui_story_5075_50750100_103_dialog_content = "Siéntete libre de disfrutar del paisaje o hacer tus oraciones. Todos los demás han sido despejados, así que nadie te molestará.",
  ui_story_5075_50750100_104_dialog_content = "¿Eh? ¿Hiciste que la gente se fuera solo por mí? No es de extrañar que este lugar esté tan desierto...",
  ui_story_5075_50750100_105_dialog_content = "Realmente no tienes que pasar por todos estos problemas. No soy una persona famosa ni nada por el estilo, y definitivamente no me importa ser parte de la multitud.",
  ui_story_5075_50750100_106_dialog_content = "Bromeas, estimado emisario. Eres un invitado de honor del Reino Ji, y estamos dedicados a servirte con nuestros máximos esfuerzos.",
  ui_story_5075_50750100_107_dialog_content = "Siéntete libre de seguir adelante y disfrutar.",
  ui_story_5075_50750100_108_dialog_content = "(Bien... ya estoy aquí, así que podría echar un vistazo alrededor.)",
  ui_story_5075_50750100_109_dialog_content = "(Hay una estatua seriamente imponente en el centro del salón principal. ¿Es esa la Doncella Dragón?)",
  ui_story_5075_50750100_110_dialog_content = "(Hay todo tipo de ofrendas como dijo Dantang, desde frutas y verduras hasta té y bocadillos...)",
  ui_story_5075_50750100_111_dialog_content = "¿Eh? ¿También está aquí alguien más?",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  ui_story_5075_50750100_113_dialog_content = "Me pregunto qué doncella dejó caer esto... ¿O pertenece a ese extraño que acabo de ver?",
  ui_story_5075_50750100_114_dialog_content = "Estimado emisario—",
  ui_story_5075_50750100_115_dialog_content = "He inspeccionado aquí varias veces. No hay nadie más en el templo que tú.",
  ui_story_5075_50750100_116_dialog_content = "Pero estoy seguro de que vi a alguien aquí hace un momento. Parece que también dejaron caer algo...",
  ui_story_5075_50750100_117_dialog_content = "No vi ninguno... ¿Eh?",
  ui_story_5075_50750100_118_dialog_content = "¿A dónde fueron todas las ofrendas?",
  ui_story_5075_50750100_119_dialog_content = "C-Cómo podría esto...",
  ui_story_5075_50750100_120_dialog_content = "Por favor acepte nuestras disculpas, Su Excelencia. Fue un descuido de nuestra parte dejar que un ladrón se escabullera.",
  ui_story_5075_50750100_121_dialog_content = "Los espíritus malvados no se atreverían a acercarse al Templo de la Doncella Dragón. Deben ser esos astutos fiendlings otra vez...",
  ui_story_5075_50750100_122_dialog_content = "¿Qué pasa con los diabólicos?",
  ui_story_5075_50750100_123_dialog_content = "No es gran cosa, no vale la pena tu preocupación, estimado emisario.",
  ui_story_5075_50750100_124_dialog_content = "Fue nuestra negligencia. Por favor, baja primero con los guardias. Informaré de esto al administrador.",
  ui_story_5075_50750100_125_dialog_content = "¡Guardias! ¡Escolten al emisario de regreso a la casa de huéspedes!",
  ui_story_5075_50750100_126_dialog_content = "¡Afirmativo!",
  ui_story_5075_50750100_127_dialog_content = "E-Espera, todos... Al menos déjenme tomar unas cuantas respiraciones más de aire fresco—",
  ui_story_5075_50750100_128_dialog_content = "(Los próximos días no fueron diferentes a antes.)",
  ui_story_5075_50750100_129_dialog_content = "(Comí, dormí y me divertí... Cuidaron de mí de todas las formas posibles, y los guardias me escoltaron a donde quiera que fuera.)",
  ui_story_5075_50750100_130_dialog_content = "(Pero nadie me daba una respuesta directa cada vez que preguntaba sobre ir al palacio.)",
  ui_story_5075_50750100_131_dialog_content = "Nada se va a resolver a este ritmo. Debería ir a hablar con el mayordomo yo mismo.",
  ui_story_5075_50750100_132_dialog_content = "Necesito asegurar una audiencia con el rey, o de lo contrario Dantang y yo nunca completaremos nuestra misión.",
  ui_story_5075_50750100_133_dialog_content = "Solo espero que no haya guardias que se interpongan en mi camino...",
  ui_story_5075_50750100_134_dialog_content = "... Princesa Zhuohua.",
  ui_story_5075_50750100_135_dialog_content = "(¿Eh? ¿Alguien acaba de mencionar a Dantang?)",
  ui_story_5075_50750100_136_dialog_content = "¿Es la noticia de verdad?",
  ui_story_5075_50750100_137_dialog_content = "Jaja, ya sabes, no hay humo sin fuego.",
  ui_story_5075_50750100_138_dialog_content = "Escuché que nuestro príncipe heredero está locamente enamorado de esa princesa. Solo tiene ojos para ella.",
  ui_story_5075_50750100_139_dialog_content = "La princesa aún no ha aceptado. Pero las sirvientas en el palacio dicen que el rey tiene la intención de organizar un matrimonio para ellos.",
  ui_story_5075_50750100_140_dialog_content = "¡Eso tiene sentido! No es de extrañar que el palacio haya estado bullicioso, demasiado ocupado para preocuparse por cualquier otra cosa.",
  ui_story_5075_50750100_141_dialog_content = "¡Oh Dios mío, el patito realmente se ha convertido en un cisne! Si lo recuerdo correctamente, ¿no estaba aquí para saldar una deuda?",
  ui_story_5075_50750100_142_dialog_content = "?",
  ui_story_5075_50750100_143_dialog_content = "Disculpe, pero ¿de quién está hablando—",
  ui_story_5075_50750100_144_dialog_content = "Resulta que estás aquí, estimado emisario. Te estaba buscando por todas partes.",
  ui_story_5075_50750100_145_dialog_content = "El rey ha emitido un decreto, invitándote especialmente a asistir al gran banquete de hoy y compartir tus perspectivas sobre asuntos extranjeros.",
  ui_story_5075_50750100_146_dialog_content = "Por favor, ve a prepararte ahora, luego te llevaré al palacio.",
  ui_story_5075_50750100_147_dialog_content = "¿Quieres decir ahora mismo? ¿Por qué nadie me lo dijo antes?",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>Jade torres, puertas de oro, majestuosas y grandiosas. Melodías en armonía, resonando en la tierra imperial.</color>",
  ui_story_5075_50750201_2_dialog_content = "¡Emisario de Astra, por favor entre a la corte real!",
  ui_story_5075_50750201_3_dialog_content = "Resulta que la gente de las tierras occidentales se ve diferente a nosotros.",
  ui_story_5075_50750201_4_dialog_content = "Los atuendos son bastante novedosos, aunque el corte ajustado reduce la elegancia.",
  ui_story_5075_50750201_5_dialog_content = "Se rumorea que es un Caelestite, bastante raro incluso en las tierras occidentales.",
  ui_story_5075_50750201_6_dialog_content = "(Parece que están hablando de mí.)",
  ui_story_5075_50750201_7_dialog_content = "(Dantang también está aquí, y nadie parece estar molestando a ella, pero parece bastante tensa.)",
  ui_story_5075_50750201_8_dialog_content = "Eres PlayerName, ¿verdad? Se dice que has hecho mucho para recuperar las rutas marítimas entre los dos continentes.",
  ui_story_5075_50750201_9_dialog_content = "Al conocerte ahora, puedo decir que eres realmente un joven talentoso.",
  ui_story_5075_50750201_10_dialog_content = "Me alabas demasiado. Shadowind solo pudo regresar a salvo gracias a los esfuerzos conjuntos de todos...",
  ui_story_5075_50750201_11_dialog_content = "No hay necesidad de ser humilde. Alguien, sirva a nuestro invitado un poco de té.",
  ui_story_5075_50750201_12_dialog_content = "Es bastante raro encontrar a un viajero de más allá del mar. ¿Qué tal si compartes algunas historias de tierras extranjeras con nosotros?",
  ui_story_5075_50750201_13_dialog_content = "Se dice que en tu continente hay gigantes de acero expertos en la guerra.",
  ui_story_5075_50750201_14_dialog_content = "Esos gigantes, controlados por soldados dentro de ellos solo con pensamientos, tienen ojos brillantes como un rayo y la fuerza para mover montañas. ¿Es eso cierto?",
  ui_story_5075_50750201_X14_option_content = "Eso es demasiado...",
  ui_story_5075_50750201_15_dialog_content = "Eso es... un poco exagerado.",
  ui_story_5075_50750201_16_dialog_content = "La tecnología de Astra aún no está a ese nivel.",
  ui_story_5075_50750201_17_dialog_content = "Si bien es cierto que tenemos Colossi, no son las increíbles armas que estás describiendo.",
  ui_story_5075_50750201_18_dialog_content = "Por no mencionar que no quedan muchos de ellos, y solo unas pocas personas en el mundo pueden controlarlos.",
  ui_story_5075_50750201_X18_option_content = "Quizás en el futuro, aunque.",
  ui_story_5075_50750201_X19_dialog_content = "Aunque tal fuerza poderosa no exista ahora...",
  ui_story_5075_50750201_X20_dialog_content = "Con la Federación Illumina experta en tecnología militar y Lumopolis, proficientes en magia ritual, alrededor...",
  ui_story_5075_50750201_X21_dialog_content = "Quizás un día, Astra creará a los gigantes que describiste.",
  ui_story_5075_50750201_X22_dialog_content = "Oh, ¿así que estás diciendo que no existe tal cosa?",
  ui_story_5075_50750201_19_dialog_content = "Entonces, ¿cómo confrontan tus soldados a los espíritus malignos en la batalla?",
  ui_story_5075_50750201_20_dialog_content = "Nuestros militares investigan y producen todo tipo de armas y armaduras para combatirlos.",
  ui_story_5075_50750201_21_dialog_content = "Combinado con Luminatics, nos permiten defendernos de los Eclipsites... o \"espíritus malvados\", como tú los llamas.",
  ui_story_5075_50750201_22_dialog_content = "Entonces, ¿aún confías en la fuerza física en combate, eh?",
  ui_story_5075_50750201_23_dialog_content = "Bueno, entonces, en tu extenso continente, ¿existen técnicas de inmortalidad o formas de ascender?",
  ui_story_5075_50750201_24_dialog_content = "Yo, eh... No lo creo.",
  ui_story_5075_50750201_25_dialog_content = "Tenemos algunas personas longevas en nuestra tierra. De hecho, la reina de Northland es famosa por su apariencia eternamente juvenil.",
  ui_story_5075_50750201_26_dialog_content = "Pero en cuanto a verdaderos inmortales... Me temo que no he oído hablar de ninguno.",
  ui_story_5075_50750201_27_dialog_content = "Hmm, parece que a pesar del mar de por medio, el otro continente no es muy diferente de nuestro Longzhou.",
  ui_story_5075_50750201_28_dialog_content = "No del todo cierto—",
  ui_story_5075_50750201_29_dialog_content = "Ejem.",
  ui_story_5075_50750201_30_dialog_content = "(No seas impulsivo.)",
  ui_story_5075_50750201_31_dialog_content = "...",
  ui_story_5075_50750201_32_dialog_content = "Más interesante aún, he oído que, PlayerName, tienes algunas habilidades peculiares.",
  ui_story_5075_50750201_33_dialog_content = "Y pueden amplificar la fuerza de las Artes de Fuerza varias veces.",
  ui_story_5075_50750201_34_dialog_content = "¿Qué tal si te nombro para un puesto nominal para que puedas quedarte en el Reino Ji?",
  ui_story_5075_50750201_35_dialog_content = "Has visto la belleza de la ciudad de Haojin de primera mano estos días.",
  ui_story_5075_50750201_36_dialog_content = "Nuestro Reino de Ji, bendecido con abundante tierra y mar, floreciente en todos los aspectos, es como un paraíso en la tierra.",
  ui_story_5075_50750201_37_dialog_content = "¿No es mucho mejor que esa tierra invadida por espíritus malignos?",
  ui_story_5075_50750201_38_dialog_content = "Hmm, agradezco el amable gesto, pero Astra es mi hogar. Tarde o temprano, tengo que volver.",
  ui_story_5075_50750201_39_dialog_content = "No solo eso, sino que no estoy aquí por mi propio placer. Vine como emisario para promover mejores relaciones entre nuestras tierras.",
  ui_story_5075_50750201_40_dialog_content = "De vuelta en Astra, hemos desarrollado todo tipo de contramedidas efectivas contra los Eclipsites. Ya sea Illumina o Lumopolis—",
  ui_story_5075_50750201_41_dialog_content = "Bueno, tienes un punto. Pero dejemos que las Oficinas de Comercio Marítimo se encarguen de asuntos tan menores.",
  ui_story_5075_50750201_42_dialog_content = "Discutir estos asuntos ahora sería un desperdicio de un momento tan hermoso.",
  ui_story_5075_50750201_43_dialog_content = "El Festival de Primavera se acerca, y Ji rebosa de prosperidad y maravillas. Deberíamos celebrar juntos.",
  ui_story_5075_50750201_44_dialog_content = "¡Todos, levanten sus copas!",
  ui_story_5075_50750201_45_dialog_content = "Pero-",
  ui_story_5075_50750201_46_dialog_content = "¡Por la longevidad del rey y su eterno reinado!",
  ui_story_5075_50750201_47_dialog_content = "¡Por la abundancia y prosperidad del Reino de Ji!",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50750201_49_dialog_content = "¡Es un terremoto!",
  ui_story_5075_50750201_50_dialog_content = "¡Apúrate, protege al rey!",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>Las mesas y sillas tiemblan, los platos tintinean y caen, y los temblores tardan un tiempo en calmarse completamente.</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>El gran salón, animado hace un momento, ahora es un desastre, lleno de los sonidos de la gente corriendo y gritando órdenes.</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>Los funcionarios, que estaban llenos de espíritu hace unos momentos, ahora parecen bastante desaliñados.</color>",
  ui_story_5075_50750201_54_dialog_content = "Uf, eso estuvo cerca, pero acabo de recibir la buena noticia de que la gente está a salvo.",
  ui_story_5075_50750201_55_dialog_content = "No es como lo planeé, pero aquí es donde termina el banquete hoy.",
  ui_story_5075_50750201_56_dialog_content = "Dantang¿?",
  ui_story_5075_50750201_57_dialog_content = "Ven, PlayerName. Vamos a un lugar más tranquilo.",
  ui_story_5075_50750201_58_dialog_content = "Creo que mi diadema se enganchó en algo...",
  ui_story_5075_50750201_59_dialog_content = "Lo siento, Dantang, pero ¿podrías echarme una mano?",
  ui_story_5075_50750201_60_dialog_content = "Las flores de este árbol son tan bonitas. No quiero lastimar accidentalmente algo tan precioso.",
  ui_story_5075_50750201_61_dialog_content = "Jeje, estas flores de ciruelo no son precisamente preciosas pero son bastante comunes. Tal vez seas el primero en tratarlas con tanta delicadeza.",
  ui_story_5075_50750201_62_dialog_content = "Por favor, permanece quieto y déjame liberarte.",
  ui_story_5075_50750201_63_dialog_content = "...",
  ui_story_5075_50750201_64_dialog_content = "Bueno, está hecho.",
  ui_story_5075_50750201_65_dialog_content = "¿Está encontrando su estancia en la Casa Real de Huéspedes cómoda estos últimos días?",
  ui_story_5075_50750201_66_dialog_content = "Sí, pero parece que todos están exagerando un poco con su hospitalidad.",
  ui_story_5075_50750201_67_dialog_content = "Ni siquiera me dejan servirme una taza de agua. Me hace sentir como si fuera realmente valioso o algo así.",
  ui_story_5075_50750201_68_dialog_content = "¿No es ese el caso?",
  ui_story_5075_50750201_69_dialog_content = "Por favor, no bromees sobre eso.",
  ui_story_5075_50750201_70_dialog_content = "Hice todo lo posible para no hacer el ridículo. Eso no fue fácil para mí, ya sabes.",
  ui_story_5075_50750201_71_dialog_content = "Tampoco hice un buen trabajo como emisario.",
  ui_story_5075_50750201_72_dialog_content = "Parece imposible entrar al palacio. Ni siquiera he tenido la oportunidad de presentar a Astra, mucho menos negociar mejores lazos.",
  ui_story_5075_50750201_73_dialog_content = "... Mis disculpas, PlayerName.",
  ui_story_5075_50750201_74_dialog_content = "Eso es negligencia de mi parte.",
  ui_story_5075_50750201_75_dialog_content = "Te invité a venir hasta aquí y sin embargo, no pude proporcionarte un foro.",
  ui_story_5075_50750201_76_dialog_content = "No es tu culpa, Dantang. Si hubiera hecho un mejor trabajo preparándome, no estaría dando tumbos así.",
  ui_story_5075_50750201_77_dialog_content = "No, es mi culpa...",
  ui_story_5075_50750201_78_dialog_content = "*se ríe*",
  ui_story_5075_50750201_79_dialog_content = "Jajaja... Toda esta disculpa entre amigos es un poco graciosa, ¿no es así?",
  ui_story_5075_50750201_80_dialog_content = "Bueno, no sirve de nada preocuparse por el pasado. Volveré y me prepararé para mi próximo viaje al palacio, y prometo que lo haré mejor entonces.",
  ui_story_5075_50750201_81_dialog_content = "... Ah, y una cosa más.",
  ui_story_5075_50750201_82_dialog_content = "¿Si?",
  ui_story_5075_50750201_83_dialog_content = "Antes de venir, escuché a dos de las sirvientas hablar... Dijeron algo sobre planes de matrimonio entre tú y el príncipe del Reino Ji?",
  ui_story_5075_50750201_84_dialog_content = "Y no hablaron de ti en un tono agradable, diciendo que estás aquí como garantía.",
  ui_story_5075_50750201_85_dialog_content = "Por eso tengo que preguntar: ¿te tratan bien por aquí?",
  ui_story_5075_50750201_86_dialog_content = "Bueno...",
  ui_story_5075_50750201_87_dialog_content = "Estoy bien.",
  ui_story_5075_50750201_88_dialog_content = "De hecho, escuché los mismos rumores antes, pero no esperaba que tú también los escucharas.",
  ui_story_5075_50750201_89_dialog_content = "Esa es la intención del rey, pero he dejado clara mi posición, y él no puede obligarme.",
  ui_story_5075_50750201_X89_dialog_content = "Sobre eso... Es cierto que estoy aquí debido a un préstamo a Ye.",
  ui_story_5075_50750201_X90_dialog_content = "Sin embargo, no es asunto de los sirvientes juzgar. Me ocuparé de los chismosos más tarde.",
  ui_story_5075_50750201_X91_dialog_content = "Dantang...",
  ui_story_5075_50750201_90_dialog_content = "No te preocupes. He estado aquí el tiempo suficiente para obtener suficiente apoyo.",
  ui_story_5075_50750201_91_dialog_content = "Nadie en todo el palacio se ha atrevido a desafiarme abiertamente.",
  ui_story_5075_50750201_92_dialog_content = "Eso incluye al príncipe, ¿verdad?",
  ui_story_5075_50750201_93_dialog_content = "¡Por supuesto! Sin mencionar que el príncipe heredero es solo un...",
  ui_story_5075_50750201_94_dialog_content = "¡Dantang! ¿Estás bien, Dantang?",
  ui_story_5075_50750201_95_dialog_content = "... ¿Príncipe heredero? Deberías estar descansando en tu cámara a esta hora tan tarde de la noche.",
  ui_story_5075_50750201_96_dialog_content = "Estoy preocupado por ti.",
  ui_story_5075_50750201_97_dialog_content = "Ese terremoto fue bastante fuerte hace un momento. ¿Estás bien? ¿Alguna herida? ¿Asustado?",
  ui_story_5075_50750201_98_dialog_content = "*suspiros* Estoy bien y sin daño, no te preocupes.",
  ui_story_5075_50750201_99_dialog_content = "Pero el rey te castigará de nuevo si descubre que te has ido sin ningún guardia de escolta.",
  ui_story_5075_50750201_100_dialog_content = "¡Ya soy mayor! ¡N-No tengo miedo del castigo!",
  ui_story_5075_50750201_101_dialog_content = "Además, como un verdadero hombre, ¡debo estar allí para mi prometida en tiempos de crisis!",
  ui_story_5075_50750201_102_dialog_content = "No—",
  ui_story_5075_50750201_103_dialog_content = "¿Cómo puedes decir eso—",
  ui_story_5075_50750201_104_dialog_content = "¿Oh? ¿Un hombre de verdad? Parece que he pasado por alto algo.",
  ui_story_5075_50750201_105_dialog_content = "Tu carga de estudio está actualmente al nivel de los niños, pero como ya eres un hombre de verdad, bueno...",
  ui_story_5075_50750201_106_dialog_content = "¡Tendré que decirle al profesor que tu tarea es demasiado ligera y necesitamos duplicarla a partir de ahora!",
  ui_story_5075_50750201_107_dialog_content = "¡No... Por favor no! Lo admito... ¡Aún no he crecido para ser un hombre de verdad!",
  ui_story_5075_50750201_108_dialog_content = "P-Puede que tenga altas aspiraciones, ¡pero mi cuerpo y mente no están completamente desarrollados para tal carga!",
  ui_story_5075_50750201_109_dialog_content = "... Ya tuve suficiente por hoy. Voy a volver a descansar.",
  ui_story_5075_50750201_110_dialog_content = "Dantang, ¡pasemos el rato juntos de nuevo mañana!",
  ui_story_5075_50750201_111_dialog_content = "Contratamos a un nuevo chef que es experto en la cocina Ye. Papá te invitó a un banquete mañana.",
  ui_story_5075_50750201_112_dialog_content = "¡Tienes que venir!",
  ui_story_5075_50750201_113_dialog_content = "*suspira*",
  ui_story_5075_50750201_114_dialog_content = "Gracias por su ayuda, señor, o el príncipe nunca volvería.",
  ui_story_5075_50750201_115_dialog_content = "Este es el Asesor Principal del Rey del Reino de Ji, PlayerName.",
  ui_story_5075_50750201_116_dialog_content = "Y mi mentor también.",
  ui_story_5075_50750201_117_dialog_content = "Puedo prosperar en Ji gracias a su ayuda y orientación.",
  ui_story_5075_50750201_118_dialog_content = "(¿Es realmente tan importante? Espera, ¿cómo suelen mostrar su respeto las personas en Longzhou?)",
  ui_story_5075_50750201_119_dialog_content = "¡Bueno verte, señor!",
  ui_story_5075_50750201_120_dialog_content = "Señor, este es PlayerName de Astra, a quien creo que vio durante el banquete.",
  ui_story_5075_50750201_121_dialog_content = "Hmm, estoy profundamente impresionado.",
  ui_story_5075_50750201_122_dialog_content = "(Sí, definitivamente es el maestro de Dantang. Su mirada me pone aún más nervioso que una sala entera de gente mirando...)",
  ui_story_5075_50750201_123_dialog_content = "¿Eh? Esa marca en la carta que estás sosteniendo...",
  ui_story_5075_50750201_124_dialog_content = "Un informe urgente de la Oficina de Inspección.",
  ui_story_5075_50750201_125_dialog_content = "¿Es del escuadrón enviado apresuradamente para defender la bahía debido al aumento de la presencia de Eclipsites?",
  ui_story_5075_50750201_126_dialog_content = "Ahora, temo que sus oponentes son más que solo espíritus malvados.",
  ui_story_5075_50750201_127_dialog_content = "Según el informe urgente, justo después del terremoto, los demonios cerca del mar de repente se volvieron locos y comenzaron a hacer daño a las personas.",
  ui_story_5075_50750201_128_dialog_content = "Aunque las patrullas intervinieron a tiempo y los detuvieron, me temo que este puede no ser un incidente aislado.",
  ui_story_5075_50750201_129_dialog_content = "¿Demonios frenéticos? ¿Pero cómo? ¿Hay algo más en el terremoto que simplemente ser un desastre natural?",
  ui_story_5075_50750202_1_dialog_content = "Por eso vine aquí, esperando que puedas investigarlo por nosotros.",
  ui_story_5075_50750202_2_dialog_content = "Por supuesto, mañana yo...",
  ui_story_5075_50750202_3_dialog_content = "¿No se supone que debes cuidar al príncipe para el rey de nuevo mañana?",
  ui_story_5075_50750202_4_dialog_content = "Bueno, mmm...",
  ui_story_5075_50750202_5_dialog_content = "¿Hay algo que pueda hacer para ayudar?",
  ui_story_5075_50750202_6_dialog_content = "Dantang puede que no tenga tiempo libre, pero yo sí. Si todo lo que necesitas es alguien para investigar, puedo encargarme de eso perfectamente.",
  ui_story_5075_50750202_7_dialog_content = "No. Ya es un gran favor de tu parte venir como emisario, PlayerName.",
  ui_story_5075_50750202_8_dialog_content = "¿Cómo podemos cargarte con los asuntos de Ji?",
  ui_story_5075_50750202_9_dialog_content = "Creo que es factible.",
  ui_story_5075_50750202_10_dialog_content = "¿Señor?",
  ui_story_5075_50750202_11_dialog_content = "He revisado la propuesta de intercambio de Zhuohua.",
  ui_story_5075_50750202_12_dialog_content = "Pero en la corte real, está claro que al rey no le agrada la idea de una ejecución inmediata.",
  ui_story_5075_50750202_13_dialog_content = "Qué pena.",
  ui_story_5075_50750202_14_dialog_content = "PlayerName, siendo un emisario, debes apreciar otra oportunidad para persuadir al rey.",
  ui_story_5075_50750202_15_dialog_content = "Es correcto.",
  ui_story_5075_50750202_16_dialog_content = "Mucha gente me ayudó a llegar hasta aquí, y tantos cuentan conmigo. Me niego a volver con las manos vacías.",
  ui_story_5075_50750202_17_dialog_content = "Bueno, esta es una oportunidad de oro.",
  ui_story_5075_50750202_18_dialog_content = "A medida que el Festival de Primavera está a la vuelta de la esquina, la ciudad está llena de gente, junto con diversas actividades.",
  ui_story_5075_50750202_19_dialog_content = "Entonces, cualquier problema causado por espíritus malvados y demonios podría llevar a consecuencias graves y daño a los ciudadanos.",
  ui_story_5075_50750202_20_dialog_content = "Y cuando eso suceda, si alguien pudiera resolverlo pronto, sería una acción meritoria.",
  ui_story_5075_50750202_21_dialog_content = "El rey seguramente otorgará recompensas donde se deben.",
  ui_story_5075_50750202_22_dialog_content = "En realidad, no me importan mucho las recompensas. Después de todo, ni siquiera sé qué hacer con la pila de regalos que tengo en la casa de huéspedes...",
  ui_story_5075_50750202_23_dialog_content = "Pero si es posible, me gustaría mucho aprovechar esta oportunidad para compartir nuestro plan con el rey.",
  ui_story_5075_50750202_24_dialog_content = "Así que por favor, déjeme esta tarea a mí, señor.",
  ui_story_5075_50750202_25_dialog_content = "Tengo otra solicitud, y si estás de acuerdo, dejaré este asunto en tus manos.",
  ui_story_5075_50750202_26_dialog_content = "¿Qué es?",
  ui_story_5075_50750202_27_dialog_content = "... Intenta mantener un perfil bajo durante tu investigación, y no dejes que nadie en la corte real se entere de esto.",
  ui_story_5075_50750202_28_dialog_content = "Señor, PlayerName es de otro país y no está familiarizado con el Reino Ji, mucho menos para llevar a cabo una misión solo.",
  ui_story_5075_50750202_29_dialog_content = "Nunca dije que PlayerName debería manejarlo solo.",
  ui_story_5075_50750202_30_dialog_content = "¿No captas mi indirecta, eh? Zhuohua, estás siendo demasiado impaciente.",
  ui_story_5075_50750202_31_dialog_content = "...",
  ui_story_5075_50750202_32_dialog_content = "Está bien, Dantang.",
  ui_story_5075_50750202_33_dialog_content = "He realizado muchos trabajos que me han llevado a lugares desconocidos en Astra. Por muy duros que fueran esos trabajos, obtuve mucha experiencia en este tipo de cosas.",
  ui_story_5075_50750202_34_dialog_content = "Bien.",
  ui_story_5075_50750202_35_dialog_content = "Zhuohua, acompaña a nuestro joven invitado fuera del palacio.",
  ui_story_5075_50750202_36_dialog_content = "Ciertamente...",
  ui_story_5075_50750202_37_dialog_content = "PlayerName—",
  ui_story_5075_50750202_38_dialog_content = "Solo para que lo sepas, no escucharé si vas a disculparte o intentar convencerme de lo contrario.",
  ui_story_5075_50750202_39_dialog_content = "Pero si te hacen correr así mientras yo me quedo en el palacio...",
  ui_story_5075_50750202_40_dialog_content = "Pero la comida es deliciosa en el banquete.",
  ui_story_5075_50750202_41_dialog_content = "?",
  ui_story_5075_50750202_42_dialog_content = "¿No crees que es muchas veces mejor que la comida en Twin Pavilions Bay?",
  ui_story_5075_50750202_43_dialog_content = "Sí, ya que están preparados por el chef real.",
  ui_story_5075_50750202_44_dialog_content = "En otras palabras, no somos nosotros los que lo hicimos. Tampoco sembramos el arroz, ¿verdad?",
  ui_story_5075_50750202_45_dialog_content = "Por supuesto, es de los agricultores locales.",
  ui_story_5075_50750202_46_dialog_content = "¿Entonces lo enviamos a la ciudad?",
  ui_story_5075_50750202_47_dialog_content = "No, las casas de comercio en todo el país son responsables de eso.",
  ui_story_5075_50750202_48_dialog_content = "¿Lo compramos nosotros mismos?",
  ui_story_5075_50750202_49_dialog_content = "No, esa es la tarea del tesorero real.",
  ui_story_5075_50750202_50_dialog_content = "Y sin embargo, no te preocupaba molestarlos, ni ofreciste hacer estas cosas por ellos.",
  ui_story_5075_50750202_51_dialog_content = "... No soy tan engreído como para creer que puedo hacer sus trabajos.",
  ui_story_5075_50750202_52_dialog_content = "Esta tarea tampoco es diferente.",
  ui_story_5075_50750202_53_dialog_content = "Nadie puede hacer todo por sí mismo. Si no estás libre para hacer algo mientras yo tengo tanto el tiempo como la habilidad, debería ser yo quien lo haga.",
  ui_story_5075_50750202_54_dialog_content = "Molestar a los demás, depender de los demás, así es como funciona este mundo.",
  ui_story_5075_50750202_55_dialog_content = "Por supuesto, si crees que no soy capaz de manejar el trabajo...",
  ui_story_5075_50750202_56_dialog_content = "¡Yo nunca!",
  ui_story_5075_50750202_57_dialog_content = "... Sabes, estás mejor preparado para ser un debatiente que un emisario, PlayerName.",
  ui_story_5075_50750202_58_dialog_content = "Por mucho sentido que hayas hecho, sería sabio que me rindiera.",
  ui_story_5075_50750202_59_dialog_content = "Jaja, si tu lo dices...",
  ui_story_5075_50750202_60_dialog_content = "Es maravilloso que te veas mucho mejor que cuando nos fuimos.",
  ui_story_5075_50750202_61_dialog_content = "Ejem. ¿Era tan obvio?",
  ui_story_5075_50750202_62_dialog_content = "Es por mi culpa que te estresaste demasiado, por las relaciones diplomáticas, las secuelas del terremoto...",
  ui_story_5075_50750202_63_dialog_content = "Sin mencionar la preocupación por la posibilidad de que me hayan hecho algo malo, estás tan estresado que no has sido tú mismo últimamente.",
  ui_story_5075_50750202_64_dialog_content = "¿Así que crees que me preocupo por demasiadas cosas?",
  ui_story_5075_50750202_65_dialog_content = "Apenas, lo tomé más como un consejo amistoso.",
  ui_story_5075_50750202_66_dialog_content = "Por tu bien, debo levantarme y resolver los problemas lo antes posible.",
  ui_story_5075_50750202_67_dialog_content = "¡Bien, entonces hagamos lo mejor que podamos juntos! Incluso si no estamos exactamente luchando en el mismo frente—",
  ui_story_5075_50750202_68_dialog_content = "Aún podemos trabajar juntos y alcanzar nuestros objetivos.",
  ui_story_5075_50750202_69_dialog_content = "Estimado emisario, estoy aquí para acompañarte de regreso.",
  ui_story_5075_50750202_70_dialog_content = "Oh, hola de nuevo. ¿Estás aquí solo para acompañarme de vuelta?",
  ui_story_5075_50750202_71_dialog_content = "Por supuesto. Mientras estés en el Reino Ji, eres un invitado de honor de nuestra Casa Real de Huéspedes, y no seremos negligentes en nuestros deberes.",
  ui_story_5075_50750202_72_dialog_content = "Parece que es hora de que me vaya. ¡Te mantendré informado, Dantang!",
  ui_story_5075_50750202_73_dialog_content = "Entonces esperaré tus buenas noticias en el palacio.",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>Momentos después—</color>",
  ui_story_5075_50750202_75_dialog_content = "¿Su Alteza? ¿Qué hace aquí parado solo?",
  ui_story_5075_50750202_76_dialog_content = "Oh, has vuelto, Jiu. ¿Cómo va eso de lo que hablamos?",
  ui_story_5075_50750202_77_dialog_content = "Todavía estoy trabajando duro en ello.",
  ui_story_5075_50750202_78_dialog_content = "Pero todavía hay numerosos agentes secretos activos en Haojin.",
  ui_story_5075_50750202_79_dialog_content = "Así que por favor ten cuidado cuando no esté cerca.",
  ui_story_5075_50750202_80_dialog_content = "Entendido. Bien hecho, Jiu.",
  ui_story_5075_50750202_81_dialog_content = "Me quedaré en el palacio en el futuro previsible, así que no espero ningún peligro.",
  ui_story_5075_50750202_82_dialog_content = "Oh, recuérdame escribir una carta cuando regresemos.",
  ui_story_5075_50750202_83_dialog_content = "Incluso el Capitán Yuebai ha entregado todos los envíos y está de vuelta en Haojin...",
  ui_story_5075_50750202_84_dialog_content = "Una cierta Ministra Armilla no ha estado en contacto, excepto por un mensaje críptico desde que tocó tierra...",
  ui_story_5075_50750202_85_dialog_content = "Veo que tendré que regañarla yo mismo.",
  ui_story_5075_50750202_86_dialog_content = "¿Mmm?",
  ui_story_5075_50750202_87_dialog_content = "¿Qué pasa, Su Alteza?",
  ui_story_5075_50750202_88_dialog_content = "Tranquilo. Solo estoy un poco sorprendido.",
  ui_story_5075_50750202_89_dialog_content = "Se siente como si las flores de este ciruelo hubieran florecido en un abrir y cerrar de ojos.",
  ui_story_5075_50750202_90_dialog_content = "¿Pero no prefieres solo las begonias?",
  ui_story_5075_50750202_91_dialog_content = "Sí, pero también encuentro que las flores de ciruelo de hoy son deliciosas.",
  ui_story_5075_50750301_1_dialog_content = "(A pesar de que estaba lleno de confianza cuando acepté hacer esta investigación...)",
  ui_story_5075_50750301_2_dialog_content = "(¡No esperaba encontrarme con un obstáculo tan grande de inmediato!)",
  ui_story_5075_50750301_3_dialog_content = "Oye... Toda esta protección es algo innecesaria, ¿no crees? Solo quería hacer un poco de compras.",
  ui_story_5075_50750301_4_dialog_content = "Su Excelencia, considerando su distinguido estatus, seis guardias son solo la medida de seguridad básica, nada especial.",
  ui_story_5075_50750301_5_dialog_content = "Ya he solicitado agregar nueve guardias más para garantizar tu seguridad.",
  ui_story_5075_50750301_6_dialog_content = "¿Más guardias?",
  ui_story_5075_50750301_7_dialog_content = "No importa, tengo algo más importante que preguntar...",
  ui_story_5075_50750301_8_dialog_content = "¿Por qué no hay una sola persona en esta calle?",
  ui_story_5075_50750301_9_dialog_content = "Para evitar cualquier interrupción no deseada en su ocio, hemos despejado el área con anticipación.",
  ui_story_5075_50750301_10_dialog_content = "¡Pero eso simplemente arruina toda la experiencia!",
  ui_story_5075_50750301_11_dialog_content = "¡Eres demasiado sobreprotector de cualquier manera que lo veas!",
  ui_story_5075_50750301_12_dialog_content = "(Si ni siquiera puedo hablar con alguien aquí afuera, mi investigación terminará antes de comenzar.)",
  ui_story_5075_50750301_13_dialog_content = "... No necesitas molestarte. Yo lo entregaré por ti.",
  ui_story_5075_50750301_14_dialog_content = "(¿Eh? ¿Alguien hablando afuera?)",
  ui_story_5075_50750301_15_dialog_content = "El palacio me dijo que entregara esto al emisario en persona. Por favor, no me lo pongas difícil.",
  ui_story_5075_50750301_16_dialog_content = "Si ese es el caso, por favor entra.",
  ui_story_5075_50750301_17_dialog_content = "Saludos, Su Excelencia.",
  ui_story_5075_50750301_18_dialog_content = "Estas son golosinas preparadas por el nuevo chef del palacio. A los nobles les parecen bastante sabrosas.",
  ui_story_5075_50750301_19_dialog_content = "Así que me enviaron para traerte algunos para que los pruebes.",
  ui_story_5075_50750301_20_dialog_content = "Gracias. ¿Eh? Todavía está tibio.",
  ui_story_5075_50750301_21_dialog_content = "A pesar del clima templado de Haojin, todavía es invierno.",
  ui_story_5075_50750301_22_dialog_content = "Entonces, hay un calentador debajo del contenedor de comida para mantener todo caliente y sabroso para ti.",
  ui_story_5075_50750301_23_dialog_content = "El calentador de allí utiliza una nueva técnica importada del Reino Ye.",
  ui_story_5075_50750301_24_dialog_content = "Y su estilo está meticulosamente diseñado, con artesanos hábiles tallando flores en el interior, lo que lo convierte en un adorno adecuado.",
  ui_story_5075_50750301_25_dialog_content = "¿En el interior? ¿Por qué hacer tallas tan intrincadas en un lugar donde nadie puede verlas?",
  ui_story_5075_50750301_26_dialog_content = "Bueno, ellos dijeron... es más fácil manejar las cosas donde no son visibles.",
  ui_story_5075_50750301_27_dialog_content = "¿Qué?",
  ui_story_5075_50750301_28_dialog_content = "Solo estaba murmurando para mí mismo. Tómate tu tiempo y disfruta, estimado emisario. Regresaré al palacio e informaré.",
  ui_story_5075_50750301_29_dialog_content = "Estimado emisario, ¿te gustaría algunos bocadillos ahora? ¿O hay algo más que necesites?",
  ui_story_5075_50750301_30_dialog_content = "No, gracias. Estoy un poco cansado, así que creo que solo tomaré una siesta por ahora. Ustedes pueden ir.",
  ui_story_5075_50750301_31_dialog_content = "Oh, puedes dejar la comida justo aquí. La comeré cuando me despierte.",
  ui_story_5075_50750301_32_dialog_content = "Sí, Su Excelencia.",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>El calentador está emitiendo un ligero humo, y a través de las piezas de cobre entrelazadas, puedes ver las llamas parpadeando en el interior.</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>Justo cuando las llamas dentro de la estufa se apagan, las piezas de cobre que previamente estaban entrelazadas de repente se separan.</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>Entonces, se despliegan en una pequeña y delicada flor de begonia.</color>",
  ui_story_5075_50750301_37_dialog_content = "Hay una insignia escondida dentro, ¿también hay una nota?",
  ui_story_5075_50750301_38_dialog_content = "May disfrute de buena salud durante su estancia en Ji para aliviar la ansiedad de la Princesa Zhuohua, Su Excelencia.",
  ui_story_5075_50750301_39_dialog_content = "¡Estaba entregando un mensaje secreto de Dantang!",
  ui_story_5075_50750301_40_dialog_content = "(La insignia pertenece a esa \"Oficina de Inspección\", supongo, pero no sé qué hacer con ella en este momento.)",
  ui_story_5075_50750301_41_dialog_content = "(¿Es un mapa? ¡Con una dirección aún!)",
  ui_story_5075_50750301_42_dialog_content = "(¡Las sirvientas resulta que están fuera ahora mismo! ¡Esta es mi oportunidad!)",
  ui_story_5075_50750301_43_option_content = "Escaneo psíquico",
  ui_story_5075_50750301_44_dialog_content = "(Puedo sentir a dos guardias al este y tres al sur... Así que parece que voy al oeste.)",
  ui_story_5075_50750301_45_dialog_content = "¡Oye, muévete rápido! ¡El emisario está desaparecido!",
  ui_story_5075_50750301_46_dialog_content = "Tú quédate aquí. Iré allá para ver si puedo encontrar algo.",
  ui_story_5075_50750301_47_dialog_content = "(Eso no tomó mucho tiempo, pero afortunadamente llegué al borde del patio. Ahora solo tengo que saltar estas paredes...)",
  ui_story_5075_50750301_48_dialog_content = "... ¡Son demasiado altos!",
  ui_story_5075_50750301_49_dialog_content = "¡Estimado emisario! ¡Estimado emisario!",
  ui_story_5075_50750301_50_dialog_content = "(¡Estaré rodeado en cualquier momento! Tengo que pensar en algo...)",
  ui_story_5075_50750301_51_dialog_content = "¿Estás jugando al escondite?",
  ui_story_5075_50750301_52_dialog_content = "¿Ah?",
  ui_story_5075_50750301_53_dialog_content = "¡Aquí!",
  ui_story_5075_50750301_54_dialog_content = "Mira hacia arriba.",
  ui_story_5075_50750301_55_dialog_content = "¿Un pequeño niño? ¿Qué haces en la cima de la pared? ¡Es peligroso allí arriba!",
  ui_story_5075_50750301_56_dialog_content = "No es peligroso en absoluto. Incluso puedo caminar sobre una cuerda.",
  ui_story_5075_50750301_57_dialog_content = "¿Así que estás jugando al escondite? Yo también quiero jugar.",
  ui_story_5075_50750301_58_dialog_content = "No estoy jugando...",
  ui_story_5075_50750301_59_dialog_content = "¿Estimado emisario? ¿Estás aquí?",
  ui_story_5075_50750301_60_dialog_content = "¡Uh-oh! Lo siento, pero tengo que irme—",
  ui_story_5075_50750301_61_dialog_content = "!",
  ui_story_5075_50750301_62_dialog_content = "¡Oh, eh... Solo iba a dar un paseo!",
  ui_story_5075_50750301_63_dialog_content = "¿Emisario? ¿Estás por aquí?",
  ui_story_5075_50750301_64_dialog_content = "?",
  ui_story_5075_50750301_65_dialog_content = "Tampoco está aquí. ¿A dónde se fue?",
  ui_story_5075_50750301_66_dialog_content = "Emissario—",
  ui_story_5075_50750301_67_dialog_content = "Y dijiste que no estabas jugando.",
  ui_story_5075_50750301_68_dialog_content = "Ese guardia no me vio en absoluto hace un momento. ¿Hiciste esto tú?",
  ui_story_5075_50750301_69_dialog_content = "Jeje. Tal vez un poco.",
  ui_story_5075_50750301_70_dialog_content = "?",
  ui_story_5075_50750301_71_dialog_content = "?",
  ui_story_5075_50750301_72_dialog_content = "Un momento.",
  ui_story_5075_50750301_73_dialog_content = "¿No deberías estar asombrado por mi aura dominante y caer de rodillas ante el gran y majestuoso Chen'ni ya?",
  ui_story_5075_50750301_74_dialog_content = "Aura dominante...",
  ui_story_5075_50750301_75_dialog_content = "Uh, ¿qué te hace pensar que debería estar haciendo eso?",
  ui_story_5075_50750301_76_dialog_content = "¡Porque eso es lo que escuché del cuentacuentos en el puente en mi camino aquí!",
  ui_story_5075_50750301_77_dialog_content = "Dijo que esa es la tendencia actual. ¿No es así?",
  ui_story_5075_50750301_78_dialog_content = "No creo que eso sea exactamente de lo que él estaba hablando...",
  ui_story_5075_50750301_79_dialog_content = "Como sea—",
  ui_story_5075_50750301_80_dialog_content = "Definitivamente escuché algo sucediendo aquí.",
  ui_story_5075_50750301_81_dialog_content = "Pero acabo de comprobar... Bueno, solo para estar seguros, vamos a comprobarlo de nuevo.",
  ui_story_5075_50750301_82_dialog_content = "¡Juguemos una partida de escondite!",
  ui_story_5075_50750301_83_dialog_content = "Solo necesito algo de ayuda para salir de aquí primero. ¿Crees que puedes hacer eso, gran y majestuoso Chen'ni?",
  ui_story_5075_50750301_84_dialog_content = "¡Oh, seguro que tienes una lengua simplista para ser un niño!",
  ui_story_5075_50750301_85_dialog_content = "Relájate. Soy un experto en este juego. ¡No te equivocarás con Chen'ni!",
  ui_story_5075_50750301_86_dialog_content = "¡El secreto es ir a toda velocidad!",
  ui_story_5075_50750302_1_dialog_content = "Puff... Puff...",
  ui_story_5075_50750302_2_dialog_content = "Estoy empezando a pensar... que realmente no sabes cómo jugar al escondite...",
  ui_story_5075_50750302_3_dialog_content = "Eso es imposible.",
  ui_story_5075_50750302_4_dialog_content = "Mira, aquí estamos fuera de la puerta.",
  ui_story_5075_50750302_5_dialog_content = "Y nadie nos atrapó todo este tiempo.",
  ui_story_5075_50750302_6_dialog_content = "Estoy diciendo que no se supone que debas correr así durante el escondite...",
  ui_story_5075_50750302_7_dialog_content = "Y el hecho de que nadie nos vio en absoluto significa que de alguna manera hiciste trampa.",
  ui_story_5075_50750302_8_dialog_content = "... De nuevo, supongo que eso significa que también hice trampa.",
  ui_story_5075_50750302_9_dialog_content = "De todos modos, gracias de nuevo, Chen'ni... quiero decir, ¡el gran y majestuoso Chen'ni!",
  ui_story_5075_50750302_10_dialog_content = "Bueno, ya que fuiste lo suficientemente amable para jugar conmigo, podemos omitir el honorífico.",
  ui_story_5075_50750302_11_dialog_content = "Claro, Chen'ni. Por cierto, mi nombre es PlayerName. Yo soy—",
  ui_story_5075_50750302_12_dialog_content = "Un Celestita.",
  ui_story_5075_50750302_13_dialog_content = "Lo se.",
  ui_story_5075_50750302_14_dialog_content = "¿Ah?",
  ui_story_5075_50750302_15_dialog_content = "¿Emisario? ¿Eres tú el que está ahí?",
  ui_story_5075_50750302_16_dialog_content = "Debería salir de aquí mientras aún pueda.",
  ui_story_5075_50750302_17_dialog_content = "¡Estimado emisario, realmente eres tú!",
  ui_story_5075_50750302_18_dialog_content = "¿Por qué saliste sin guardias? Es demasiado arriesgado.",
  ui_story_5075_50750302_19_dialog_content = "¡Guardias!",
  ui_story_5075_50750302_20_dialog_content = "Espera, yo no—",
  ui_story_5075_50750302_21_dialog_content = "¡Chirrido!",
  ui_story_5075_50750302_22_dialog_content = "¡Ahh—una rata! ¡H-Ayuda!",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5075_50750302_24_dialog_content = "¡Ahhh! Es un diabólico... ¡Un diabólico nos está atacando!",
  ui_story_5075_50750302_25_dialog_content = "... Silencio, no seas tan ruidoso.",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>Ruido sordo.</color>",
  ui_story_5075_50750302_27_dialog_content = "¿Qué has hecho, Chen'ni?",
  ui_story_5075_50750302_28_dialog_content = "Hazla dormir un poco.",
  ui_story_5075_50750302_29_dialog_content = "Ese es el siguiente.",
  ui_story_5075_50750302_30_dialog_content = "Chirrido...",
  ui_story_5075_50750302_31_dialog_content = "Definitivamente no es una rata ordinaria...",
  ui_story_5075_50750302_32_dialog_content = "Este debe ser uno de esos fiendlings de los que Liqing y los demás me hablaron. Un fiendling que no logró tomar una forma adecuada.",
  ui_story_5075_50750302_33_dialog_content = "Algo de eso me hace sentir realmente incómodo... Es frenético, ¿no es así?",
  ui_story_5075_50750302_X33_dialog_content = "Según el informe urgente, justo después del terremoto, los demonios cerca del mar de repente se volvieron locos y comenzaron a hacer daño a las personas.",
  ui_story_5075_50750302_34_dialog_content = "¿Podrías decirlo?",
  ui_story_5075_50750302_35_dialog_content = "Entonces también debes poder ver esto.",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>Las yemas de los dedos de Chen'ni rozan al demonio caído, extrayendo una sombra oscura de su cuerpo.</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>Es como una neblina turbia, con un toque vago de malicia que se acumula.</color>",
  ui_story_5075_50750302_38_option_content = "Prueba la telepatía",
  ui_story_5075_50750302_39_dialog_content = "Odio...",
  ui_story_5075_50750302_40_dialog_content = "Ay—",
  ui_story_5075_50750302_41_dialog_content = "Me duele cuando uso mis poderes en ello, como si estuviera tocando un líquido corrosivo... ¿Qué es?",
  ui_story_5075_50750302_42_dialog_content = "Una plaga persistente y podrida.",
  ui_story_5075_50750302_43_dialog_content = "¡Cuidado, está empezando a moverse! ¡Podría intentar escapar!",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>Pero la chica ni siquiera parpadea.</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>Un simple pellizco y giro de Chen'ni, y la amenazante niebla negra se dispersa en el aire como una llama sofocada.</color>",
  ui_story_5075_50750302_46_dialog_content = "Vamos, no me salté la hora de dormir y vine aquí para este tipo de problemas.",
  ui_story_5075_50750302_47_dialog_content = "Ve a jugar solo, PlayerName. Tengo otras cosas que hacer.",
  ui_story_5075_50750302_48_dialog_content = "Espera—",
  ui_story_5075_50750302_49_dialog_content = "¿Qué se supone que debo hacer con estos dos?",
  ui_story_5075_50750302_50_dialog_content = "Ups, olvidé este lío.",
  ui_story_5075_50750302_51_dialog_content = "Uf.",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>La chica sostiene a la sirvienta por el hombro y la \"vuela\" de regreso a la Casa de Huéspedes Real.</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>Entonces, agarrando la cola del demonio, la lanza lejos en el cielo.</color>",
  ui_story_5075_50750302_54_dialog_content = "¿Está realmente bien?",
  ui_story_5075_50750302_55_dialog_content = "Por supuesto. Los fiendlings no son tan débiles.",
  ui_story_5075_50750302_56_dialog_content = "Si no pueden soportar eso, sería mejor que olviden transformarse y permanezcan como un animal por el resto de sus vidas.",
  ui_story_5075_50750302_57_dialog_content = "Tuve esa sensación cuando usé mis poderos, y dado el comportamiento extraño...",
  ui_story_5075_50750302_58_dialog_content = "Tú también eres un diablillo, ¿verdad?",
  ui_story_5075_50750302_59_dialog_content = "¿Chen'ni? Oye, ¿a dónde fuiste?",
  ui_story_5075_50750302_60_dialog_content = "Todavía quería preguntarle sobre esa bola de niebla negra... Bueno, no importa.",
  ui_story_5075_50750302_61_dialog_content = "Tal vez me encuentre con ella de nuevo durante mi investigación.",
  ui_story_5075_50750302_62_dialog_content = "Por ahora, debería comenzar revisando esta dirección.",
  ui_story_5075_50750302_63_dialog_content = "...",
  ui_story_5075_50750401_1_dialog_content = "Es nuevamente el Festival de Primavera. ¡Ven y prueba nuestras dulces mandarinas de la fortuna!",
  ui_story_5075_50750401_2_dialog_content = "¡Toma unas mandarinas de la fortuna! Vamos, te pelaré una. No te cobraré si no está dulce.",
  ui_story_5075_50750401_3_dialog_content = "¡Semillas de sésamo, semillas de melón y frutas cubiertas de azúcar! ¡Todo hecho de formas probadas en el tiempo! Joven, ¿por qué no vienes a echar un vistazo?",
  ui_story_5075_50750401_4_dialog_content = "Es tan animado aquí. Caminar por las calles solo se siente completamente diferente.",
  ui_story_5075_50750401_5_dialog_content = "Disculpe, pero ¿sabe cómo llegar a la calle Yulin?",
  ui_story_5075_50750401_6_dialog_content = "Está un poco lejos. Deberías dirigirte hacia el puente más concurrido primero, luego preguntar a alguien más después de cruzar la intersección.",
  ui_story_5075_50750401_7_dialog_content = "Gracias. Hay tanta gente allí.",
  ui_story_5075_50750401_8_dialog_content = "¿Primera vez aquí? La ciudad de Haojin organiza ferias cada Festival de Primavera, eso es un gran éxito.",
  ui_story_5075_50750401_9_dialog_content = "Está justo en esa calle.",
  ui_story_5075_50750401_10_dialog_content = "Habrá actores famosos actuando más tarde. Definitivamente deberías ir a ver si no tienes prisa o algo así.",
  ui_story_5075_50750401_11_dialog_content = "Claro, echaré un vistazo cuando tenga tiempo.",
  ui_story_5075_50750401_12_dialog_content = "Oh, elegiste el momento equivocado para venir. Este lugar solía ser aún más animado en años anteriores.",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50750401_14_dialog_content = "¿Qué fue ese ruido?",
  ui_story_5075_50750401_15_dialog_content = "Oh, los niños se divierten jugando con petardos.",
  ui_story_5075_50750401_16_dialog_content = "Este no es lo suficientemente fuerte. ¡Consigue otro!",
  ui_story_5075_50750401_17_dialog_content = "¡Los petardos estallan, ahuyentando a los demonios, desterrando la mala suerte de una manera alegre!",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>Aplastar, aplastar!</color>",
  ui_story_5075_50750401_19_dialog_content = "¡Jajajaja!",
  ui_story_5075_50750401_20_dialog_content = "Chirrido...",
  ui_story_5075_50750401_21_dialog_content = "¿Es esto lo que consideras divertido? ¡Hacer estallar fuegos artificiales en una calle concurrida como esta es peligroso!",
  ui_story_5075_50750401_22_dialog_content = "Ese fiundling tampoco se está volviendo frenético... De hecho, parece completamente inofensivo!",
  ui_story_5075_50750401_23_dialog_content = "No es gran cosa. Verás, incluso para un Festival de Primavera ordinario, existe la tradición de usar petardos para ahuyentar a los fiendlings.",
  ui_story_5075_50750401_24_dialog_content = "La única diferencia es que antes solían contratar actores para interpretar a los diablillos, y estos niños están lidiando con uno real.",
  ui_story_5075_50750401_25_dialog_content = "No tomé este ritual en serio antes, pero últimamente, las cosas se han vuelto inquietas.",
  ui_story_5075_50750401_26_dialog_content = "Quizás los fiendlings son de hecho un poco siniestros.",
  ui_story_5075_50750401_27_dialog_content = "Aunque seas un recién llegado, te aconsejaría que te mantengas alejado de esas cosas. Lamentablemente, me voy ahora.",
  ui_story_5075_50750401_28_dialog_content = "¿Por qué no se mueve en absoluto? ¿Ya está muerto?",
  ui_story_5075_50750401_29_dialog_content = "¿Deberíamos intentar otra explosión?",
  ui_story_5075_50750401_30_dialog_content = "¡Basta ya! Ustedes niños se están pasando demasiado con esto.",
  ui_story_5075_50750401_31_dialog_content = "!",
  ui_story_5075_50750401_32_dialog_content = "(¡La niebla negra otra vez! ¡Y está sofocando al demonio!)",
  ui_story_5075_50750401_33_dialog_content = "¡Salgan de aquí, niños!",
  ui_story_5075_50750401_34_dialog_content = "¿Eh? ¿Por qué?",
  ui_story_5075_50750401_35_dialog_content = "...",
  ui_story_5075_50750401_36_dialog_content = "Este... parece un poco fuera de lugar, ¿no crees?",
  ui_story_5075_50750401_37_dialog_content = "¡Chirrido!",
  ui_story_5075_50750401_38_dialog_content = "Oh no, es demasiado tarde—",
  ui_story_5075_50750401_39_dialog_content = "¡Aquí viene un cabezazo!",
  ui_story_5075_50750401_40_dialog_content = "Chirrido-",
  ui_story_5075_50750401_41_dialog_content = "El demonio... Fue embestido hacia el cielo.",
  ui_story_5075_50750401_42_dialog_content = "¡Mantén la guardia alta! ¡Está regresando!",
  ui_story_5075_50750402_1_dialog_content = "Chirrido...",
  ui_story_5075_50750402_2_dialog_content = "Relájate, todo está bien ahora. Oye, deja de retorcerte o acabarás aún más herido.",
  ui_story_5075_50750402_3_dialog_content = "¡Chirrido! ¡Chirrido!",
  ui_story_5075_50750402_4_dialog_content = "Fuiste tú quien me ayudó hace un momento, ¿verdad? Muchas gracias, ¡eso fue un mando increíble!",
  ui_story_5075_50750402_5_dialog_content = "Lo vi justo ahora, la forma en que te adelantaste para salvar a este demonio. ¡Debes ser una persona realmente buena!",
  ui_story_5075_50750402_6_dialog_content = "Jaja... No hice mucho. Además, fuiste tú quien lo sometió.",
  ui_story_5075_50750402_7_dialog_content = "¡Y lo hiciste tan rápido también! No creo que nadie siquiera se haya dado cuenta de que algo había sucedido.",
  ui_story_5075_50750402_8_dialog_content = "Todo es parte de mi trabajo.",
  ui_story_5075_50750402_9_dialog_content = "Lo siento, aún no me he presentado. Mi nombre es Luo Song, y soy una especie de sacerdote errante.",
  ui_story_5075_50750402_10_dialog_content = "¡Chirrido!",
  ui_story_5075_50750402_11_dialog_content = "Principalmente solo viajo por la tierra, eliminando demonios de vez en cuando.",
  ui_story_5075_50750402_12_dialog_content = "¡Chirrido! ¡Chirrido!",
  ui_story_5075_50750402_13_dialog_content = "Algo ha estado agitando a los fiendlings en esta área recientemente, haciéndolos perder la cabeza y atacar a las personas indiscriminadamente.",
  ui_story_5075_50750402_14_dialog_content = "Vine aquí para investigar la causa de este extraño fenómeno, pero incluso una ciudad tan bien protegida como Haojin...",
  ui_story_5075_50750402_15_dialog_content = "¡Chirrido! ¡Chirrido!",
  ui_story_5075_50750402_16_dialog_content = "¿Hay algo malo con ese diablillo?",
  ui_story_5075_50750402_17_dialog_content = "Parece ser el caso. Desde que lo capturé, no ha dejado de intentar morderme o retorcerse para escapar.",
  ui_story_5075_50750402_18_dialog_content = "Míralo, PlayerName.",
  ui_story_5075_50750402_19_dialog_content = "Oh, esto no es nada. Después de todo, me gano la vida lidiando con diablillos todo el tiempo.",
  ui_story_5075_50750402_20_dialog_content = "Para un diabólico como este, todo lo que tienes que hacer es sostener tu pulgar e índice así...",
  ui_story_5075_50750402_21_dialog_content = "¡Y con un poco de presión, no puede escapar!",
  ui_story_5075_50750402_22_dialog_content = "Ya veo. ¡Debes ser realmente un profesional después de todo!",
  ui_story_5075_50750402_23_dialog_content = "... ¡Espera, eso no es lo que estaba preguntando!",
  ui_story_5075_50750402_24_dialog_content = "Déjame intentar sentirlo...",
  ui_story_5075_50750402_25_dialog_content = "Lo sabía. Esa extraña bola de niebla negra todavía está dentro del cuerpo del demonio.",
  ui_story_5075_50750402_26_dialog_content = "\"¿Extraña bola de niebla negra\"?",
  ui_story_5075_50750402_27_dialog_content = "¡Sí, puedo verlo! Apuesto a que esta niebla negra está haciendo que los demonios se descontrolen.",
  ui_story_5075_50750402_28_dialog_content = "Algo así está más allá de mi especialización. Probablemente se necesite el toque de un maestro para esto.",
  ui_story_5075_50750402_29_dialog_content = "¿A menos que creas que podemos vencer a esa niebla negra?",
  ui_story_5075_50750402_30_dialog_content = "Uh, probablemente no.",
  ui_story_5075_50750402_31_dialog_content = "Pero sí conocí a una chica antes—",
  ui_story_5075_50750402_32_dialog_content = "¡Ey! ¿Por qué de repente corrieron y se pararon aquí susurrando? ¿Qué pasa?",
  ui_story_5075_50750402_33_dialog_content = "Oh, casi olvido a este grupo de niños.",
  ui_story_5075_50750402_34_dialog_content = "Por no mencionar... nunca tuve la oportunidad de preguntar tu nombre.",
  ui_story_5075_50750402_35_dialog_content = "¿Yo? Soy PlayerName.",
  ui_story_5075_50750402_36_dialog_content = "Es un placer conocerte, PlayerName. ¿Te importaría cuidar a este chico por mí?",
  ui_story_5075_50750402_37_dialog_content = "¿Ah?",
  ui_story_5075_50750402_38_dialog_content = "¡Chirrido!",
  ui_story_5075_50750402_39_dialog_content = "¡Oye, no me lo lances así! ¡Vaya, este demonio es más fuerte de lo que parece!",
  ui_story_5075_50750402_40_dialog_content = "(¡Ni siquiera se movía en la mano de Luo Song antes! ¡Qué tan fuerte es, eh, deja de moverte!)",
  ui_story_5075_50750402_41_option_content = "¡Potencia de fuerza!",
  ui_story_5075_50750402_42_dialog_content = "Chirrido...",
  ui_story_5075_50750402_43_dialog_content = "Uf, eso es mejor.",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>¡Zas! ¡Zas! ¡Zas!</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>Luo Song castiga a los niños dandoles un golpecito en la cabeza.</color>",
  ui_story_5075_50750402_46_dialog_content = "(Con la fuerza de Luo Song, probablemente eso duele mucho...)",
  ui_story_5075_50750402_47_dialog_content = "Waaahhhh—",
  ui_story_5075_50750402_48_dialog_content = "¿Quién te crees que eres, golpeando nuestras cabezas así? ¡Duele!",
  ui_story_5075_50750402_49_dialog_content = "Luo Song es mi nombre. Ya sea que esté vagando por la tierra o lidiando con demonios, eso no cambia.",
  ui_story_5075_50750402_50_dialog_content = "Eso es porque no tengo nada que ocultar. Mis intenciones son rectas y honestas.",
  ui_story_5075_50750402_51_dialog_content = "Tú, por otro lado, tienes mucho que explicar a tus padres. ¿Cuáles son vuestros nombres?",
  ui_story_5075_50750402_52_dialog_content = "Encender fuegos artificiales en la calle para intimidar a los débiles e indefensos no es algo que pueda permitir, incluso para los niños.",
  ui_story_5075_50750402_53_dialog_content = "Yo, eh, mi nombre es...",
  ui_story_5075_50750402_54_dialog_content = "Espera, ¿por qué debería decírtelo?",
  ui_story_5075_50750402_55_dialog_content = "Mis padres dijeron que es porque estos diablillos traen mala suerte que los espíritus malvados han estado causando estragos últimamente.",
  ui_story_5075_50750402_56_dialog_content = "¡Estás con ellos, lo que significa que tampoco eres bueno!",
  ui_story_5075_50750402_57_dialog_content = "Suena a pura superstición para mí.",
  ui_story_5075_50750402_58_dialog_content = "Además, usar las palabras de otras personas para excusar tu mal comportamiento sigue siendo inaceptable.",
  ui_story_5075_50750402_59_dialog_content = "¿Has visto a algún diablillo trabajando junto con los espíritus malvados?",
  ui_story_5075_50750402_60_dialog_content = "Bueno... Aunque no lo hemos visto, este demonio sí que nos robó nuestro melón de azúcar!",
  ui_story_5075_50750402_61_dialog_content = "Todos contribuyeron con su dinero de bolsillo para comprarlo, pero en un instante, se fue.",
  ui_story_5075_50750402_62_dialog_content = "¡Por cierto!",
  ui_story_5075_50750402_63_dialog_content = "¡Los ladrones no son buenos, así que lo que hicimos es todo para mantener segura a la comunidad!",
  ui_story_5075_50750402_64_dialog_content = "Dijiste que se fue en un instante, entonces eso significa que nunca viste cómo robaba tus bocadillos en primer lugar.",
  ui_story_5075_50750402_65_dialog_content = "Pero esta criatura era lo único que merodeaba cerca. Si no es ella, ¿quién más podría ser?",
  ui_story_5075_50750402_66_dialog_content = "PlayerName.",
  ui_story_5075_50750402_67_dialog_content = "¿Podrías por favor revisar la boca de ese diablillo en busca de algún residuo azucarado?",
  ui_story_5075_50750402_68_dialog_content = "Déjame ver... No.",
  ui_story_5075_50750402_69_dialog_content = "Aparte de algo de barro y algunos cortes y moretones, no hay nada más en el cuerpo de este demonio.",
  ui_story_5075_50750402_70_dialog_content = "¡Eso no prueba que no fuera el ladrón!",
  ui_story_5075_50750402_71_dialog_content = "Quizás usó algo de magia, trasladando el melón de azúcar a otro lugar en un suspiro.",
  ui_story_5075_50750402_72_dialog_content = "Uh, no creo que sería robar dulces si tuvieran poderes como ese.",
  ui_story_5075_50750402_73_dialog_content = "¿Cómo es exactamente tu melón de azúcar?",
  ui_story_5075_50750402_74_dialog_content = "¿Cómo más podría verse? Solo blanco, redondo, como...",
  ui_story_5075_50750402_75_dialog_content = "¿Una mandarina de la fortuna pelada?",
  ui_story_5075_50750402_76_dialog_content = "¡Exactamente! Un melón de azúcar tan bueno y sabroso, los diablillos seguramente lo amarían.",
  ui_story_5075_50750402_77_dialog_content = "Lo compraste en el puesto de ese anciano en la calle, ¿verdad?",
  ui_story_5075_50750402_78_dialog_content = "Si tuvieras que juntar todo tu dinero para comprarlo, probablemente no podrías permitirte nada más después.",
  ui_story_5075_50750402_79_dialog_content = "Pero los niños son codiciosos, especialmente cuando se trata de bocadillos, y resulta que había un vendedor de mandarinas de la fortuna ofreciendo muestras gratuitas cerca.",
  ui_story_5075_50750402_80_dialog_content = "No me digas que no lo viste.",
  ui_story_5075_50750402_81_dialog_content = "Fuimos allí, ¿y qué?",
  ui_story_5075_50750402_82_dialog_content = "Mientras te comías sus mandarinas, ¿dónde pusiste tu melón de azúcar?",
  ui_story_5075_50750402_83_dialog_content = "Acabo de ponerlo justo al lado del puesto de frutas... ¡Oh!",
  ui_story_5075_50750402_84_dialog_content = "De hecho, este es nuestro melón de azúcar, mezclado con las mandarinas de la fortuna peladas.",
  ui_story_5075_50750402_85_dialog_content = "...",
  ui_story_5075_50750402_86_dialog_content = "Y así aparece la verdad.",
  ui_story_5075_50750402_87_dialog_content = "¿Qué tienen que decir por ustedes mismos ahora?",
  ui_story_5075_50750402_88_dialog_content = "Lo siento...",
  ui_story_5075_50750402_89_dialog_content = "La próxima vez que te encuentres en este tipo de situación, detente y considera primero.",
  ui_story_5075_50750402_90_dialog_content = "No pienses que puedes culpar a los diablillos por todas tus desgracias.",
  ui_story_5075_50750402_91_dialog_content = "Dime, ¿lastimar a un fiundling de esta manera traería de vuelta tu melón de azúcar?",
  ui_story_5075_50750402_92_dialog_content = "Debido a las supersticiones y estereotipos, tendemos a etiquetar las cosas que no entendemos como \"malvadas\" para poder atacarlas...",
  ui_story_5075_50750402_93_dialog_content = "Pero ese tipo de comportamiento no es mejor que un niño haciendo una rabieta.",
  ui_story_5075_50750402_94_dialog_content = "Esto no es un acto de heroísmo sino de cobardía. ¿Entiendes?",
  ui_story_5075_50750402_95_dialog_content = "Entiendo...",
  ui_story_5075_50750402_96_dialog_content = "Bien, ahora vete a casa y cuéntales a tus padres lo que pasó aquí hoy.",
  ui_story_5075_50750402_97_dialog_content = "Bien...",
  ui_story_5075_50750402_98_dialog_content = "¿Crees que realmente van a contarles a sus padres sobre esto?",
  ui_story_5075_50750402_99_dialog_content = "Probablemente no.",
  ui_story_5075_50750402_100_dialog_content = "Sé que mis palabras solo están abordando los síntomas del problema, no sus causas subyacentes.",
  ui_story_5075_50750402_101_dialog_content = "Pero los rumores pueden ser igual de dañinos. La idea de que los diablillos traen peligro y desgracia solo surgió porque suficientes personas hablaron de ello.",
  ui_story_5075_50750402_102_dialog_content = "Lo que digo es la verdad, y mientras siga diciendo la verdad, eventualmente surgirá algo de ello.",
  ui_story_5075_50750402_103_dialog_content = "Después de todo, la verdad es la verdad, y las mentiras son mentiras.",
  ui_story_5075_50750402_104_dialog_content = "Eres una persona bastante increíble, Luo Song.",
  ui_story_5075_50750402_105_dialog_content = "Incluso les ayudaste a encontrar su melón de azúcar en muy poco tiempo. ¡Fue como si hubieras visto personalmente todo lo que sucedió!",
  ui_story_5075_50750402_106_dialog_content = "Jaja, sobre eso...",
  ui_story_5075_50750402_107_dialog_content = "No lo vi yo mismo, pero alguien lo hizo.",
  ui_story_5075_50750402_108_dialog_content = "Hmm... ¿Te gustaría conocer a mi amigo?",
  ui_story_5075_50750402_109_dialog_content = "¡Rooooooor!",
  ui_story_5075_50750402_110_dialog_content = "¿Tu amigo es un diablillo?",
  ui_story_5075_50750402_111_dialog_content = "Su nombre es Ah Ding.",
  ui_story_5075_50750402_112_dialog_content = "Vio a esos niños perder su melón de azúcar antes y me contó todo al respecto.",
  ui_story_5075_50750402_113_dialog_content = "Tenía la intención de llevarlo para decirles la verdad a los niños de frente, pero un vendedor de figuritas de azúcar me detuvo.",
  ui_story_5075_50750402_114_dialog_content = "Me dijo que la gente aquí tiene una visión muy negativa de los fiendlings en este momento, y que traer a Ah Ding podría empeorar las cosas.",
  ui_story_5075_50750402_115_dialog_content = "Así que le dije a Ah Ding que me esperara aquí.",
  ui_story_5075_50750402_116_dialog_content = "El vendedor de figuritas de azúcar es quien me enseñó cómo acercarme a esos niños con la verdad.",
  ui_story_5075_50750402_117_dialog_content = "Cuando lo pienso, sus puntos de vista son perfectamente válidos.",
  ui_story_5075_50750402_118_dialog_content = "Debería ir a agradecerle y comprar algunas figuritas de azúcar para Ah Ding y sus amigos, que se esconden en otros lugares.",
  ui_story_5075_50750402_119_dialog_content = "Uh, ¿Luo Song? Sé que es una suposición, pero... ¿Es ese hombre de allí el \"vendedor de figuritas de azúcar\" del que estás hablando?",
  ui_story_5075_50750402_120_dialog_content = "¡Sí, ese es él!",
  ui_story_5075_50750402_121_dialog_content = "¿Podrías esperar aquí unos minutos mientras voy a saludar a mis pequeños amigos? Volveré pronto.",
  ui_story_5075_50750402_122_dialog_content = "...",
  ui_story_5075_50750402_123_dialog_content = "\"¿Vendedor de figuritas de azúcar\"?",
  ui_story_5075_50750402_124_dialog_content = "¡Sí, ese soy yo sin duda!",
  ui_story_5075_50750500_1_dialog_content = "... ¿No se supone que eres un adivino?",
  ui_story_5075_50750500_2_dialog_content = "No-no. Mira este sirope claro como el cristal.",
  ui_story_5075_50750500_3_dialog_content = "Luego mira la artesanía tan realista.",
  ui_story_5075_50750500_4_dialog_content = "Es posible solo con habilidades transmitidas durante generaciones más años de experiencia.",
  ui_story_5075_50750500_5_dialog_content = "Juro sobre la tumba de mi antepasado que soy un auténtico fabricante de figuritas de azúcar.",
  ui_story_5075_50750500_6_dialog_content = "Ha pasado bastante tiempo desde que nos separamos en Shadowind.",
  ui_story_5075_50750500_7_dialog_content = "El destino nos trajo a ambos aquí, ¿por qué no te ofrezco una figurita de azúcar gratis?",
  ui_story_5075_50750500_8_dialog_content = "No intento sospechar de ti ni nada por el estilo.",
  ui_story_5075_50750500_9_dialog_content = "Pero un regalo tuyo no es algo que pueda aceptar fácilmente.",
  ui_story_5075_50750500_10_dialog_content = "Pobre de mí. No puedo creerlo...",
  ui_story_5075_50750500_11_dialog_content = "A pesar de conocerme solo por un corto tiempo, ya me entiendes tan bien.",
  ui_story_5075_50750500_12_dialog_content = "Ya que has visto a través de mí, iré al grano. Aquí, por favor toma esto.",
  ui_story_5075_50750500_13_dialog_content = "Eso es un accesorio para niñas, ¿no es así?",
  ui_story_5075_50750500_14_dialog_content = "Un cliente mío dejó caer esto accidentalmente justo antes de que llegaras.",
  ui_story_5075_50750500_15_dialog_content = "Pero estoy demasiado ocupado con las ventas para rastrearla, así que todo depende de ti.",
  ui_story_5075_50750500_16_dialog_content = "Pero yo también tengo cosas que hacer.",
  ui_story_5075_50750500_17_dialog_content = "No te preocupes. Descubrí a través de la adivinación que hay un fuerte vínculo kármico entre ustedes dos.",
  ui_story_5075_50750500_18_dialog_content = "Simplemente ocúpate de tus propios asuntos, y te encontrarás de manera natural.",
  ui_story_5075_50750500_19_dialog_content = "Supongo que después de todo aún eres adivino.",
  ui_story_5075_50750500_20_dialog_content = "Espera, ahora que lo miro más de cerca, esto se parece a lo que encontré en el Templo de la Doncella Dragón.",
  ui_story_5075_50750500_21_dialog_content = "Y recuerdo haberlo visto también en alguien más.",
  ui_story_5075_50750500_22_dialog_content = "De ninguna manera...",
  ui_story_5075_50750500_23_dialog_content = "Dime, ¿sabes algo sobre los <color=#FFB400>diabólicos</color>? Li Tianxian?",
  ui_story_5075_50750500_24_dialog_content = "Por supuesto que sí. ¿Recuerdas la especial <color=#FFB400>Adivinación del Hexagrama Celestial</color> que inventé yo mismo?",
  ui_story_5075_50750500_25_dialog_content = "También tiene algo que ver con los más venerados <color=#FFB400>Trece Grandes Fiendlings</color> de Longzhou.",
  ui_story_5075_50750500_26_dialog_content = "¿Pero no son esos animales?",
  ui_story_5075_50750500_27_dialog_content = "Los animales, los diabólicos y las deidades solo varían en sus apariencias específicas.",
  ui_story_5075_50750500_28_dialog_content = "¿No te contó Zhong Xu la historia de los protectores demoníacos que finalmente fueron concedidos la divinidad?",
  ui_story_5075_50750500_29_dialog_content = "Estos trece fiendlings también son las deidades más únicas en Longzhou.",
  ui_story_5075_50750500_30_dialog_content = "La <color=#FFB400>Doncella Dragón</color> en <color=#FFB400>Doncella Dragón Sobre Mares Turbulentos</color> que tú conoces es una de ellas.",
  ui_story_5075_50750500_31_dialog_content = "Aunque el tiempo ha hecho que la gente olvide que las deidades que adoran son en realidad fiendlings.",
  ui_story_5075_50750500_32_dialog_content = "Me desvío, volvamos a tu pregunta.",
  ui_story_5075_50750500_33_dialog_content = "Los fiendlings también manejan diferentes Artes de Fuerza, y para los principales fiendlings, o deidades...",
  ui_story_5075_50750500_34_dialog_content = "Su poder es tan avanzado, que se le llama \"sobrenatural\".",
  ui_story_5075_50750500_35_dialog_content = "Se dice que podrían cambiar el clétima, volverse invisibles o transformarse a voluntad.",
  ui_story_5075_50750500_36_dialog_content = "¡Qué envidiable!",
  ui_story_5075_50750500_37_dialog_content = "No me digas que esa chica también es una... Espera, ¿te pregunté sobre los poderes de los demonios?",
  ui_story_5075_50750500_38_dialog_content = "¡Por supuesto que lo hiciste!",
  ui_story_5075_50750500_39_dialog_content = "Oh... Estos deben ser algunos Luminatics realmente poderosos. No estoy seguro de si puedo percibir algo a este nivel.",
  ui_story_5075_50750500_40_dialog_content = "Me temo que tendrás que preguntarle a las <color=#FFB400>deidades</color> sobre eso tú mismo.",
  ui_story_5075_50750500_41_dialog_content = "De hecho, tengo un mantra para ti, aunque no está ni cerca del nivel sobrenatural.",
  ui_story_5075_50750500_42_dialog_content = "Se ha transmitido desde la antigua gente de Longzhou y es especialmente útil para esta circunstancia.",
  ui_story_5075_50750500_43_dialog_content = "Ven, repite después de mí.",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>Merry—Año—Nuevo.</color>",
  ui_story_5075_50750500_45_dialog_content = "Merry—Año—Nuevo.",
  ui_story_5075_50750500_46_dialog_content = "Ahí tienes. Lo usarás bien en los próximos días, garantizado.",
  ui_story_5075_50750500_47_dialog_content = "No importa con qué problemas te encuentres, solo repítelo, y casi todo estará bien.",
  ui_story_5075_50750500_48_dialog_content = "¿Es realmente tan poderoso un encantamiento tan simple?",
  ui_story_5075_50750500_49_dialog_content = "¡Oh, no subestimes el poder de un antiguo mantra!",
  ui_story_5075_50750500_50_dialog_content = "En realidad, hay cuatro partes en el mantra, pero probablemente el resto aún esté más allá de tu comprensión en este momento.",
  ui_story_5075_50750500_51_dialog_content = "Te los enseñaré más tarde cuando tengamos la oportunidad.",
  ui_story_5075_50750500_52_dialog_content = "¡Ok! ¡Muchas gracias!",
  ui_story_5075_50750500_53_dialog_content = "No lo menciones.",
  ui_story_5075_50750500_54_dialog_content = "En cuanto a tus otros problemas, me encantaría hacer una lectura para ti...",
  ui_story_5075_50750500_55_dialog_content = "Regresé, PlayerName. Lamento haberte hecho esperar.",
  ui_story_5075_50750500_56_dialog_content = "Pero realmente no tengo tiempo ahora mismo.",
  ui_story_5075_50750500_57_dialog_content = "¿Entonces no vas a leer mi fortuna después de todo?",
  ui_story_5075_50750500_58_dialog_content = "¿De qué fortuna estás hablando?",
  ui_story_5075_50750500_59_dialog_content = "¡Eso me recuerda! Dijiste que eres un sacerdote errante, ¿Luo Song? ¿Eso significa que también puedes usar la adivinación para predecir el futuro?",
  ui_story_5075_50750500_60_dialog_content = "¿Qué? No dejes que los demás te engañen tan fácilmente, PlayerName.",
  ui_story_5075_50750500_61_dialog_content = "Todo ese discurso sobre el destino, el destino y el karma puede sonar convincente, incluso milagroso.",
  ui_story_5075_50750500_62_dialog_content = "Pero no es más que trucos baratos respaldados por mentiras ingeniosas.",
  ui_story_5075_50750500_63_dialog_content = "¿Ah?",
  ui_story_5075_50750500_64_dialog_content = "Mientras hagas las cosas con la conciencia tranquila, cualquier resultado que desees es posible.",
  ui_story_5075_50750500_65_dialog_content = "Siempre es mejor tomar el destino en tus propias manos, en lugar de dejarlo en manos de los trucos mágicos de algún estafador.",
  ui_story_5075_50750500_66_dialog_content = "(Li Tianxian...)",
  ui_story_5075_50750500_67_dialog_content = "(No me mires, solo soy un fabricante de figuritas de azúcar.)",
  ui_story_5075_50750500_68_dialog_content = "Tonto.",
  ui_story_5075_50750500_69_dialog_content = "Mente unidireccional.",
  ui_story_5075_50750500_70_dialog_content = "No saber nada, no saber nada.",
  ui_story_5075_50750500_71_dialog_content = "Problemas, problemas.",
  ui_story_5075_50750500_72_dialog_content = "¿Qué tonterías están balbuceando ustedes dos ahora? Tan incoherente, jaja.",
  ui_story_5075_50750500_73_dialog_content = "...",
  ui_story_5075_50750500_74_dialog_content = "Oye, tu figurita de azúcar está lista.",
  ui_story_5075_50750500_75_dialog_content = "Gracias... Espera, ¡esto es solo una flor de ciruelo! ¿Dónde está mi figurita de azúcar?",
  ui_story_5075_50750500_76_dialog_content = "Oh lo siento, me estoy quedando sin almíbar.",
  ui_story_5075_50750500_77_dialog_content = "Pero no te enfades. Quiero decir, tal como dice el poema...",
  ui_story_5075_50750500_78_dialog_content = "Belleza celestial, mi fuente de dicha, mi lluvia vespertina, mi tenue bruma matutina, anhelo tu toque a través de la larga noche solitaria. Mientras las flores de ciruelo florecen junto a mi ventana tan brillantes, extienden sus pétalos, tan rápidos parecen, convenciendo a mi corazón de que mi belleza está cerca.",
  ui_story_5075_50750500_79_dialog_content = "Entonces, ¿por qué no puedes ver esta <color=#FFB400>flor de ciruelo</color> como una dulce <color=#FFB400>belleza</color>?",
  ui_story_5075_50750500_80_dialog_content = "Me suena a una excusa bastante lamentable.",
  ui_story_5075_50750500_81_dialog_content = "Vamos, todos tenemos que ser románticos a veces.",
  ui_story_5075_50750500_82_dialog_content = "Bien, te voy a dejar ahora. ¡Nos vemos luego!",
  ui_story_5075_50750500_83_dialog_content = "Recuerda lo que dije. Si estás vacilando, intenta <color=#FFB400>rezar a las deidades</color>.",
  ui_story_5075_50750500_84_dialog_content = "Se supone que representarán Dragon Maiden Over Turbulent Seas en la feria más tarde.",
  ui_story_5075_50750500_85_dialog_content = "Pero la deidad en el escenario no es una real.",
  ui_story_5075_50750500_86_dialog_content = "¿Eh? ¿Es eso... la niebla negra?",
  ui_story_5075_50750500_87_dialog_content = "¡Necesito ir a investigar!",
  ui_story_5075_50750500_88_dialog_content = "Espera, PlayerName, iré contigo—",
  ui_story_5075_50750500_89_dialog_content = "Finalmente, puedo dedicarme a la lectura ahora que se ha ido el irritante.",
  ui_story_5075_50750500_90_dialog_content = "Uh-oh.",
  ui_story_5075_50750500_91_dialog_content = "La deidad en ese escenario podría ser real después de todo.",
  ui_story_5075_50750601_1_dialog_content = "¡Chirrido, chirrido!",
  ui_story_5075_50750601_2_dialog_content = "Mantén silencio e intenta no llamar demasiado la atención.",
  ui_story_5075_50750601_3_dialog_content = "¿Eh? Ya está despierto.",
  ui_story_5075_50750601_4_dialog_content = "Cuanto más se acerca a la feria, más lucha...",
  ui_story_5075_50750601_5_dialog_content = "Debe ser por su proximidad a la niebla negra.",
  ui_story_5075_50750601_6_dialog_content = "Juzgando por tu descripción, diría que tiene algún tipo de capacidad para corromper.",
  ui_story_5075_50750601_7_dialog_content = "Como un veneno que hace que los demonios enloquezcan.",
  ui_story_5075_50750601_8_dialog_content = "Desafortunadamente, no tengo forma de expulsarlo de sus cuerpos.",
  ui_story_5075_50750601_9_dialog_content = "He visto a los diabólicos en la naturaleza con los mismos síntomas, pero nunca se recuperaron de ellos. Todo lo que podían hacer era esconderse en algún lugar lejos de la gente.",
  ui_story_5075_50750601_10_dialog_content = "Este pequeño diablillo no es diferente...",
  ui_story_5075_50750601_11_dialog_content = "Mencionaste a una chica que podía eliminar tal mancha antes. ¿Podemos ir a verla?",
  ui_story_5075_50750601_12_dialog_content = "Para decir la verdad, solo la conocí hoy. Todo lo que sé es que su nombre es Chen'ni.",
  ui_story_5075_50750601_13_dialog_content = "Parece ser una diablilla especialmente poderosa ella misma.",
  ui_story_5075_50750601_14_dialog_content = "Los accesorios que dejó son nuestra única pista.",
  ui_story_5075_50750601_15_dialog_content = "¿Cómo podría alguien permitirse perder algo tan valioso, y mucho menos dos de ellos?",
  ui_story_5075_50750601_16_dialog_content = "No estarás hablando de una tobillera y pulsera doradas, ¿verdad?",
  ui_story_5075_50750601_17_dialog_content = "¿Cómo lo supiste?",
  ui_story_5075_50750601_18_dialog_content = "Porque yo también los he visto.",
  ui_story_5075_50750601_19_dialog_content = "¿También tienes uno? Una niña pequeña me acaba de comprar una empanada de sopa.",
  ui_story_5075_50750601_20_dialog_content = "Ella compró solo un dumpling y pagó con esto.",
  ui_story_5075_50750601_21_dialog_content = "¿Es esto oro? Estaba a punto de decir que era demasiado, y ella desapareció de repente cuando levanté la vista.",
  ui_story_5075_50750601_22_dialog_content = "Igual aquí, pero ni siquiera la vi.",
  ui_story_5075_50750601_23_dialog_content = "Todo lo que noté fue un tazón menos de taro de azúcar en esta mesa, y todo lo que quedaba era esta pieza de oro.",
  ui_story_5075_50750601_24_dialog_content = "¿Crees que fue el Dios de la Riqueza?",
  ui_story_5075_50750601_25_dialog_content = "Hmm... No parece ser una diosa de la riqueza, ¿verdad?",
  ui_story_5075_50750601_26_dialog_content = "¿Es eso realmente importante en este momento?",
  ui_story_5075_50750601_27_dialog_content = "¿La joven que compró raíces de loto rellenas con oro? La he visto. Probablemente entró.",
  ui_story_5075_50750601_28_dialog_content = "¡Bienvenido! ¡Echa un vistazo a mis carteles de Año Nuevo! Cada uno está cuidadosamente dibujado con la máxima atención al detalle.",
  ui_story_5075_50750601_29_dialog_content = "¿La chica que pagó con oro? Sí, la recuerdo.",
  ui_story_5075_50750601_30_dialog_content = "Realmente le gustaron mis carteles de año nuevo, especialmente los que tenían como tema la Doncella Dragón sobre Mares Turbulentos. Tomó bastantes.",
  ui_story_5075_50750601_31_dialog_content = "Recuerdo que después de que ella compró los carteles, había gritos provenientes del escenario.",
  ui_story_5075_50750601_32_dialog_content = "Tal vez ella fue a ver de qué se trataba el alboroto.",
  ui_story_5075_50750601_33_dialog_content = "Dijo que tenía algo más que hacer antes de irse. Supongo que se refería a visitar la feria.",
  ui_story_5075_50750601_34_dialog_content = "Parece que ella también hizo un trabajo bastante minucioso.",
  ui_story_5075_50750601_35_dialog_content = "¡Todo aquí sabe muy bien!",
  ui_story_5075_50750601_36_dialog_content = "Estos bocadillos de arroz no son tan dulces como los de Astra, ¡pero aún así me hacen desear aún más!",
  ui_story_5075_50750601_37_dialog_content = "¡De acuerdo! ¡La chica debe haber elegido el mejor loto relleno entre todos estos! ¡Son absolutamente increíbles!",
  ui_story_5075_50750601_38_dialog_content = "¿También te gustan, Ah Ding?",
  ui_story_5075_50750601_39_dialog_content = "¡Rugido!",
  ui_story_5075_50750601_40_dialog_content = "Eso me recuerda, ¿qué estábamos haciendo aquí de nuevo?",
  ui_story_5075_50750601_41_dialog_content = "...",
  ui_story_5075_50750601_42_dialog_content = "...",
  ui_story_5075_50750601_43_dialog_content = "La feria realmente te hace olvidarte de las cosas, ¿verdad?",
  ui_story_5075_50750601_44_dialog_content = "Cierto, jaja...",
  ui_story_5075_50750601_45_dialog_content = "Aun así, ¿has notado algo?",
  ui_story_5075_50750601_46_dialog_content = "El demonio que trajimos aquí dejó de luchar tan pronto como llegamos. Parece que se ha calmado bastante.",
  ui_story_5075_50750601_47_dialog_content = "Déjame intentar usar mis poderes de nuevo...",
  ui_story_5075_50750601_48_dialog_content = "¡Ya no hay más niebla negra en los alrededores! ¿Acaba de desaparecer?",
  ui_story_5075_50750601_49_dialog_content = "Hay otra posibilidad. Una mala.",
  ui_story_5075_50750601_50_dialog_content = "La niebla podría estar acumulándose en otro lugar. Necesitamos encontrar a la mujer antes de que alguien salga lastimado.",
  ui_story_5075_50750601_51_dialog_content = "Oye, PlayerName!",
  ui_story_5075_50750601_52_dialog_content = "¡Chen'ni! Estoy tan contento de que finalmente...",
  ui_story_5075_50750601_53_dialog_content = "¡Genial, trajiste a un amigo!",
  ui_story_5075_50750601_54_dialog_content = "¡Justo a tiempo! ¡Sube al escenario ahora!",
  ui_story_5075_50750601_55_dialog_content = "¿Hacer qué ahora?",
  ui_story_5075_50750601_56_dialog_content = "Tú... quiero decir, perdóname, pero este diablillo—",
  ui_story_5075_50750601_57_dialog_content = "¿Otro?",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>Al igual que antes, Chen'ni mueve su mano casualmente, incluso de manera algo distraída.</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>La niebla negra dentro del demonio es extraída y aplastada, como si nunca hubiera existido.</color>",
  ui_story_5075_50750601_60_dialog_content = "¡Chirrido!",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>El pequeño demonio salta ligeramente hasta los pies de Chen'ni, inclinando su cabeza como si mostrara gratitud.</color>",
  ui_story_5075_50750601_62_dialog_content = "Así que realmente eres—",
  ui_story_5075_50750601_63_dialog_content = "¡Vamos, es nuestro turno!",
  ui_story_5075_50750601_64_dialog_content = "¡Hay tanta gente allí abajo!",
  ui_story_5075_50750601_65_dialog_content = "¿Qué se supone exactamente que debemos hacer aquí arriba?",
  ui_story_5075_50750601_66_dialog_content = "Baila la <color=#FFB400>Doncella Dragón Sobre Mares Turbulentos</color>, por supuesto.",
  ui_story_5075_50750601_67_dialog_content = "Hola, queridos conciudadanos. Sé que todos vinieron aquí hoy por los famosos artistas.",
  ui_story_5075_50750601_68_dialog_content = "Pero estoy seguro de que todos han escuchado que la intérprete que mejor interpreta a la Doncella Dragón se lastimó el pie y no puede subir al escenario.",
  ui_story_5075_50750601_69_dialog_content = "Pero no podemos dejar el escenario vacío durante la feria, así que hemos ideado un nuevo arreglo.",
  ui_story_5075_50750601_70_dialog_content = "A continuación, algunas intérpretes de Doncella Dragón se turnarán en el escenario, cada una presentando su propia versión de Doncella Dragón Sobre Mares Turbulentos.",
  ui_story_5075_50750601_71_dialog_content = "Todos ustedes pueden elegir a la mejor intérprete de Doncella Dragón del Festival de Primavera de este año. ¿Qué les parece?",
  ui_story_5075_50750601_72_dialog_content = "¡Excelente!",
  ui_story_5075_50750601_73_dialog_content = "Es afortunado que hayas traído a un amigo, PlayerName, o no tendríamos suficientes personas.",
  ui_story_5075_50750601_74_dialog_content = "Tu amigo jugará como el Dragón Negro, un bravucón problemático del mar.",
  ui_story_5075_50750601_75_dialog_content = "Soy la Doncella Dragón.",
  ui_story_5075_50750601_76_dialog_content = "¿Qué hay de mí?",
  ui_story_5075_50750601_77_dialog_content = "Prepárate, PlayerName, porque tienes la parte más importante.",
  ui_story_5075_50750601_78_dialog_content = "<size=50>¡Serás el mar!</size>",
  ui_story_5075_50750601_79_dialog_content = "¿Es eso necesario?",
  ui_story_5075_50750601_80_dialog_content = "¿Qué estás diciendo? El mar es muy importante.",
  ui_story_5075_50750601_81_dialog_content = "Ahí está la música. Empieza a bailar.",
  ui_story_5075_50750601_82_dialog_content = "¡Ahh—!",
  ui_story_5075_50750601_83_dialog_content = "\"Bendecida por el destino, la Doncella Dragón trae buenos augurios mientras desciende al mundo.\"",
  ui_story_5075_50750601_84_dialog_content = "\"Las olas del vasto océano son oscuras, como si estuvieran envueltas en humo.\"",
  ui_story_5075_50750601_85_dialog_content = "(De acuerdo, presume de lo vasto y oscuro que eres, mar.)",
  ui_story_5075_50750601_86_dialog_content = "(¡Guiñarme un ojo no cambia nada! D-De todos modos, supongo que será mejor que cause algunas olas.)",
  ui_story_5075_50750601_87_dialog_content = "\"Bendita sea la Doncella Dragón...\"",
  ui_story_5075_50750601_88_dialog_content = "...",
  ui_story_5075_50750601_89_dialog_content = "(¡Oh no... No me digas que olvidaste tus líneas!)",
  ui_story_5075_50750601_90_dialog_content = "\"¡Innumerables bendiciones para todos\"! ¡Esa es la próxima parte!",
  ui_story_5075_50750601_91_dialog_content = "(No es bueno, ya se lo perdió. Claramente no podemos esperar que Chen'ni recuerde sus líneas...)",
  ui_story_5075_50750601_92_dialog_content = "\"A medida que llega el dragón malvado, tanto el sol como la luna pierden su luz.\"",
  ui_story_5075_50750601_93_dialog_content = "(¿Luo Song?)",
  ui_story_5075_50750601_94_dialog_content = "\"El trueno retumba y el relámpago destella.\"",
  ui_story_5075_50750601_95_dialog_content = "(Sus movimientos son rígidos y las líneas están claramente mal, ¡pero lo está haciendo! ¡Bien hecho!)",
  ui_story_5075_50750601_96_dialog_content = "(Espera, ¿por qué no se mueve?)",
  ui_story_5075_50750601_97_dialog_content = "(¡Rápido! ¡Truenos y relámpagos!)",
  ui_story_5075_50750601_98_dialog_content = "(¿Ese también es mi trabajo?)",
  ui_story_5075_50750601_99_dialog_content = "(Lo que sea, es hora de hacer un poco de trueno.)",
  ui_story_5075_50750601_100_dialog_content = "¡Retumbar!",
  ui_story_5075_50750601_101_dialog_content = "\"La gente observa impotente mientras los espíritus malignos rugen y hacen estragos!\"",
  ui_story_5075_50750601_102_dialog_content = "\"Pero pronto, la Doncella Dragón aparece y los salva de la destrucción.\"",
  ui_story_5075_50750601_103_dialog_content = "\"Con fuerza ilimitada y determinación inquebrantable,\"",
  ui_story_5075_50750601_104_dialog_content = "\"¡Ella golpea a los demonios y los manda volando en todas direcciones!\"",
  ui_story_5075_50750601_105_dialog_content = "(¿Así que ahora la Doncella Dragón usa sus puños para pelear?)",
  ui_story_5075_50750601_106_dialog_content = "(Además, se supone que eres un dragón malvado! ¡Tus líneas no podrían estar más desordenadas!)",
  ui_story_5075_50750601_107_dialog_content = "¡Rugido!",
  ui_story_5075_50750601_108_dialog_content = "(De todo el desastre en esta obra de teatro desastrosa, ¿por qué tienes que hacer un Eclipsite tan real?)",
  ui_story_5075_50750601_109_dialog_content = "(¡Espera un minuto!)",
  ui_story_5075_50750601_110_dialog_content = "¡Este es un verdadero eclipse!",
  ui_story_5075_50750602_1_dialog_content = "Gracias a todos por traer algo así...",
  ui_story_5075_50750602_2_dialog_content = "Único... interpretaciones creativas de la... Doncella Dragón Sobre Mares Turbulentos.",
  ui_story_5075_50750602_3_dialog_content = "El líder del grupo parece tan derrotado. Debemos haber hecho un trabajo realmente terrible.",
  ui_story_5075_50750602_4_dialog_content = "Creo que, honestamente, el ataque del espíritu malvado fue el que más daño hizo.",
  ui_story_5075_50750602_5_dialog_content = "¿Pensé que los Eclipsites de Longzhou rara vez aparecían en las ciudades?",
  ui_story_5075_50750602_6_dialog_content = "Pequeños demonios frenéticos, una inexplicable niebla negra, y ahora también Eclipsites.",
  ui_story_5075_50750602_7_dialog_content = "¿Qué demonios está pasando en la ciudad de Haojin?",
  ui_story_5075_50750602_8_dialog_content = "¿Por qué ustedes dos se ven tan preocupados?",
  ui_story_5075_50750602_9_dialog_content = "Creo que lo hicimos bien, incluso manejamos el espíritu malvado.",
  ui_story_5075_50750602_10_dialog_content = "Especialmente por parte de PlayerName. ¡Me encanta!",
  ui_story_5075_50750602_11_dialog_content = "Si a eso se le puede llamar actuación...",
  ui_story_5075_50750602_12_dialog_content = "No creo que la segunda mitad de la historia tenga algo que ver con la Doncella Dragón Sobre Mares Turbulentos.",
  ui_story_5075_50750602_13_dialog_content = "Así es como me contaron la historia.",
  ui_story_5075_50750602_14_dialog_content = "Hace ochocientos años, el mundo fue plagado por un malvado dragón negro.",
  ui_story_5075_50750602_15_dialog_content = "Pero un día, apareció la Doncella Dragón. Desde la cima de las olas del océano, derribó al malvado dragón con sus puños.",
  ui_story_5075_50750602_16_dialog_content = "Cada golpe tenía una fuerza inimaginable. El dragón se tambaleó en shock mientras el viento de sus puños lo empujaba millas y millas de distancia.",
  ui_story_5075_50750602_17_dialog_content = "¡Antes de que pudiera reaccionar, la Doncella Dragón cayó sobre el dragón con una ráfaga de golpes, golpeándolo hasta dejarlo irreconocible!",
  ui_story_5075_50750602_18_dialog_content = "¡Genial! ¿Y entonces? ¿Y entonces?",
  ui_story_5075_50750602_19_dialog_content = "Un fuerte zumbido resonó en los oídos del dragón mientras la ira se acumulaba en su corazón, y este ferozmente—",
  ui_story_5075_50750602_20_dialog_content = "Bueno, creo que sabes lo que pasó después mejor que nadie. Después de todo—",
  ui_story_5075_50750602_21_dialog_content = "Eres Chen'ni, la Todopoderosa Divinidad del Dragón Benevolente, ¿verdad?",
  ui_story_5075_50750602_22_dialog_content = "Espera un minuto... Después de escuchar lo que Li Tianxian dijo sobre los fiendlings, no debería sorprenderme que Chen'ni sea una deidad de algún tipo.",
  ui_story_5075_50750602_23_dialog_content = "¿Pero esta Chen'ni que tenemos aquí es la Doncella Dragón?",
  ui_story_5075_50750602_24_dialog_content = "Ese soy yo, en efecto.",
  ui_story_5075_50750602_25_dialog_content = "¡Me siento honrado de estar en tu presencia, la Todopoderosa Divinidad del Dragón Benevolente!",
  ui_story_5075_50750602_26_dialog_content = "¡Eso no tomó mucho tiempo!",
  ui_story_5075_50750602_27_dialog_content = "Una deidad genuina, un ser iluminado, está justo frente a nosotros. Es apropiado que mostremos nuestra reverencia.",
  ui_story_5075_50750602_28_dialog_content = "Lady Chen'ni, ¿hay alguna razón para su aparición en Haojin?",
  ui_story_5075_50750602_29_dialog_content = "Alguien rompió el sello y perturbó mi sueño. Estoy aquí por justicia.",
  ui_story_5075_50750602_30_dialog_content = "¡E-Eso suena como un desastre!",
  ui_story_5075_50750602_31_dialog_content = "¿Entonces la aparición de espíritus malvados y demonios agitados es porque el sello del dragón malvado ha sido roto?",
  ui_story_5075_50750602_32_dialog_content = "Entonces, el dragón negro también es real, ¿eh?",
  ui_story_5075_50750602_33_dialog_content = "Así es, aunque hay tantas versiones diferentes de la Doncella del Dragón Sobre Mares Turbulentos, todas se basan en un evento histórico real.",
  ui_story_5075_50750602_34_dialog_content = "Por eso las partes más importantes de la historia son en su mayoría las mismas.",
  ui_story_5075_50750602_35_dialog_content = "El malvado dragón causando estragos en el mundo, la Doncella del Dragón sellándolo en el fondo del mar, y la gente conociendo la paz una vez más.",
  ui_story_5075_50750602_36_dialog_content = "Pero el evento de la historia sucedió hace más de ochocientos años.",
  ui_story_5075_50750602_37_dialog_content = "¿Cómo podría el dragón negro seguir vivo después de todo este tiempo?",
  ui_story_5075_50750602_38_dialog_content = "El dragón negro lleva mucho tiempo muerto. Eso no es una preocupación.",
  ui_story_5075_50750602_39_dialog_content = "Pero lo que ocurrió en aquel momento no fue culpa de mi familia.",
  ui_story_5075_50750602_40_dialog_content = "Existe un profundo abismo bajo el mar donde se enterró a un poderoso demonio junto con su abrumador rencor.",
  ui_story_5075_50750602_41_dialog_content = "Mi compañero se encontró con él y fue superado por el rencor, de ahí el alboroto en el mar.",
  ui_story_5075_50750602_42_dialog_content = "A pesar de que el sello fue removido, mi poder permanece. Aunque el rencor también fue liberado, no puede causar daño al mundo sin un recipiente físico.",
  ui_story_5075_50750602_43_dialog_content = "Incluso si posee un nuevo cuerpo, aún no puede moverse libremente hasta que se acostumbre completamente.",
  ui_story_5075_50750602_44_dialog_content = "(¿Así que lo que sentí brevemente antes era el poderoso demonio?)",
  ui_story_5075_50750602_45_dialog_content = "(Eso no se siente bien... Pero no lo vi bien. Afortunadamente, todavía tenemos tiempo según Chen'ni.)",
  ui_story_5075_50750602_46_dialog_content = "No importa cómo lo mires, Chen'ni tiene el mismo objetivo que nosotros.",
  ui_story_5075_50750602_47_dialog_content = "Si estamos trabajando juntos por el momento, ¿puedo hacer una pequeña pregunta?",
  ui_story_5075_50750602_48_dialog_content = "Sí.",
  ui_story_5075_50750602_49_dialog_content = "Creo que la primera vez que nos conocimos fue en el Templo de la Doncella Dragón.",
  ui_story_5075_50750602_50_dialog_content = "Pero si tú eres la Doncella Dragonante, entonces... ¿por qué estabas robando tus propias ofrendas?",
  ui_story_5075_50750602_51_dialog_content = "... Eso no fue robar.",
  ui_story_5075_50750602_52_dialog_content = "Estaba tomando regalos destinados para mí. ¿Cómo podría ser eso robar? ¡Humph!",
  ui_story_5075_50750602_53_dialog_content = "Jaja, mi error. Solo estabas aceptando tus ofrendas, no robándolas.",
  ui_story_5075_50750602_54_dialog_content = "Supongo que simplemente estoy acostumbrado a verte así.",
  ui_story_5075_50750602_55_dialog_content = "De todos modos, estoy bastante seguro de que estos accesorios de oro te pertenecen, ¿verdad Chen'ni?",
  ui_story_5075_50750602_56_dialog_content = "Encontré uno de estos en el Templo de la Doncella Dragón, y el otro me lo dio Li Tianxian... eh, quiero decir, un vendedor de figuritas de azúcar. Quería devolvértelo.",
  ui_story_5075_50750602_57_dialog_content = "Solo tomaré uno de vuelta.",
  ui_story_5075_50750602_58_dialog_content = "Ya que encontraste el otro en mi templo, PlayerName, puedes quedártelo.",
  ui_story_5075_50750602_59_dialog_content = "Si tienes alguna necesidad en el futuro, te concederé un deseo a través de ella.",
  ui_story_5075_50750602_60_dialog_content = "Un deseo...",
  ui_story_5075_50750602_61_dialog_content = "Perdón por la interrupción, amigos.",
  ui_story_5075_50750602_62_dialog_content = "Oh, hola. Lo siento por lo que pasó antes.",
  ui_story_5075_50750602_63_dialog_content = "Nah, debería ser yo quien te agradezca. No hay otro daño excepto el escenario roto.",
  ui_story_5075_50750602_64_dialog_content = "Aunque la competencia tenga que terminar así, y no podamos entregar premios, aún así, por favor, toma esto.",
  ui_story_5075_50750602_65_dialog_content = "Es un bocadillo casero, no tan sofisticado como los que se venden por ahí.",
  ui_story_5075_50750602_66_dialog_content = "Pero está hecho con una receta secreta que se ha transmitido en mi familia, no disponible en ningún otro lugar. Adelante, pruébalo.",
  ui_story_5075_50750602_67_dialog_content = "¡Eso es todo!",
  ui_story_5075_50750602_68_dialog_content = "Me inscribí en la competencia porque lo olí. Veo que en realidad no es el premio.",
  ui_story_5075_50750602_69_dialog_content = "¿Hiciste todo eso por un bocadillo?",
  ui_story_5075_50750602_70_dialog_content = "Nom-nom.",
  ui_story_5075_50750602_71_dialog_content = "Sí, este es el sabor. ¡Lo hiciste de la misma manera que lo hacía tu abuelo!",
  ui_story_5075_50750602_72_dialog_content = "Bueno, supongo que puedo llamar a mi justa gira un rotundo éxito.",
  ui_story_5075_50750602_73_dialog_content = "Vamos.",
  ui_story_5075_50750602_74_dialog_content = "Es exactamente como lo que hacía mi abuelo... Aunque él murió hace años y nunca vendimos algo así.",
  ui_story_5075_50750602_75_dialog_content = "¡¡¡Espera un segundo...!!!",
  ui_story_5075_50750602_76_dialog_content = "Prueba un bocado también, PlayerName, Luo Song y Ah Ding.",
  ui_story_5075_50750602_77_dialog_content = "Este aperitivo es simplemente fantástico. Lástima que solo su familia pueda hacerlo.",
  ui_story_5075_50750602_78_dialog_content = "¡Rugido!",
  ui_story_5075_50750602_79_dialog_content = "¡Gracias, señora Chen'ni!",
  ui_story_5075_50750602_80_dialog_content = "Nos hemos visto antes, así que solo llámame Chen'ni.",
  ui_story_5075_50750602_81_dialog_content = "¡Tu deseo es mi comando!",
  ui_story_5075_50750602_82_dialog_content = "¿Cómo es que no estás comiendo, PlayerName?",
  ui_story_5075_50750602_83_dialog_content = "¿Está realmente bien?",
  ui_story_5075_50750602_84_dialog_content = "¿Qué quieres decir?",
  ui_story_5075_50750602_85_dialog_content = "El líder del grupo es descendiente de alguien que solías conocer, ¿verdad?",
  ui_story_5075_50750602_86_dialog_content = "¿No tienes más que decirle a él?",
  ui_story_5075_50750602_87_dialog_content = "Bueno...",
  ui_story_5075_50750602_88_dialog_content = "Soy un dragón, un gran diablillo y un dios del mar para todos. A diferencia de la gente normal, puedo vivir mucho, mucho tiempo.",
  ui_story_5075_50750602_89_dialog_content = "Así que llego a conocer a muchas, muchas personas.",
  ui_story_5075_50750602_90_dialog_content = "Ese líder de la compañía es el nieto de alguien que solía darme bocadillos todo el tiempo.",
  ui_story_5075_50750602_91_dialog_content = "La calle del lado este es donde se va a casar la nieta de un hombre con quien solía remar botes.",
  ui_story_5075_50750602_92_dialog_content = "Un callejón en el extremo sur del río es donde está siendo enterrado el joven sobrino del hombre que siempre me ganaba en las peleas de cricket.",
  ui_story_5075_50750602_93_dialog_content = "El niño también resulta ser su último pariente de sangre en este mundo.",
  ui_story_5075_50750602_94_dialog_content = "La vida es demasiado corta para todos, así que apuran todo.",
  ui_story_5075_50750602_95_dialog_content = "Entonces siempre sienten la necesidad de demostrar sus lazos con rituales o ceremonias.",
  ui_story_5075_50750602_96_dialog_content = "Si tengo que conocer a sus descendientes solo porque conocí a alguien...",
  ui_story_5075_50750602_97_dialog_content = "Estaría pasando todo mi tiempo yendo y viniendo entre ceremonias.",
  ui_story_5075_50750602_98_dialog_content = "Pero, ¿no te sientes solo de esa manera?",
  ui_story_5075_50750602_99_dialog_content = "Debido a tu longevidad, siempre eres el que tiene que despedirse de tus amigos.",
  ui_story_5075_50750602_100_dialog_content = "No, creo que está bien así.",
  ui_story_5075_50750602_101_dialog_content = "También deberías sentirte afortunado, PlayerName.",
  ui_story_5075_50750602_102_dialog_content = "Porque llegas a conocerme, alguien que vivirá por mucho, mucho tiempo, y yo te recordaré.",
  ui_story_5075_50750602_103_dialog_content = "Incluso si deberías morir, aún estarás en mis recuerdos, permaneciendo conmigo para siempre.",
  ui_story_5075_50750602_104_dialog_content = "(Siempre puedo entender un poco lo que ella quiere decir, pero nunca lo entiendo completamente.)",
  ui_story_5075_50750602_105_dialog_content = "(Ya sea la sonrisa alegre en su rostro, o los sentimientos que expresa.)",
  ui_story_5075_50750602_106_dialog_content = "(En ese momento, de repente entiendo, realmente no somos iguales.)",
  ui_story_5075_50750701_1_dialog_content = "Nosotros. Somos. Diferentes.",
  ui_story_5075_50750701_2_dialog_content = "Así.",
  ui_story_5075_50750701_3_dialog_content = "Nosotros. Somos. Incompatibles.",
  ui_story_5075_50750701_4_dialog_content = "Urgh...",
  ui_story_5075_50750701_5_dialog_content = "¿Estás bien? ¿Necesitas un descanso?",
  ui_story_5075_50750701_6_dialog_content = "Has estado sintiendo la niebla negra todo este tiempo. ¿Estás seguro de que puedes seguir adelante?",
  ui_story_5075_50750701_7_dialog_content = "Por supuesto que puedo. No soy tan débil.",
  ui_story_5075_50750701_8_dialog_content = "Además, cuanto más siento esta niebla negra, más me doy cuenta de que no es muy diferente de Darkflow.",
  ui_story_5075_50750701_9_dialog_content = "Las mayores diferencias son sus propiedades infecciosas y corruptoras, que dificultan su disipación utilizando nuestros métodos habituales para combatir el Darkflow.",
  ui_story_5075_50750701_10_dialog_content = "Si Chen'ni tiene razón, y la causa raíz de estas propiedades es un rencor, entonces puede poseer alguna forma de conciencia.",
  ui_story_5075_50750701_11_dialog_content = "Si es así, ¡debería poder usar mis poderes para interrumpirlo!",
  ui_story_5075_50750701_12_dialog_content = "Después de un par de intentos, me di cuenta de que podía usar mis habilidades psíquicas para aislar el poder corruptor de la niebla negra.",
  ui_story_5075_50750701_13_dialog_content = "Si sigo practicando, incluso podría ser capaz de ayudar a los fiundlings que ya han sido corrompidos.",
  ui_story_5075_50750701_14_dialog_content = "En realidad, está bien dejarme todo a mí.",
  ui_story_5075_50750701_15_dialog_content = "Eso no servirá. Estamos trabajando juntos ahora, lo que significa que no puedo simplemente dejarte hacer todo el trabajo.",
  ui_story_5075_50750701_16_dialog_content = "Entonces dejaré el trabajo delicado en tus manos. Si algo requiere un toque más fuerte, mis puños siempre están a la altura de la tarea!",
  ui_story_5075_50750701_17_dialog_content = "Rugido—",
  ui_story_5075_50750701_18_dialog_content = "Lo mismo se aplica para Ah Ding!",
  ui_story_5075_50750701_19_dialog_content = "¡Rugido!",
  ui_story_5075_50750701_20_dialog_content = "¡Chirrido!",
  ui_story_5075_50750701_21_dialog_content = "¿No es el mismo pequeño fiundling de antes? ¿Qué está haciendo aquí?",
  ui_story_5075_50750701_22_dialog_content = "¿No te pedí que le dijeras que buscara a tus amigos, Ah Ding?",
  ui_story_5075_50750701_23_dialog_content = "Rugido...",
  ui_story_5075_50750701_24_dialog_content = "No quería escuchar, ¿eh?",
  ui_story_5075_50750701_25_dialog_content = "Mientras practicaba con mis habilidades psíquicas, noté que nos ha estado siguiendo desde la distancia todo este tiempo.",
  ui_story_5075_50750701_26_dialog_content = "¿Quizás solo tiene miedo? Podría pensar que es más seguro quedarse con nosotros después de haber sido corrompido.",
  ui_story_5075_50750701_27_dialog_content = "Apenas consideraría seguro estar a nuestro lado. Después de todo, vamos a...",
  ui_story_5075_50750701_28_dialog_content = "Espera, ¿olvidé preguntar a dónde vamos?",
  ui_story_5075_50750701_29_dialog_content = "Calle Yulin.",
  ui_story_5075_50750701_30_dialog_content = "De dónde viene esa repugnante vibra.",
  ui_story_5075_50750701_31_dialog_content = "¿Ah?",
  ui_story_5075_50750701_32_dialog_content = "¿Esto significa que nuestros destinos son realmente diferentes?",
  ui_story_5075_50750701_33_dialog_content = "?",
  ui_story_5075_50750701_34_dialog_content = "No lo creo. Si ese fuera el caso, habríamos tenido problemas hace mucho tiempo.",
  ui_story_5075_50750701_35_dialog_content = "Probablemente no importa.",
  ui_story_5075_50750701_36_dialog_content = "De todos modos, estamos en el destino de PlayerName.",
  ui_story_5075_50750701_37_dialog_content = "¿Estoy viendo cosas? ¿Por qué cada tienda parece aún más lujosa que la anterior?",
  ui_story_5075_50750701_38_dialog_content = "Así que esta es la calle Yulin... No es tan animada como la feria, pero sigue siendo realmente impresionante.",
  ui_story_5075_50750701_39_dialog_content = "Lo sé. Aquí es donde viven todas las personas ricas.",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>El río claro atraviesa toda la calle, bordeado por edificios altos. Incluso en invierno, están decorados con vibrantes flores de varios colores.</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>Cintas coloridas revolotean entre los edificios, y cuando sopla el viento, desencadena un coro de campanillas de plata tintineantes.</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>En torres altas y bajas, tres mil doncellas bailan, su belleza resplandece. De este a oeste, en aguas que otorgan, barcos cargados de oro en fila incesante.</color>",
  ui_story_5075_50750701_43_dialog_content = "¿Qué es esa estatua al lado de la calle?",
  ui_story_5075_50750701_44_dialog_content = "Un banco de peces rodeando un barco. Hay algo familiar en el barco y las colas de esos peces...",
  ui_story_5075_50750701_45_dialog_content = "¿Dónde he visto esto antes?",
  ui_story_5075_50750701_46_dialog_content = "Son peces serpiente. Siempre nadan de un lado a otro en cardúmenes.",
  ui_story_5075_50750701_47_dialog_content = "Pero no importa qué tan lejos vayan, volverán a la costa de Longzhou para poner huevos en invierno.",
  ui_story_5075_50750701_48_dialog_content = "Entonces, muchos marineros les suplicarían que guiaran sus barcos.",
  ui_story_5075_50750701_49_dialog_content = "¿Pidiendo ayuda a los peces?",
  ui_story_5075_50750701_50_dialog_content = "Claro. La gente siempre hace ofrendas a los animales o diabólicos para pedir ayuda.",
  ui_story_5075_50750701_51_dialog_content = "¿No ha sido así desde tiempos antiguos?",
  ui_story_5075_50750701_52_dialog_content = "Eso no parece ser el caso, al menos no ahora...",
  ui_story_5075_50750701_53_dialog_content = "Esta estatua debe tener muchos años ahora, y está cubierta de rasguños y mugre. No creo que nadie la haya cuidado durante mucho tiempo.",
  ui_story_5075_50750701_54_dialog_content = "Incluso si antes estaban en buenos términos, me temo que ese tiempo...",
  ui_story_5075_50750701_55_dialog_content = "Ese tiempo hace mucho que terminó.",
  ui_story_5075_50750701_56_dialog_content = "¡Yuebai! Finalmente has vuelto a Haojin.",
  ui_story_5075_50750701_57_dialog_content = "Regresé hace algunos días, pero asuntos urgentes con la familia Lin me impidieron verte antes.",
  ui_story_5075_50750701_58_dialog_content = "¡Entonces es bueno que nos hayamos encontrado aquí!",
  ui_story_5075_50750701_59_dialog_content = "¿Con qué tipo de problema está lidiando la familia Lin ahora?",
  ui_story_5075_50750701_60_dialog_content = "No diría exactamente que es un problema.",
  ui_story_5075_50750701_61_dialog_content = "Es más bien un error.",
  ui_story_5075_50750701_62_dialog_content = "Un error cometido por la Familia Lin en relación al pez serpiente.",
  ui_story_5075_50750701_63_dialog_content = "¿Es por eso que dijiste, \"Ese tiempo hace mucho que terminó\"?",
  ui_story_5075_50750701_64_dialog_content = "Sí.",
  ui_story_5075_50750701_65_dialog_content = "Por favor, abstente de tocar mi cola.",
  ui_story_5075_50750701_66_dialog_content = "¡P-Pero yo no toqué tu cola!",
  ui_story_5075_50750701_67_dialog_content = "No estaba hablando de ti, PlayerName.",
  ui_story_5075_50750701_68_dialog_content = "Vaya, parte culpable.",
  ui_story_5075_50750701_69_dialog_content = "Rara vez veo a un Aurorian con herencia de pez serpiente, así que simplemente no pude evitarlo.",
  ui_story_5075_50750701_70_dialog_content = "Dada la teoría de que los peces serpiente y los dragones son parientes lejanos, en realidad estamos algo relacionados.",
  ui_story_5075_50750701_71_dialog_content = "Entonces, ese es mi honor.",
  ui_story_5075_50750701_72_dialog_content = "No es de extrañar que pensara que esos peces me resultaban familiares. Me recordaban a ti, Yuebai.",
  ui_story_5075_50750701_73_dialog_content = "¡Y después de mirar más de cerca, este barco se parece mucho al Shadowind!",
  ui_story_5075_50750701_74_dialog_content = "Eso es porque es una versión temprana de ello.",
  ui_story_5075_50750701_75_dialog_content = "También fue el primer barco de la Familia Lin en cruzar el mar y llegar a Astra hace muchos años.",
  ui_story_5075_50750701_76_dialog_content = "Entiendo. Pero, ¿qué hace aquí una escultura de un barco de la familia Lin?",
  ui_story_5075_50750701_77_dialog_content = "¿No lo sabes?",
  ui_story_5075_50750701_78_dialog_content = "Esta calle comercial una vez perteneció a la familia Lin.",
  ui_story_5075_50750701_79_dialog_content = "¿T-Toda la calle?",
  ui_story_5075_50750701_80_dialog_content = "Desafortunadamente, debido a una serie de tratos recientes, así como al último incidente de la Familia Lin, gran parte de la calle se ha dividido.",
  ui_story_5075_50750701_81_dialog_content = "En este momento, solo la mitad de la calle sigue bajo el nombre de la Familia Lin.",
  ui_story_5075_50750701_82_dialog_content = "En cuanto al destino final de esta mitad restante, todo depende de cómo progresen las cosas.",
  ui_story_5075_50750701_83_dialog_content = "La mitad de una calle entera sigue siendo bastante impresionante, ¿sabes?",
  ui_story_5075_50750701_84_dialog_content = "¡Chirrido!",
  ui_story_5075_50750701_85_dialog_content = "¡Ay!",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>Mientras te derriban repentinamente por el demonio que se abalanza, un Darkflow negro como la brea golpea el suelo justo a tus pies.</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50750701_88_dialog_content = "¡PlayerName! ¿Estás bien?",
  ui_story_5075_50750701_89_dialog_content = "Estoy bien. Ese pequeño demonio me salvó justo ahora.",
  ui_story_5075_50750701_90_dialog_content = "Chirrido...",
  ui_story_5075_50750701_91_dialog_content = "¿Qué le pasa? Parece que tiene mucho dolor.",
  ui_story_5075_50750701_92_dialog_content = "... Espera, ¿cuándo se volvió a infectar con la niebla negra?",
  ui_story_5075_50750701_93_dialog_content = "¿Ah Ding?",
  ui_story_5075_50750701_94_dialog_content = "Rugido...",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>Ah Ding emite un gruñido bajo y doloroso, y la Lumina previamente estable a su alrededor comienza a fluctuar.</color>",
  ui_story_5075_50750701_96_dialog_content = "No me digas que estos síntomas son...",
  ui_story_5075_50750701_97_dialog_content = "¡Potencia de fuerza!",
  ui_story_5075_50750701_98_dialog_content = "Logré aislar el poder corruptor de la niebla por ahora, pero necesitamos encontrar su fuente lo más pronto posible.",
  ui_story_5075_50750701_99_dialog_content = "¿De dónde vino esta gigantesca nube de niebla negra?",
  ui_story_5075_50750701_100_dialog_content = "Estoy buscando al que rompió el sello, no a ti. Mantén la calma y no te dejes llevar por las narices.",
  ui_story_5075_50750701_101_dialog_content = "¿Eh? ¿Con quién estás hablando, Chen'ni?",
  ui_story_5075_50750701_102_dialog_content = "El pez.",
  ui_story_5075_50750701_103_dialog_content = "El pez... ¿Te refieres a la estatua?",
  ui_story_5075_50750701_104_dialog_content = "¡Escaneo psíquico!",
  ui_story_5075_50750701_105_dialog_content = "¿Esto está bajo el mar?",
  ui_story_5075_50750701_106_dialog_content = "Quién. Va. Allí.",
  ui_story_5075_50750701_107_dialog_content = "¿Una cola de pez serpiente?",
  ui_story_5075_50750701_108_dialog_content = "¿Estás relacionado con la familia Lin?",
  ui_story_5075_50750701_109_dialog_content = "Los. Lins.",
  ui_story_5075_50750701_110_dialog_content = "Des—preciable.",
  ui_story_5075_50750701_111_dialog_content = "¡De—probable!",
  ui_story_5075_50750701_112_dialog_content = "!",
  ui_story_5075_50750701_113_dialog_content = "Duele...",
  ui_story_5075_50750701_114_dialog_content = "Mantente fuerte, PlayerName.",
  ui_story_5075_50750701_115_dialog_content = "Estoy bien. El poder corruptor de la niebla negra era simplemente mucho más fuerte en el lugar que percibí.",
  ui_story_5075_50750701_116_dialog_content = "Vi a alguien más allí también. Parecía que... estaba conectado de alguna manera con la familia Lin.",
  ui_story_5075_50750701_117_dialog_content = "Es Yoh.",
  ui_story_5075_50750701_118_dialog_content = "¿Lo conoces, Yuebai?",
  ui_story_5075_50750701_119_dialog_content = "Yoh es un demonio que una vez fue aliado de la Familia Lin.",
  ui_story_5075_50750701_120_dialog_content = "No hace mucho tiempo, el maestro de la guilda lo envió en una misión a la costa. Estaba investigando la razón detrás de los extraños movimientos de los espíritus malignos, pero nunca regresó.",
  ui_story_5075_50750701_121_dialog_content = "... Debe haberse convertido en el \"recipiente físico\" que Chen'ni mencionó antes! Parece que después de todo ocurrió el peor de los casos.",
  ui_story_5075_50750701_122_dialog_content = "El poder que fue sellado ha encontrado un nuevo anfitrión.",
  ui_story_5075_50750701_123_dialog_content = "¡Chirrido!",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>El pequeño demonio de repente salta y muerde fuertemente la muñeca de un extraño en la esquina.</color>",
  ui_story_5075_50750701_125_dialog_content = "Urgh... ¡Maldita criatura!",
  ui_story_5075_50750701_126_dialog_content = "¡Piérdete!",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>El pequeño diablillo es lanzado con fuerza a un lado, deslizándose lejos en el suelo, inmóvil.</color>",
  ui_story_5075_50750701_128_dialog_content = "¡Oh, no!",
  ui_story_5075_50750701_129_dialog_content = "Humph.",
  ui_story_5075_50750701_130_dialog_content = "Ese hombre... ¡Su cuerpo también está cubierto de la niebla negra! ¿Qué sostiene en sus brazos?",
  ui_story_5075_50750701_131_dialog_content = "¡¿Quién eres tú?!",
  ui_story_5075_50750701_132_dialog_content = "No necesitas saberlo.",
  ui_story_5075_50750701_133_dialog_content = "¡Esto no es bueno! ¡Alguien deténgalo!",
  ui_story_5075_50750701_134_dialog_content = "Es muy tarde!",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>El extraño destroza el objeto que sostiene en el suelo y libera una enorme niebla negra.</color>",
  ui_story_5075_50750701_136_dialog_content = "(¡Es justo como el poder que sentí en el océano!)",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>Esta vez, puedes verlo sin siquiera intentar usar tus habilidades psíquicas.</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>Esta vez, puedes verlo sin siquiera intentar usar tus habilidades psíquicas.</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>La interminable niebla negra lleva un intenso Darkflow, hirviendo y creciendo como agua caliente.</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>Todos esos flujos inestables de energía convergen en uno, y luego...</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>¡Ellos explotan repentinamente!</color>",
  ui_story_5075_50750701_142_dialog_content = "¡No, tú no!",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>Una figura dorada salta con un rayo y bloquea las oscuras mareas de la detonación, pero la niebla restante aún se dispersa.</color>",
  ui_story_5075_50750701_145_dialog_content = "¿Sois vosotros los que rompieron el sello? ¡Venid a pagar por vuestro error!",
  ui_story_5075_50750701_146_dialog_content = "*tose*",
  ui_story_5075_50750701_147_dialog_content = "¿Qué está pasando? ¿Dónde está Chen'ni?",
  ui_story_5075_50750701_148_dialog_content = "Después de que nos encontramos con la niebla negra, ella salió tras él.",
  ui_story_5075_50750701_149_dialog_content = "¡Eso es demasiado imprudente!",
  ui_story_5075_50750701_150_dialog_content = "Afortunadamente, no creo que nadie pueda realmente lastimarla.",
  ui_story_5075_50750701_151_dialog_content = "Pero no somos nada como ella. No parece que ninguno de nosotros haya resultado herido, sin embargo.",
  ui_story_5075_50750701_152_dialog_content = "¡No nos lastimamos... Pero Ah Ding y el otro pequeño sí lo hicieron!",
  ui_story_5075_50750701_153_dialog_content = "Rugido...",
  ui_story_5075_50750701_154_dialog_content = "Esa explosión de ahora ha enviado la niebla negra volando en todas direcciones. Su corrupción parece estar intensificándose también.",
  ui_story_5075_50750701_155_dialog_content = "No solo eso, parece que la niebla también está atrayendo a los Eclipsites.",
  ui_story_5075_50750701_156_dialog_content = "¡Prepárate para la batalla!",
  ui_story_5075_50750701_157_dialog_content = "Graah!",
  ui_story_5075_50750702_1_dialog_content = "¡No dejaré que los espíritus malvados profanen el lugar ancestral de la Familia Lin!",
  ui_story_5075_50750702_2_dialog_content = "Graah—",
  ui_story_5075_50750702_3_dialog_content = "Es bueno que estés aquí para eliminar a estos Eclipsites, Yuebai.",
  ui_story_5075_50750702_4_dialog_content = "Pero parece que la niebla se ha extendido hasta la ciudad. Me preocupa que esté a punto de suceder algo realmente malo.",
  ui_story_5075_50750702_5_dialog_content = "¿No hay nada que podamos hacer al respecto?",
  ui_story_5075_50750702_6_dialog_content = "Hay.",
  ui_story_5075_50750702_7_dialog_content = "La situación puede ser mucho peor que antes, pero la Familia Lin todavía tiene planes de contingencia en marcha.",
  ui_story_5075_50750702_8_dialog_content = "Asumiré la responsabilidad de escoltar a todos de manera segura hasta la finca de la familia Lin.",
  ui_story_5075_50750702_9_dialog_content = "Después, convenceré al maestro del gremio para que asigne sus recursos en la ciudad para ayudar con este asunto.",
  ui_story_5075_50750702_10_dialog_content = "¡Me parece bien! Pero, ¿no tienes curiosidad por saber qué está pasando antes de ayudarnos, Yuebai?",
  ui_story_5075_50750702_11_dialog_content = "El asunto está estrechamente relacionado con la familia Lin...",
  ui_story_5075_50750702_12_dialog_content = "Además, no necesito una razón para ayudar a un amigo como tú.",
  ui_story_5075_50750702_13_dialog_content = "Espera, PlayerName.",
  ui_story_5075_50750702_14_dialog_content = "¿Qué es, Luo Song?",
  ui_story_5075_50750702_15_dialog_content = "¿Podría dejar a este pequeño fiundling a tu cuidado por ahora?",
  ui_story_5075_50750702_16_dialog_content = "Por supuesto. No olvidemos a Ah Ding tampoco.",
  ui_story_5075_50750702_17_dialog_content = "Chen'ni aún no ha regresado, así que todo lo que puedo hacer es intentar aislar la corrupción de la niebla negra.",
  ui_story_5075_50750702_18_dialog_content = "Rugido...",
  ui_story_5075_50750702_19_dialog_content = "¿Ah Ding?",
  ui_story_5075_50750702_20_dialog_content = "Aquí es donde nos separamos.",
  ui_story_5075_50750702_21_dialog_content = "¿Tú también, Luo Song?",
  ui_story_5075_50750702_22_dialog_content = "Con la niebla negra extendiéndose por Haojin, seguramente habrá aún más demonios infectados.",
  ui_story_5075_50750702_23_dialog_content = "No son malos, simplemente siguen sus instintos. Después de todo, siguen siendo espíritus animales nacidos de la naturaleza salvaje.",
  ui_story_5075_50750702_24_dialog_content = "Tal como está, las opiniones de la gente hacia los fiendlings solo están empeorando.",
  ui_story_5075_50750702_25_dialog_content = "Si alguien resulta herido por un demonio como resultado de la infección de la niebla negra, me temo que la relación entre nosotros será irreparable.",
  ui_story_5075_50750702_26_dialog_content = "Por eso necesito someter a los demonios infectados antes de que sea demasiado tarde.",
  ui_story_5075_50750702_27_dialog_content = "Es cierto que hemos tenido nuestras diferencias con los fiendlings.",
  ui_story_5075_50750702_28_dialog_content = "Pero eso no le da a nadie el derecho de decidir su lugar en el mundo o su destino, para el caso.",
  ui_story_5075_50750702_29_dialog_content = "¿No es así, Ah Ding?",
  ui_story_5075_50750702_30_dialog_content = "Te elogio cuando haces algo bueno, y te reprendo cuando haces algo malo.",
  ui_story_5075_50750702_31_dialog_content = "Pero al final, la elección de hacer cualquiera de las dos siempre es tuya.",
  ui_story_5075_50750702_32_dialog_content = "¿Quieres venir conmigo?",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>Luo Song se inclina, mirando a Ah Ding.</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>Ah Ding, con la cara en el suelo, se levanta y tambalea hasta ponerse de pie.</color>",
  ui_story_5075_50750702_35_dialog_content = "¡Rugido!",
  ui_story_5075_50750702_36_dialog_content = "Ese es mi compañero para ti.",
  ui_story_5075_50750702_37_dialog_content = "Pero Ah Ding no está en condiciones de...",
  ui_story_5075_50750702_38_dialog_content = "Argh, si tan solo la Doncella del Dragón estuviera aquí.",
  ui_story_5075_50750702_39_dialog_content = "Estás pidiendo un poco demasiado, ¿no crees?",
  ui_story_5075_50750702_40_dialog_content = "Las deidades no aparecen ante nosotros solo porque lo pidamos, ¿sabes?",
  ui_story_5075_50750702_41_dialog_content = "Tu familia te regañaría por pedir ayuda todo el tiempo, y las deidades no son diferentes.",
  ui_story_5075_50750702_42_dialog_content = "Si, tienes razón.",
  ui_story_5075_50750702_43_dialog_content = "Para decir la verdad, la adoración y la oración no son más que pensamientos deseosos.",
  ui_story_5075_50750702_44_dialog_content = "Si las deidades eligen intervenir, es porque tienen sus propias razones para hacerlo.",
  ui_story_5075_50750702_45_dialog_content = "¡Pero aquí en el reino mortal, nuestros puños son nuestro método más confiable para alcanzar nuestros objetivos!",
  ui_story_5075_50750702_46_dialog_content = "No importa cuán difícil sea el camino, siempre podemos seguir adelante siempre que aún tengamos fuerza en nuestros puños.",
  ui_story_5075_50750702_47_dialog_content = "¡Rugido!",
  ui_story_5075_50750702_48_dialog_content = "¡Hora de que nos vayamos!",
  ui_story_5075_50750702_49_dialog_content = "La mejor de las suertes, a los dos.",
  ui_story_5075_50750702_50_dialog_content = "También deberíamos irnos.",
  ui_story_5075_50750702_51_dialog_content = "Ven, te llevaré a la finca de la familia Lin.",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>Palacio Real del Reino Ji</color>",
  ui_story_5075_50750801_2_dialog_content = "Mi Señor, hay noticias del Reino Ye de nuevo.",
  ui_story_5075_50750801_3_dialog_content = "¿Sobre los <color=#FFB400>cañones costeros</color> que pedimos del Reino Ye? ¿Ya llegaron?",
  ui_story_5075_50750801_4_dialog_content = "No... aún no...",
  ui_story_5075_50750801_5_dialog_content = "¿No? ¿No comenzaron a enviar después de subir el precio la última vez?",
  ui_story_5075_50750801_6_dialog_content = "El mensaje del Reino dice eso.",
  ui_story_5075_50750801_7_dialog_content = "Pero ha pasado medio mes y las mercancías aún no han llegado. Enviamos cartas instándolos, pero en su extremo...",
  ui_story_5075_50750801_8_dialog_content = "Déjame adivinar, ¿están subiendo el precio de nuevo?",
  ui_story_5075_50750801_9_dialog_content = "...Sí.",
  ui_story_5075_50750801_10_dialog_content = "La carta dice que el equipo de reparto desapareció en las montañas.",
  ui_story_5075_50750801_11_dialog_content = "Y considerando que son algo que nuestro Reino Ji necesita urgentemente, pueden disponer de algunas manos para ayudarnos a buscar.",
  ui_story_5075_50750801_12_dialog_content = "Pero necesitamos cubrir los costos de la búsqueda.",
  ui_story_5075_50750801_13_dialog_content = "Por supuesto, proponen que este costo se puede compensar con el préstamo que el Reino Ye nos pidió hace cinco años.",
  ui_story_5075_50750801_14_dialog_content = "Entonces, supongo que solo lo están usando como excusa para subir el precio.",
  ui_story_5075_50750801_15_dialog_content = "Si no aceptamos pagar, seguirán alegando que los cañones costeros están perdidos.",
  ui_story_5075_50750801_16_dialog_content = "Y la búsqueda puede continuar... para siempre.",
  ui_story_5075_50750801_17_dialog_content = "¡Ridículo!",
  ui_story_5075_50750801_18_dialog_content = "Hicimos el pedido tan pronto como los espíritus malignos comenzaron a actuar, pero se retrasó una y otra vez.",
  ui_story_5075_50750801_19_dialog_content = "Esta vez es el equipo de reparto el que ha desaparecido. ¿Cuál será su excusa la próxima vez? ¿Cañones desapareciendo misteriosamente en el aire?",
  ui_story_5075_50750801_20_dialog_content = "En la respuesta, deja claro que si intentan aprovecharse, ¡todas las transacciones entre nuestros reinos serán canceladas!",
  ui_story_5075_50750801_21_dialog_content = "Pero, mi Señor, los espíritus malignos han estado desatados por todas partes últimamente.",
  ui_story_5075_50750801_22_dialog_content = "Especialmente a lo largo de la costa, todas las regiones buscan apoyo en el palacio.",
  ui_story_5075_50750801_23_dialog_content = "Si los cañones costeros del Reino Ye no llegan pronto, podría ser difícil mantener la línea de defensa por más tiempo.",
  ui_story_5075_50750801_24_dialog_content = "¿Es difícil mantener la línea de defensa?",
  ui_story_5075_50750801_25_dialog_content = "¿Es el Reino Ye el único proveedor que queda en Longzhou?",
  ui_story_5075_50750801_26_dialog_content = "Nuestro Reino de Ji prospera con abundantes bienes y multitudes de comerciantes, y las ganancias diarias son incalculables.",
  ui_story_5075_50750801_27_dialog_content = "Si el envío por mar es desafiante ahora, podemos recurrir al transporte fluvial. Dado que el Reino Ye se niega al comercio justo, buscaremos a alguien más.",
  ui_story_5075_50750801_28_dialog_content = "El dinero hace todo posible. Siempre y cuando el precio sea el correcto, incluso las poderosas fuerzas de Yangjing estarán a mi mando.",
  ui_story_5075_50750801_29_dialog_content = "¿Qué pasa con las demandas del Reino Ye?",
  ui_story_5075_50750801_30_dialog_content = "Recházalos a todos.",
  ui_story_5075_50750801_31_dialog_content = "Sí, mi Señor.",
  ui_story_5075_50750801_32_dialog_content = "¡Humph, ahora incluso el Reino Ye se atreve a jugar conmigo.",
  ui_story_5075_50750801_33_dialog_content = "Es posible que hayan olvidado convenientemente la vergüenza cuando pidieron un préstamo a nuestro Reino Ji hace años.",
  ui_story_5075_50750801_34_dialog_content = "Hablando de eso, ese año también es cuando Zhuohua llegó al Reino de Ji.",
  ui_story_5075_50750801_35_dialog_content = "Asesor Principal, ¿qué piensas? Si Zhuohua realmente se convierte en mi nuera, ese dinero podría ser negociable.",
  ui_story_5075_50750801_36_dialog_content = "Mi Señor, no bromees. Zhuohua es una mujer ambiciosa y decidida. Este asunto no es una broma.",
  ui_story_5075_50750801_37_dialog_content = "Humph, soy muy consciente de eso.",
  ui_story_5075_50750801_38_dialog_content = "Es simplemente raro encontrar a alguien que pueda mantener al príncipe heredero tan bien en línea...",
  ui_story_5075_50750801_39_dialog_content = "No nos detengamos en asuntos triviales de niños. Mi Señor, ¿ha considerado una estrategia para la actual situación turbulenta?",
  ui_story_5075_50750801_40_dialog_content = "A lo largo de los años, nuestro Reino de Ji ha puesto un gran énfasis en el comercio. Necesidades como la comida y la maquinaria dependen del comercio con otros reinos.",
  ui_story_5075_50750801_41_dialog_content = "Si hay más situaciones como el incidente de hoy con el Reino Ye...",
  ui_story_5075_50750801_42_dialog_content = "El Reino de Ji ha estado centrado en el comercio durante siglos. Idear una nueva estrategia no es tarea fácil.",
  ui_story_5075_50750801_43_dialog_content = "Además, la amenaza de los espíritus malignos puede que no dure.",
  ui_story_5075_50750801_44_dialog_content = "Hablemos de esto algún otro día.",
  ui_story_5075_50750801_45_dialog_content = "Estoy cansado. Voy a volver a descansar ahora.",
  ui_story_5075_50750801_46_dialog_content = "... Entendido.",
  ui_story_5075_50750801_47_dialog_content = "¿Señor? Estás aquí.",
  ui_story_5075_50750801_48_dialog_content = "Escuché que los espíritus malignos en la bahía han aumentado su poder, y el caso del demonio sigue siendo un misterio.",
  ui_story_5075_50750801_49_dialog_content = "Además, después de separarnos en el palacio, ¡no he tenido noticias de PlayerName desde entonces!",
  ui_story_5075_50750801_50_dialog_content = "¿Qué perspectiva puede darme, señor?",
  ui_story_5075_50750801_51_dialog_content = "No te preocupes. Ese joven está seguro y a salvo, y las tareas asignadas a él van bien.",
  ui_story_5075_50750801_52_dialog_content = "Pero supongo que hay más cosas sobre las que quieres preguntar, ¿verdad?",
  ui_story_5075_50750801_53_dialog_content = "No voy a andar por las ramas y seré directo contigo entonces.",
  ui_story_5075_50750801_54_dialog_content = "Aconsejaste a PlayerName que permanezca encubierto y no alerte a nadie en el tribunal.",
  ui_story_5075_50750801_55_dialog_content = "¿Fue porque sospechaste un posible juego sucio o malicia?",
  ui_story_5075_50750801_56_dialog_content = "Para tu pregunta, en lugar de preguntarme a mí, ¿por qué no consultas con tu guardia?",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>Jiu</color>? Ella está en...",
  ui_story_5075_50750801_58_dialog_content = "No necesitas decírmelo. Soy un anciano y no puedo entender los juegos de ustedes, las jóvenes.",
  ui_story_5075_50750801_59_dialog_content = "Solo mírenlo ustedes mismos.",
  ui_story_5075_50750801_60_dialog_content = "... Ya veo. Gracias por la ilustración.",
  ui_story_5075_50750801_61_dialog_content = "Ah, aquí hay algo más. Permíteme disculparme contigo.",
  ui_story_5075_50750801_62_dialog_content = "Cuando veas al joven más tarde, por favor transmítele también mis disculpas.",
  ui_story_5075_50750801_63_dialog_content = "Anteriormente, le pasé algo al niño en tu nombre.",
  ui_story_5075_50750801_64_dialog_content = "Espero que resulte útil a su debido tiempo.",
  ui_story_5075_50750801_65_dialog_content = "(Él es, de hecho, muy cauteloso con alguien en la corte.)",
  ui_story_5075_50750801_66_dialog_content = "(Pero ¿quién puede ser para hacerlo tan cauteloso?)",
  ui_story_5075_50750801_67_dialog_content = "(Me pregunto si tiene algo que ver con el caso que Jiu está investigando...)",
  ui_story_5075_50750801_68_dialog_content = "(Hablando de eso, ¿por qué el palacio guarda silencio sobre el espionaje en la ciudad?)",
  ui_story_5075_50750801_69_dialog_content = "(¿Solo Jiu logró descubrirlo? ¿O alguien le permitió descubrirlo intencionalmente?)",
  ui_story_5075_50750801_70_dialog_content = "(Pero ella solo es una guardia para una princesa rehén, y solo lo está haciendo por mí.)",
  ui_story_5075_50750801_71_dialog_content = "(No es necesario que nadie en el tribunal haga esto, incluso si tienen segundas intenciones, a no ser que...)",
  ui_story_5075_50750801_72_dialog_content = "(La mente maestra detrás de la trama no está trabajando para el Reino Ji pero...)",
  ui_story_5075_50750801_73_dialog_content = "Bip.",
  ui_story_5075_50750801_74_dialog_content = "¿Un pájaro mensajero de la <color=#FFB400>Ministra Armilla</color>?",
  ui_story_5075_50750801_75_dialog_content = "Citó que no funcionaban lo suficientemente bien para evitar a los guardias como la razón por la que nunca me envió nada.",
  ui_story_5075_50750801_76_dialog_content = "Sabía que era solo una excusa.",
  ui_story_5075_50750801_77_dialog_content = "...",
  ui_story_5075_50750801_78_dialog_content = "¡Qué audaz de tu parte, Xuan Ji!",
  ui_story_5075_50750801_79_dialog_content = "Debo irme del palacio ahora.",
  ui_story_5075_50750801_80_dialog_content = "Consejero Jefe, según sus instrucciones, hemos retirado a los guardias de los alrededores.",
  ui_story_5075_50750801_81_dialog_content = "La princesa Zhuohua también ha recibido la carta.",
  ui_story_5075_50750801_82_dialog_content = "Bien.",
  ui_story_5075_50750902_1_dialog_content = "Aquí estamos. Bienvenido a la finca de la calle Yulin de la familia Lin.",
  ui_story_5075_50750902_2_dialog_content = "¿Eh? ¿No es esta la misma dirección que estaba escrita en esa nota?",
  ui_story_5075_50750902_3_dialog_content = "¿Nota?",
  ui_story_5075_50750902_4_dialog_content = "Recibí una caja de comida del palacio hoy temprano, y contenía un pequeño mapa con esta dirección marcada en él.",
  ui_story_5075_50750902_5_dialog_content = "También vino con esta insignia, pero no estoy seguro de qué se supone que debo hacer con ella.",
  ui_story_5075_50750902_6_dialog_content = "Esto es... una insignia de la Oficina de Inspección.",
  ui_story_5075_50750902_7_dialog_content = "Joven, ¿sabes que además de la marina, el Reino de Ji no mantiene ningún ejército regular en tierra?",
  ui_story_5075_50750902_8_dialog_content = "La protección de rutas vitales, la investigación de traiciones y la eliminación de espíritus malignos, todo ello recae bajo la responsabilidad de la Oficina de Inspección.",
  ui_story_5075_50750902_9_dialog_content = "Y la insignia en tu mano te permite movilizar las fuerzas de la Oficina de Inspección.",
  ui_story_5075_50750902_10_dialog_content = "Aparte de la guardia del palacio real, lo que tienes en tus manos es el mando de la fuerza más poderosa en Haojin.",
  ui_story_5075_50750902_11_dialog_content = "¿Quieres decir que he estado llevando algo tan importante todo este tiempo?",
  ui_story_5075_50750902_12_dialog_content = "¿Eh? Espera, ¿quién eres tú?",
  ui_story_5075_50750902_13_dialog_content = "Guildmaster, no hay necesidad de que salgas a saludarnos.",
  ui_story_5075_50750902_14_dialog_content = "Escuché una perturbación afuera, así que salí para ver qué estaba pasando.",
  ui_story_5075_50750902_15_dialog_content = "No esperaba que tuvieras invitados.",
  ui_story_5075_50750902_16_dialog_content = "Debes ser PlayerName, ¿verdad?",
  ui_story_5075_50750902_17_dialog_content = "A menudo he escuchado tu nombre de Zhong Xu, Liqing y Yuebai. Es mi fortuna finalmente conocerte hoy.",
  ui_story_5075_50750902_18_dialog_content = "Pero ahora no es el momento para charlas pequeñas.",
  ui_story_5075_50750902_19_dialog_content = "Joven, ¿puedes decirme por qué parecías tan sorprendido cuando me viste?",
  ui_story_5075_50750902_20_dialog_content = "Ah, lo siento por eso. Aun así, siento que te he visto en algún lugar antes.",
  ui_story_5075_50750902_21_dialog_content = "Creo que estaba en el fondo del océano... en los recuerdos del demonio que controla la niebla negra.",
  ui_story_5075_50750902_22_dialog_content = "¿Es Yoh?",
  ui_story_5075_50750902_23_dialog_content = "Eso creo.",
  ui_story_5075_50750902_24_dialog_content = "Así que estás al tanto de Yoh y su rencor contra la familia Lin. ¿Qué exactamente ocurrió entre ustedes?",
  ui_story_5075_50750902_25_dialog_content = "Esa es una larga historia.",
  ui_story_5075_50750902_26_dialog_content = "Hablemos adentro.",
  ui_story_5075_50750902_27_dialog_content = "Tengo algunos asuntos que atender. Yuebai, por favor, entretén a nuestro invitado por ahora.",
  ui_story_5075_50750902_28_dialog_content = "Muy bien.",
  ui_story_5075_50750902_29_dialog_content = "¿Te gustaría un poco de té?",
  ui_story_5075_50750902_30_dialog_content = "Oh, no gracias.",
  ui_story_5075_50750902_31_dialog_content = "Entendido. Quizás en otra ocasión.",
  ui_story_5075_50750902_32_dialog_content = "Jajaja... Casi olvido tu forma habitual de hacer las cosas.",
  ui_story_5075_50750902_33_dialog_content = "?",
  ui_story_5075_50750902_34_dialog_content = "No es nada. Simplemente no creo que necesitemos ninguna de esas formalidades sofocantes más.",
  ui_story_5075_50750902_35_dialog_content = "Vamos al grano. ¿Cuál es la historia entre Yoh y los Lins?",
  ui_story_5075_50750902_36_dialog_content = "Ves, la historia compartida entre la familia Lin y los demonios se remonta a mucho tiempo atrás.",
  ui_story_5075_50750902_37_dialog_content = "En ese momento, la Familia Lin era solo un pequeño gremio, uno que estaba al borde de la bancarrota debido a años de mal negocio.",
  ui_story_5075_50750902_38_dialog_content = "En un acto final de desesperación, el maestro del gremio intercambió la riqueza restante de la familia por un barco mercante, con la esperanza de encontrar un mejor medio de supervivencia a través del mar.",
  ui_story_5075_50750902_39_dialog_content = "No hace falta decir, él tuvo éxito.",
  ui_story_5075_50750902_40_dialog_content = "Ese fue el comienzo de las relaciones comerciales de la familia Lin con Astra.",
  ui_story_5075_50750902_41_dialog_content = "Recuerdo que Carleen me contó esta historia. Twin Pavilions Bay también comenzó a prosperar en ese momento.",
  ui_story_5075_50750902_42_dialog_content = "Entonces parece que ya sabes el resto.",
  ui_story_5075_50750902_43_dialog_content = "Sin embargo, lo más importante para nuestra situación actual es lo que sucedió después. En su viaje de regreso a Longzhou, el barco del maestro del gremio navegó accidentalmente hacia aguas en calma.",
  ui_story_5075_50750902_44_dialog_content = "La familia Lin no tenía esferas armilares en ese momento, ni tenían artesanos habilidosos como Xuan Ji para rescatarlos.",
  ui_story_5075_50750902_45_dialog_content = "El maestro del gremio y su tripulación pasaron una quincena a la deriva en el mar, y estuvieron peligrosamente cerca de agotar sus reservas de alimentos.",
  ui_story_5075_50750902_46_dialog_content = "Fue entonces cuando se encontraron con un banco de peces serpiente.",
  ui_story_5075_50750902_47_dialog_content = "Chen'ni dijo que los peces serpiente regresan a Longzhou en grandes cardúmenes cada invierno para poner sus huevos.",
  ui_story_5075_50750902_48_dialog_content = "¿Entonces el pez serpiente rescató al maestro del gremio?",
  ui_story_5075_50750902_49_dialog_content = "Precisamente.",
  ui_story_5075_50750902_50_dialog_content = "Siguiendo la escuela de peces serpiente, que consideraron un buen presagio, los llevó fuera de las aguas en calma y de regreso a las costas de Longzhou.",
  ui_story_5075_50750902_51_dialog_content = "Por esa razón, solo fletaba viajes de regreso desde Astra en los meses de invierno.",
  ui_story_5075_50750902_52_dialog_content = "A cambio de abundantes ofrendas de comida, los peces serpiente guiaron los barcos de la Familia Lin de manera segura a través del mar.",
  ui_story_5075_50750902_53_dialog_content = "Y así, el pez serpiente se convirtió en una especie de tótem para la Familia Lin.",
  ui_story_5075_50750902_54_dialog_content = "También es el homónimo de toda esta calle.",
  ui_story_5075_50750902_55_dialog_content = "Pero tras la muerte de ese antiguo maestro del gremio, el gremio Lin solo creció en escala con cada generación que pasaba.",
  ui_story_5075_50750902_56_dialog_content = "Pronto, las crecientes demandas del gremio no pudieron ser satisfechas con solo un viaje de regreso en invierno.",
  ui_story_5075_50750902_57_dialog_content = "En ese momento, el maestro de la guilda de ese tiempo comenzó a pedir a los peces serpiente cada vez más escoltas a través del mar.",
  ui_story_5075_50750902_58_dialog_content = "Espera, ¿él negoció... con pescado?",
  ui_story_5075_50750902_59_dialog_content = "Aunque estoy parado justo frente a ti, todavía no te has dado cuenta, ¿verdad?",
  ui_story_5075_50750902_60_dialog_content = "En aquel entonces, el líder de los peces serpiente era un <color=#FFB400>diabólico</color>.",
  ui_story_5075_50750902_61_dialog_content = "La línea de sangre de pez serpiente de la Familia Lin también comenzó en ese momento.",
  ui_story_5075_50750902_62_dialog_content = "Pero al exigir más escoltas de los peces serpiente sin considerar sus tendencias naturales, la Familia Lin no cumplió con su acuerdo original.",
  ui_story_5075_50750902_63_dialog_content = "Como resultado, los lazos entre ellos comenzaron a deteriorarse gradualmente.",
  ui_story_5075_50750902_64_dialog_content = "En un momento, un barco de la familia Lin incluso destruyó un hábitat de peces serpiente.",
  ui_story_5075_50750902_65_dialog_content = "Este incidente enfureció al líder actual del pez serpiente, y decidió terminar completamente su cooperación con la Familia Lin.",
  ui_story_5075_50750902_66_dialog_content = "Todavía recuerdo cómo el recién transformado Yoh irrumpió en mi patio y gritó cuánto me despreciaba.",
  ui_story_5075_50750902_67_dialog_content = "Bienvenido de nuevo, Guildmaster.",
  ui_story_5075_50750902_68_dialog_content = "Lo siento, tú...",
  ui_story_5075_50750902_69_dialog_content = "Jaja, escuché lo que dijiste hace un momento.",
  ui_story_5075_50750902_70_dialog_content = "Debe ser difícil para alguien tan joven como tú aceptar este tipo de cosas.",
  ui_story_5075_50750902_71_dialog_content = "No justificaré las acciones de la Familia Lin. Lo que hicieron nuestros predecesores fue realmente infiel.",
  ui_story_5075_50750902_72_dialog_content = "Sin embargo, como hombre de negocios, soy muy consciente de que la Familia Lin se benefició en última instancia de ello, convirtiéndose en el principal jugador en el sector empresarial de Haojin.",
  ui_story_5075_50750902_73_dialog_content = "Si yo hubiera sido el que tomaba las decisiones en ese momento, probablemente habría hecho lo mismo.",
  ui_story_5075_50750902_74_dialog_content = "Si no hubiéramos recibido información sobre la esfera armilar con anticipación, la familia Lin no lo habría liberado tan fácilmente.",
  ui_story_5075_50750902_75_dialog_content = "Es posible que lo hayan mantenido cautivo, usándolo como un peón.",
  ui_story_5075_50750902_76_dialog_content = "Me odia, odia a la familia Lin, y con razón.",
  ui_story_5075_50750902_77_dialog_content = "Romper promesas y traicionar la confianza, de hecho, la familia Lin cometió tales actos en el pasado.",
  ui_story_5075_50750902_78_dialog_content = "Ahora, la familia Lin está cosechando lo que sembró.",
  ui_story_5075_50750902_79_dialog_content = "Los espíritus malvados vagan por las áreas costeras, sin embargo, el Reino de Ji aún no puede establecer una línea de defensa estable.",
  ui_story_5075_50750902_80_dialog_content = "Según escuché, los cañones costeros que pedimos del Reino Ye aún no han llegado.",
  ui_story_5075_50750902_81_dialog_content = "Los barcos comerciales de la Familia Lin hace tiempo que no pueden navegar, y los negocios costeros están estancados. Nunca llueve pero diluvia.",
  ui_story_5075_50750902_82_dialog_content = "Tan pronto como me extraje de las Oficinas de Comercio Marítimo, fui descaradamente directo a Yoh, sin tener en cuenta el mejor juicio de Zhong.",
  ui_story_5075_50750902_83_dialog_content = "Esperaba que pudiera ayudar a la Familia Lin a explorar las rutas acuáticas y proteger los barcos comerciales. Por supuesto, me echaron.",
  ui_story_5075_50750902_84_dialog_content = "Según PlayerName, después de todo, fue a investigar la situación en el mar...",
  ui_story_5075_50750902_85_dialog_content = "Pero luego fue corrompido por la influencia del malvado dragón, lo que le hizo perder el control e infectar a todos los demonios cercanos con su rencor.",
  ui_story_5075_50750902_86_dialog_content = "... La familia Lin tiene la responsabilidad de este incidente, y nos corresponde a nosotros rectificarlo.",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50750902_88_dialog_content = "¡Expulsa a esos demonios!",
  ui_story_5075_50750902_89_dialog_content = "¿Qué está pasando afuera?",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>Luo Song se enfrenta a una multitud de habitantes enfadados en el centro de la calle, protegiendo a varios fiendlings que yacen inconscientes en el suelo.</color>",
  ui_story_5075_50751001_2_dialog_content = "¡Cálmense todos! ¡Estos diablillos nunca quisieron hacer daño a nadie!",
  ui_story_5075_50751001_3_dialog_content = "Ya los he sometido. Todo lo que queda es eliminar la corrupción de sus cuerpos y—",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>¡Wham!</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>Una piedra sale volando de la multitud, golpeando a Luo Song.</color>",
  ui_story_5075_50751001_6_dialog_content = "¡Rugido!",
  ui_story_5075_50751001_7_dialog_content = "¡Ah Ding! ¡Tú también necesitas calmarte!",
  ui_story_5075_50751001_8_dialog_content = "Estoy bien, lo prometo. No podemos permitirnos pelear con ellos, no ahora mismo.",
  ui_story_5075_50751001_9_dialog_content = "Las personas ya están heridas. ¡A quién le importa si lo hicieron a propósito o no!",
  ui_story_5075_50751001_10_dialog_content = "¡Te dije que esos demonios no son buenos! Robar cosas es una cosa, ¡pero ahora están matando gente!",
  ui_story_5075_50751001_11_dialog_content = "Haojin ha sido pacífica durante siglos, ¡pero hoy incluso hay espíritus malignos en la ciudad!",
  ui_story_5075_50751001_12_dialog_content = "¿Y todavía afirmas que no son los diablillos los que causan problemas? ¡Son obviamente los mismos! ¡Igual de malvados!",
  ui_story_5075_50751001_13_dialog_content = "Ustedes conocen la magia, así que les resulta fácil hablar sin sentir miedo.",
  ui_story_5075_50751001_14_dialog_content = "¡No les tienes miedo, pero nosotros sí!",
  ui_story_5075_50751001_15_dialog_content = "No podemos permitir que estas cosas ominosas permanezcan en la ciudad. ¡Expúlsalas a todas!",
  ui_story_5075_50751001_16_dialog_content = "¡Expúlsalos! ¡EXPÚLSALOS!",
  ui_story_5075_50751001_17_dialog_content = "Tengo que ayudarlo—",
  ui_story_5075_50751001_18_dialog_content = "Espera. Si sales allí sin estar preparado, solo empeorarás las cosas.",
  ui_story_5075_50751001_19_dialog_content = "Una multitud enfadada no escuchará la razón, no importa si está bien o mal.",
  ui_story_5075_50751001_20_dialog_content = "Aparte de una demostración de fuerza aún más poderosa, la única forma de hacerlos calmarse es ofreciéndoles una garantía indiscutible de que las cosas mejorarán.",
  ui_story_5075_50751001_21_dialog_content = "¡Tengo esa insignia! ¿No significa eso que puedo llamar a la Oficina de Inspección para que nos ayude?",
  ui_story_5075_50751001_22_dialog_content = "La Oficina de Inspección debería estar manejando los Eclipsites dispersos por toda la ciudad en este momento.",
  ui_story_5075_50751001_23_dialog_content = "Además, si intervinieran... Me temo que estas personas solo se agitarían más.",
  ui_story_5075_50751001_24_dialog_content = "Pero tiene que haber algo que podamos hacer...",
  ui_story_5075_50751001_25_dialog_content = "Ya dije que sí, ¿no? Más específicamente, la familia Lin tiene una solución.",
  ui_story_5075_50751001_26_dialog_content = "Maestro del gremio, tengo un favor que pedirte.",
  ui_story_5075_50751001_27_dialog_content = "Solicito formalmente la autoridad para <color=#FFB400>actuar en nombre del maestro del gremio Lin</color> de Haojin.",
  ui_story_5075_50751001_28_dialog_content = "Por favor, concédeme el derecho de asignar a las personas y recursos de la familia Lin para resolver este incidente.",
  ui_story_5075_50751001_29_dialog_content = "¿Cuál es tu plan?",
  ui_story_5075_50751001_30_dialog_content = "A pesar de la disminución de la prominencia del Gremio Lin en los últimos años, el hecho permanece que todavía somos una organización de larga data con estrechos lazos con la gente.",
  ui_story_5075_50751001_31_dialog_content = "Deseo ofrecer a la gente de esta ciudad una promesa de seguridad en nombre de la guilda y enviar a nuestros médicos para tratar a los heridos.",
  ui_story_5075_50751001_32_dialog_content = "¿Entiendes lo que está en juego con tus palabras habladas casualmente?",
  ui_story_5075_50751001_33_dialog_content = "Sí, la Familia Lin tiene una considerable riqueza, pero no hasta el punto de que podamos asumir el bienestar de toda la población de una ciudad.",
  ui_story_5075_50751001_34_dialog_content = "Además, la familia Lin estuvo involucrada en un caso de contrabando antes, y nos costó mucho esfuerzo limpiar nuestro nombre.",
  ui_story_5075_50751001_35_dialog_content = "El mundo de los negocios es como un campo de batalla, está bien jugar sucio detrás de escena, pero nuestra imagen pública debe permanecer limpia.",
  ui_story_5075_50751001_36_dialog_content = "Estás usando el nombre de la Familia Lin para avalar a los demonios. Cualquier error, y la Familia Lin se convertirá en un objetivo público.",
  ui_story_5075_50751001_37_dialog_content = "Soy muy consciente de esto.",
  ui_story_5075_50751001_38_dialog_content = "Pero Yoh está detrás de la amenaza de los demonios, y los Lins son la causa original del rencor.",
  ui_story_5075_50751001_39_dialog_content = "Los Lin deben ser responsabilizados.",
  ui_story_5075_50751001_40_dialog_content = "Los tiempos han cambiado, en efecto.",
  ui_story_5075_50751001_41_dialog_content = "El reino de Ji valora el comercio, y los comerciantes siempre priorizan las ganancias.",
  ui_story_5075_50751001_42_dialog_content = "Cuando era joven, todos peleaban por la más mínima ganancia, codiciando incluso un tazón de arroz en la mano de un mendigo.",
  ui_story_5075_50751001_43_dialog_content = "Y los Lin incluso sacrificarían el pez serpiente que habían consagrado durante generaciones para servir a sus intereses.",
  ui_story_5075_50751001_44_dialog_content = "¿Así que ahora quieres que arriesgue todo por lo que he trabajado duro solo por \"responsabilidad\"?",
  ui_story_5075_50751001_45_dialog_content = "Mis palabras están lejos de ser vacías, Guildmaster. Sé que puedo hacerlas realidad.",
  ui_story_5075_50751001_46_dialog_content = "¡Espera, ustedes dos! Ahora no es el momento para discutir...",
  ui_story_5075_50751001_47_dialog_content = "Tengo un mantra para que aprendas.",
  ui_story_5075_50751001_48_dialog_content = "No importa con qué problemas te encuentres, solo repítelo, y la mayoría de las cosas estarán bien.",
  ui_story_5075_50751001_49_dialog_content = "(Aunque dudo que ayude, ¡no lo sabré a menos que lo intente!)",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>Merry... <size=45>Merry ¡Año Nuevo!</size></color>",
  ui_story_5075_50751001_51_dialog_content = "...",
  ui_story_5075_50751001_52_dialog_content = "...",
  ui_story_5075_50751001_53_dialog_content = "Jajaja... Es un año nuevo.",
  ui_story_5075_50751001_54_dialog_content = "Despídete de lo viejo y da la bienvenida a lo nuevo, es hora de un nuevo comienzo.",
  ui_story_5075_50751001_55_dialog_content = "Después de todas las preparaciones, el día oficial del Festival de Primavera es mañana, ¿no?",
  ui_story_5075_50751001_56_dialog_content = "Así es.",
  ui_story_5075_50751001_57_dialog_content = "¿Está todo listo? ¿Qué tal la cena de Eve Año Nuevo?",
  ui_story_5075_50751001_58_dialog_content = "La mayoría de nuestros ingredientes han sido colocados en almacenamiento en frío, y las verduras frescas nos serán entregadas ese día.",
  ui_story_5075_50751001_59_dialog_content = "Las cuentas del gremio se liquidaron hace dos días. Se ha colocado un resumen en tu estudio para que lo leas cuando te sea conveniente.",
  ui_story_5075_50751001_60_dialog_content = "El negocio de nuestro gremio volvió a tener dificultades este año, pero aún así consideré apropiado recompensar a los guardias y trabajadores con dos meses adicionales de salarios.",
  ui_story_5075_50751001_61_dialog_content = "Seguro que tienes una mente propia.",
  ui_story_5075_50751001_62_dialog_content = "Al navegar el siempre caprichoso mar, un capitán debe responder de manera rápida y decisiva.",
  ui_story_5075_50751001_63_dialog_content = "Un viento de cola o una corriente ascendente pueden pasarse por alto completamente si no logro aprovecharlos a tiempo.",
  ui_story_5075_50751001_64_dialog_content = "¿Crees que lo que estamos enfrentando ahora es un viento a favor para la Familia Lin?",
  ui_story_5075_50751001_65_dialog_content = "Si estás seguro de ello, aceptaré tu solicitud.",
  ui_story_5075_50751001_66_dialog_content = "Gracias a Dios... Estás bien...",
  ui_story_5075_50751001_67_dialog_content = "<size=45>No puedo.</size>",
  ui_story_5075_50751001_68_dialog_content = "Hola—",
  ui_story_5075_50751001_69_dialog_content = "Sé muy bien que cualquier esquema o cálculo puede ser arrastrado instantáneamente por una ola lo suficientemente grande.",
  ui_story_5075_50751001_70_dialog_content = "Cuando eso sucede, lo único que evitará que el barco vuelque es una quilla fuerte y estable.",
  ui_story_5075_50751001_71_dialog_content = "La columna vertebral de un barco nunca debería doblarse o romperse.",
  ui_story_5075_50751001_72_dialog_content = "...",
  ui_story_5075_50751001_73_dialog_content = "Tal vez tu evaluación sobre la situación actual sea correcta, pero sigo siendo un producto de la vieja era.",
  ui_story_5075_50751001_74_dialog_content = "Desde donde estoy, tus acciones son demasiado radicales y arriesgadas.",
  ui_story_5075_50751001_75_dialog_content = "Maestro del gremio—",
  ui_story_5075_50751001_76_dialog_content = "Sin embargo, eres el capitán del Shadowind, manteniendo las rutas de envío cruciales para la familia Lin.",
  ui_story_5075_50751001_77_dialog_content = "En los ojos de los demás, lo que dices representa a toda la familia Lin.",
  ui_story_5075_50751001_78_dialog_content = "¿Significa esto...",
  ui_story_5075_50751001_79_dialog_content = "Puede que sea anticuado, pero ante todo, soy un hombre de negocios que considera varios factores y sopesa los pros y los contras.",
  ui_story_5075_50751001_80_dialog_content = "Eres un capitán capaz de dominar los complejos barcos modernos y ciertamente eres libre de hacer lo que quieras.",
  ui_story_5075_50751001_81_dialog_content = "Si tienes éxito, serás un héroe para Lin Guild, y también te pondré a cargo de las rutas marítimas cerca de Longzhou.",
  ui_story_5075_50751001_82_dialog_content = "Si no funciona, serás alguien que ha violado la orden del maestro del gremio, actuando sin permiso.",
  ui_story_5075_50751001_83_dialog_content = "La familia puede repudiarte pronto, e incluso podrías perder tu apellido.",
  ui_story_5075_50751001_84_dialog_content = "¿Puedes aceptar estas condiciones?",
  ui_story_5075_50751001_85_dialog_content = "<size=45>Acepto.</size>",
  ui_story_5075_50751001_86_dialog_content = "Vamos, PlayerName.",
  ui_story_5075_50751001_87_dialog_content = "Claro... Oh, pero solo un segundo.",
  ui_story_5075_50751001_88_dialog_content = "¿Puedes guardar este insignia seguro por mí por el momento, Guildmaster?",
  ui_story_5075_50751001_89_dialog_content = "¿Confiarías en mí con algo tan importante?",
  ui_story_5075_50751001_91_dialog_content = "No olvides que soy una persona engañosa y sin escrúpulos.",
  ui_story_5075_50751001_92_dialog_content = "Jaja... Estaría mintiendo si dijera que esta decisión me ha tranquilizado completamente.",
  ui_story_5075_50751001_93_dialog_content = "Pero no veo ninguna oportunidad de usarlo pronto, y el mapa que venía con él también me señaló tu dirección.",
  ui_story_5075_50751001_94_dialog_content = "Sigues insistiendo en que no eres digno de confianza, pero Yuebai y Zhong Xu aún creen en ti.",
  ui_story_5075_50751001_95_dialog_content = "Y confío en su juicio.",
  ui_story_5075_50751001_96_dialog_content = "Mis habilidades psíquicas también me dicen que incluso si intentas hacer algo malo con ello, alguien aquí te detendrá.",
  ui_story_5075_50751001_97_dialog_content = "Bueno, en ese caso, me lo llevo.",
  ui_story_5075_50751001_98_dialog_content = "Gracias.",
  ui_story_5075_50751001_99_dialog_content = "Vamos, Yuebai, vámonos—",
  ui_story_5075_50751001_100_dialog_content = "Jaja, la generación más joven.",
  ui_story_5075_50751001_101_dialog_content = "Siempre dirigiéndose a lugares arriesgados, todavía son demasiado impulsivos. Es difícil sentirse tranquilo sobre el futuro de la familia Lin.",
  ui_story_5075_50751001_102_dialog_content = "Bueno, tu expresión dice lo contrario.",
  ui_story_5075_50751001_103_dialog_content = "Prácticamente grita, \"Los Lins tienen muchos sucesores esperando en las alas.\"",
  ui_story_5075_50751001_104_dialog_content = "Jajaja, Zhong Xu, realmente tienes ojos agudos.",
  ui_story_5075_50751001_105_dialog_content = "Esperaba desenredar lentamente los problemas del pasado y dejar las cosas limpias para la próxima generación.",
  ui_story_5075_50751001_106_dialog_content = "No esperaba que ella estuviera un paso adelante de mí y que ya hubiera asumido esta responsabilidad antes de que pudiera intervenir.",
  ui_story_5075_50751001_107_dialog_content = "Pero Zhong Xu, has estado observando desde las sombras. ¿Por qué no echas una mano?",
  ui_story_5075_50751001_108_dialog_content = "PlayerName ya ha notado tu participación.",
  ui_story_5075_50751001_109_dialog_content = "Entonces, ¿lo hiciste?",
  ui_story_5075_50751001_110_dialog_content = "Nuestro joven amigo incluso trajo el emblema de la Oficina de Inspección aquí, y aún así te negaste a hablar sobre tu trato con el Asesor Jefe.",
  ui_story_5075_50751001_111_dialog_content = "Es obvio que le prometiste que le ayudarías. Tan pronto como nuestro joven amigo llegó aquí, me instaron a movilizar a los guardias de Lin.",
  ui_story_5075_50751001_112_dialog_content = "Entonces, ¿por qué fingir?",
  ui_story_5075_50751001_113_dialog_content = "La forma en que andamos con rodeos, es difícil para nosotros los ancianos comunicarnos con los jóvenes.",
  ui_story_5075_50751001_114_dialog_content = "Solo piénsalo como mi preparación para el Festival de Primavera, una ceremonia de despedida del viejo y bienvenida del nuevo.",
  ui_story_5075_50751001_115_dialog_content = "¿Ves? Aún no es el Festival de Primavera y ya estamos escuchando tantas palabras bonitas.",
  ui_story_5075_50751001_116_dialog_content = "Este es un buen augurio, ¿no es así?",
  ui_story_5075_50751001_117_dialog_content = "¡Deja de decir tonterías! Este tipo está defendiendo al diablillo. Definitivamente no trama nada bueno.",
  ui_story_5075_50751001_118_dialog_content = "Hazte a un lado ahora y déjanos expulsar a este ser maligno antes de que sea demasiado tarde.",
  ui_story_5075_50751001_119_dialog_content = "De lo contrario, incluso si tienes magia, no te lo pondremos fácil.",
  ui_story_5075_50751001_120_dialog_content = "Sé que todos están asustados, pero tenemos que ser razonables sobre esto—",
  ui_story_5075_50751001_121_dialog_content = "¡Expúlsalos a todos!",
  ui_story_5075_50751001_122_dialog_content = "¡Expúlsalos!",
  ui_story_5075_50751001_123_dialog_content = "¡Rugido!",
  ui_story_5075_50751001_124_dialog_content = "Esto es malo. No pude reunir a todos los diablillos...",
  ui_story_5075_50751001_125_dialog_content = "¡Constricción de serpiente!",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>Mu Yuebai corta rápidamente a través de la manada de demonios como una daga afilada como una navaja.</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>La multitud apenas tiene tiempo para reaccionar. El demonio que estaba rabioso hace un segundo ya ha perdido la conciencia, colapsando al suelo.</color>",
  ui_story_5075_50751002_3_dialog_content = "¿Quién... Quién es ese? ¡Es increíble!",
  ui_story_5075_50751002_4_dialog_content = "¡Lo sé! Ese es el Capitán Mu del gremio Lin.",
  ui_story_5075_50751002_5_dialog_content = "Pero su cola... Ella tiene sangre de fiundling en ella, ¿no es así...",
  ui_story_5075_50751002_6_dialog_content = "¿Cómo puedes decir eso? ¡Ella acaba de salvarnos!",
  ui_story_5075_50751002_7_dialog_content = "Todos, por favor escuchen lo que tengo que decir.",
  ui_story_5075_50751002_8_dialog_content = "Sé que hoy ha sido un día aterrador. Algunos han resultado heridos mientras que otros han sufrido pérdidas.",
  ui_story_5075_50751002_9_dialog_content = "Comparto las frustraciones de todos.",
  ui_story_5075_50751002_10_dialog_content = "Pero estos diablillos no son responsables de los problemas que hemos estado experimentando. Son simplemente las marionetas de un culpable aún más siniestro.",
  ui_story_5075_50751002_11_dialog_content = "Al luchar solo contra los demonios, estamos cayendo justo en su trampa.",
  ui_story_5075_50751002_12_dialog_content = "¡Compartes su linaje, y por eso dirías eso!",
  ui_story_5075_50751002_13_dialog_content = "Pero soy más auroriano que pez serpiente, eso siempre ha sido cierto. Además, la Familia Lin hace negocios con personas, no con diabólicos.",
  ui_story_5075_50751002_14_dialog_content = "¿Por qué iba a perjudicar las perspectivas de nuestro gremio trabajando en tu contra?",
  ui_story_5075_50751002_15_dialog_content = "...",
  ui_story_5075_50751002_16_dialog_content = "Las palabras a menudo carecen de fundamento, y sé que no tengo derecho a pedirte que creas en mis palabras.",
  ui_story_5075_50751002_17_dialog_content = "Pero en nombre del Lin Guild, prometo proporcionarles a todos pruebas irrefutables de la verdad detrás de este incidente.",
  ui_story_5075_50751002_18_dialog_content = "No podemos permitirnos ser engañados y explotados por nuestro enemigo. Hacerlo solo les permitirá operar con total impunidad.",
  ui_story_5075_50751002_19_dialog_content = "Incluso si dices eso...",
  ui_story_5075_50751002_20_dialog_content = "(Ellos aún no están completamente convencidos, pero ¿qué podemos ofrecerles como prueba? ... Espera, ¡lo tengo!)",
  ui_story_5075_50751002_21_dialog_content = "¡Potencia de fuerza!",
  ui_story_5075_50751002_22_dialog_content = "(Por favor, aunque sea solo un poco, déjame mostrar a todos lo que veo...)",
  ui_story_5075_50751002_23_dialog_content = "¡Todos! Por favor, echen un vistazo más de cerca a estos fiendlings!",
  ui_story_5075_50751002_24_dialog_content = "¿Qué diablos es eso?",
  ui_story_5075_50751002_25_dialog_content = "Esto es lo que el verdadero culpable está usando para controlar a estos demonios.",
  ui_story_5075_50751002_26_dialog_content = "Mientras sigan infectados con este poder, expulsar a los demonios de la ciudad no cambiará nada.",
  ui_story_5075_50751002_27_dialog_content = "Ellos... en realidad no parecen estar mintiendo.",
  ui_story_5075_50751002_28_dialog_content = "Los Lins realmente han hecho mucho por todos durante los años, pero...",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>Se agrupan y, después de una breve discusión en susurros, envían a un representante.</color>",
  ui_story_5075_50751002_30_dialog_content = "Bien, confiaremos en ti por ahora.",
  ui_story_5075_50751002_31_dialog_content = "Se está haciendo tarde y no queremos perder tiempo aquí.",
  ui_story_5075_50751002_32_dialog_content = "Pero todavía hay algunos demonios acechando en la ciudad. ¿Quién sabe qué podrían hacer mientras estás investigando?",
  ui_story_5075_50751002_33_dialog_content = "Entonces, tenemos una condición.",
  ui_story_5075_50751002_34_dialog_content = "Tienes que resolver esto antes del Festival de Primavera, para que todos podamos disfrutar de unas buenas vacaciones.",
  ui_story_5075_50751002_35_dialog_content = "Entendido.",
  ui_story_5075_50751002_36_dialog_content = "¡Así es! ¡Es el Año Nuevo! ¡Todos quieren que este problema se resuelva lo antes posible!",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>Mu Yuebai envía gente para aplacar a la multitud mientras finalmente se dispersan.</color>",
  ui_story_5075_50751002_38_dialog_content = "Gracias por tu ayuda.",
  ui_story_5075_50751002_39_dialog_content = "Enfrentarme a tantas personas por mi cuenta habría sido verdaderamente agotador.",
  ui_story_5075_50751002_40_dialog_content = "Cuando dices \"asumir\", no te refieres a...",
  ui_story_5075_50751002_41_dialog_content = "No importa. El Festival de Primavera está a solo un día de distancia, así que es mejor que nos apuremos.",
  ui_story_5075_50751002_42_dialog_content = "Afortunadamente, hemos logrado desenterrar muchas pistas.",
  ui_story_5075_50751002_43_dialog_content = "Para comenzar, alguien destruyó el sello de Chen'ni, permitiendo que el poder del dragón negro surgiera del mar.",
  ui_story_5075_50751002_44_dialog_content = "Aunque ese poder tiene una serie de propiedades únicas, al final del día sigue siendo solo un tipo de Darkflow.",
  ui_story_5075_50751002_45_dialog_content = "Ese Darkflow, a su vez, ha atraído a muchos Eclipsites a las costas de Haojin, impidiendo que los barcos de la Familia Lin salgan y deteniendo efectivamente su negocio.",
  ui_story_5075_50751002_46_dialog_content = "Obligó al maestro del gremio Lin a buscar a Yoh, el demonio con el que trabajaba, y pedirle que encontrara el motivo de la congregación de los Eclipsites.",
  ui_story_5075_50751002_47_dialog_content = "Solo para que Yoh sea manchado por la niebla oscura durante la investigación y quede con nada más que odio hacia la Familia Lin.",
  ui_story_5075_50751002_48_dialog_content = "Y después de adquirir un recipiente físico, la niebla negra se volvió aún más activa y comenzó a afectar a los demonios en la zona.",
  ui_story_5075_50751002_49_dialog_content = "Su influencia finalmente se infiltró en la ciudad de Haojin.",
  ui_story_5075_50751002_50_dialog_content = "Por lo tanto, tenemos que encontrar a Yoh primero y eliminar la corrupción de él.",
  ui_story_5075_50751002_51_dialog_content = "Después de eso, necesitamos encontrar una forma de sellar la niebla negra, tal como lo hizo Chen'ni en el pasado.",
  ui_story_5075_50751002_52_dialog_content = "Entonces, ¿qué estamos esperando?",
  ui_story_5075_50751002_53_dialog_content = "¡Chirrido!",
  ui_story_5075_50751002_54_dialog_content = "¡Llama Guardiana Demoníaca!",
  ui_story_5075_50751002_55_dialog_content = "¡Argh, la niebla negra se ha extendido por la mayor parte de la ciudad! Cada vez más demonios están sucumbiendo a sus efectos.",
  ui_story_5075_50751002_56_dialog_content = "Deberías quedarte aquí, Luo Song.",
  ui_story_5075_50751002_57_dialog_content = "Necesitan tu ayuda.",
  ui_story_5075_50751002_58_dialog_content = "Bien. Pero antes de que te vayas, aquí—",
  ui_story_5075_50751002_59_dialog_content = "¿Qué es esto?",
  ui_story_5075_50751002_60_dialog_content = "Un choque de puños.",
  ui_story_5075_50751002_61_dialog_content = "Esto nos hará amigos en una lucha común.",
  ui_story_5075_50751002_62_dialog_content = "Cuando regreses, te invitaré a algunos de los castañas de agua más frescas del mundo.",
  ui_story_5075_50751002_63_dialog_content = "¡Está bien!",
  ui_story_5075_50751002_64_dialog_content = "Me voy a buscar más demonios corruptos. ¡Haz lo mejor que puedas allí afuera!",
  ui_story_5075_50751002_65_dialog_content = "¡Lo haré! Ahora a encontrar a Yuebai... ¿Eh?",
  ui_story_5075_50751002_66_dialog_content = "Su Excelencia, finalmente lo hemos encontrado de nuevo.",
  ui_story_5075_50751002_67_dialog_content = "Realmente sabes cómo... deambular.",
  ui_story_5075_50751002_68_dialog_content = "Es el administrador... ¿Q-Qué lo trae por aquí, señor?",
  ui_story_5075_50751002_69_dialog_content = "Dado el aumento de seres malignos en la ciudad, es nuestro deber garantizar tu seguridad.",
  ui_story_5075_50751002_70_dialog_content = "Por favor, síganos de regreso a la Casa de Huéspedes Real.",
  ui_story_5075_50751002_71_dialog_content = "Lo siento, pero no puedo volver ahora mismo. Todavía tengo algo importante que hacer.",
  ui_story_5075_50751002_72_dialog_content = "Por favor, no nos complique las cosas. Eres un invitado distinguido que ha venido desde lejos a nuestro Reino Ji.",
  ui_story_5075_50751002_73_dialog_content = "Si algo te sucede, podríamos terminar perdiendo nuestras cabezas. Por favor, comprende nuestra situación.",
  ui_story_5075_50751002_74_dialog_content = "¡Escolta al estimado emisario de regreso a la casa de huéspedes!",
  ui_story_5075_50751002_75_dialog_content = "¡Espera! ¡Suéltame—",
  ui_story_5075_50751002_76_dialog_content = "Regrese, PlayerName.",
  ui_story_5075_50751002_77_dialog_content = "... PlayerName?",
  ui_story_5075_50751101_1_dialog_content = "¡Flores, floreciendo sin fin!",
  ui_story_5075_50751101_2_dialog_content = "Mmm...",
  ui_story_5075_50751101_3_dialog_content = "Todos ustedes parecen ser asesinos hábiles, sin embargo, ninguno de sus movimientos es letal.",
  ui_story_5075_50751101_4_dialog_content = "¿Es la intención distraerme y retrasarme?",
  ui_story_5075_50751101_5_dialog_content = "...",
  ui_story_5075_50751101_6_dialog_content = "Incluso cuando fingí golpes a los puntos vitales, no contraatacaste.",
  ui_story_5075_50751101_7_dialog_content = "Varios están heridos mientras yo permanezco ileso.",
  ui_story_5075_50751101_8_dialog_content = "Jeje. Creo que finalmente entiendo lo que PlayerName quería decir ahora.",
  ui_story_5075_50751101_9_dialog_content = "Es extraño ser tratado tan amablemente de la nada.",
  ui_story_5075_50751101_10_dialog_content = "Pero hay una razón detrás de cada peculiaridad en el mundo.",
  ui_story_5075_50751101_11_dialog_content = "Lo que la Ministra Armilla escribió en su mensaje, lo que Jiu mencionó antes de irse, y los consejos de mi mentor.",
  ui_story_5075_50751101_12_dialog_content = "Solo un idiota no podría descifrarlo con tantas pistas.",
  ui_story_5075_50751101_13_dialog_content = "Eres espías para el Reino Ye, ¿verdad?",
  ui_story_5075_50751101_14_dialog_content = "!",
  ui_story_5075_50751101_15_dialog_content = "Su Alteza, ha adivinado correctamente. Ahora debería saber que no pretendemos hacerle daño.",
  ui_story_5075_50751101_16_dialog_content = "Las cosas se están complicando en la ciudad de Haojin. Así que por favor, Su Alteza, regrese al palacio por su seguridad.",
  ui_story_5075_50751101_17_dialog_content = "¿Mi salida del palacio ahora arruinará tus planes?",
  ui_story_5075_50751101_18_dialog_content = "Entre dos reinos, los conflictos de ida y vuelta, tanto abiertos como detrás de escena, son un suceso común.",
  ui_story_5075_50751101_19_dialog_content = "Su Alteza, es bondadoso, y <color=#FFB400>nuestro señor</color> no quiere verlo en una situación difícil. Por lo tanto, por favor regrese.",
  ui_story_5075_50751101_20_dialog_content = "... <color=#FFB400>Tu señor</color>.",
  ui_story_5075_50751101_21_dialog_content = "Su Alteza, si insiste en ir en contra de nuestro consejo, tendremos que recurrir a la fuerza.",
  ui_story_5075_50751101_22_dialog_content = "¡Ve a buscarla!",
  ui_story_5075_50751101_23_dialog_content = "¡Levántate sea el viento!",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>Chasquido—</color>",
  ui_story_5075_50751101_25_dialog_content = "¿Está herido, Su Alteza?",
  ui_story_5075_50751101_26_dialog_content = "Jiu? Pensé que estabas ocupado y que no volverías por un tiempo.",
  ui_story_5075_50751101_27_dialog_content = "Mi deber es protegerte.",
  ui_story_5075_50751101_28_dialog_content = "Mientras me necesites, volveré a tu lado esté donde esté.",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>De repente, una mano agarra el tobillo de Jiu.</color>",
  ui_story_5075_50751101_30_dialog_content = "Escarcha... Espada... No puedes...",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>Chasquido—</color>",
  ui_story_5075_50751101_32_dialog_content = "Tengo la sensación de que te pediré mucho más tarde.",
  ui_story_5075_50751101_33_dialog_content = "Pero tenemos un asunto urgente entre manos. Ven conmigo a ver a PlayerName de inmediato.",
  ui_story_5075_50751101_34_dialog_content = "¿Sabe dónde está PlayerName, Su Alteza?",
  ui_story_5075_50751101_35_dialog_content = "Estaba demasiado apurado para preguntar...",
  ui_story_5075_50751101_36_dialog_content = "¿Puedo interesarte en una pequeña adivinación?",
  ui_story_5075_50751101_37_dialog_content = "... Li Tianxian.",
  ui_story_5075_50751101_38_dialog_content = "¿Has estado observando todo este tiempo?",
  ui_story_5075_50751101_39_dialog_content = "¿Qué estás diciendo? Acabo de vender todas mis figuritas de azúcar y tengo un presentimiento.",
  ui_story_5075_50751101_40_dialog_content = "Tenía la sensación de que me encontraría con alguien importante de esta manera, así que aquí estoy, probando mi suerte.",
  ui_story_5075_50751101_41_dialog_content = "Pero no vi nada que no debía ver. Lo juro.",
  ui_story_5075_50751101_42_dialog_content = "No importa. Olvídalo.",
  ui_story_5075_50751101_43_dialog_content = "Veo que es difícil conseguir nuevos clientes. PlayerName sigue siendo el mejor para creer todo lo que digo.",
  ui_story_5075_50751101_44_dialog_content = "... ¿Viste PlayerName?",
  ui_story_5075_50751101_45_dialog_content = "Claro que sí. También obtuve un caramelo de flor de ciruelo y un poema de mi parte.",
  ui_story_5075_50751101_46_dialog_content = "Pero no hay necesidad de agradecerme.",
  ui_story_5075_50751101_47_dialog_content = "Eso es absurdo. ¿Por qué debería agradecerte?",
  ui_story_5075_50751101_48_dialog_content = "Pero si pudieras decirme dónde está PlayerName, te lo agradecería.",
  ui_story_5075_50751101_49_dialog_content = "Allá en la calle Yulin, aunque será mejor que te apures.",
  ui_story_5075_50751101_50_dialog_content = "O alguien te ganará.",
  ui_story_5075_50751101_51_dialog_content = "... Vamos, Jiu.",
  ui_story_5075_50751101_52_dialog_content = "Solo un minuto. Estoy emocionado por haber vendido todas las figuritas de azúcar hoy.",
  ui_story_5075_50751101_53_dialog_content = "Así que te daré una lectura gratis.",
  ui_story_5075_50751101_54_dialog_content = "Por lo que puedo decir, te dirigirás hacia el sureste para encontrarte con alguien importante.",
  ui_story_5075_50751101_55_dialog_content = "Ahí es donde está la calle Yulin. Tú mismo me dijiste la ubicación.",
  ui_story_5075_50751101_56_dialog_content = "¿Pero no puedes simplemente seguir la corriente y admitir que hacia allí es donde te diriges?",
  ui_story_5075_50751101_57_dialog_content = "No tengo tiempo para tus tonterías.",
  ui_story_5075_50751101_58_dialog_content = "Ese es el destino que he concluido de tu lectura.",
  ui_story_5075_50751101_59_dialog_content = "Princesa Dantang, consultamos a los espíritus y deidades en la mayoría de las adivinaciones.",
  ui_story_5075_50751101_60_dialog_content = "Pero la adivinación más precisa es consultarse a uno mismo.",
  ui_story_5075_50751101_61_dialog_content = "Tus pensamientos y tus acciones determinan tu destino.",
  ui_story_5075_50751101_62_dialog_content = "Vaya, lo siento por tomar más de tu tiempo. Ya terminé y no te retendré más.",
  ui_story_5075_50751101_63_dialog_content = "...",
  ui_story_5075_50751101_64_dialog_content = "Muchas gracias.",
  ui_story_5075_50751101_65_dialog_content = "No lo menciones, aunque agradecería futuros negocios.",
  ui_story_5075_50751101_66_dialog_content = "No te preocupes, no planeo hacerlo.",
  ui_story_5075_50751102_1_dialog_content = "Urgh...",
  ui_story_5075_50751102_2_dialog_content = "Esto... no parece la casa de huéspedes.",
  ui_story_5075_50751102_3_dialog_content = "Por todo lo que hablas de hospitalidad, esta es la primera vez que veo a alguien noquear y secuestrar a su invitado.",
  ui_story_5075_50751102_4_dialog_content = "Si tan solo hubieras cooperado, nunca tuve la intención de presentarme ante ti de esta manera.",
  ui_story_5075_50751102_5_dialog_content = "Después de todo, el papel de mayordomo de la Casa de Huéspedes Real es bastante conveniente, y no quería cambiarlo.",
  ui_story_5075_50751102_6_dialog_content = "No pensé que causarías tantos problemas, incluso lograste que los Lin te echaran una mano.",
  ui_story_5075_50751102_7_dialog_content = "En el peor de los casos, podrías resolver el desorden que hemos provocado intencionalmente.",
  ui_story_5075_50751102_8_dialog_content = "¿Así que ustedes están detrás de esto?",
  ui_story_5075_50751102_9_dialog_content = "Rompiendo el sello del dragón, propagando la niebla negra por toda la ciudad, enfrentando a las personas y a los demonios entre sí.",
  ui_story_5075_50751102_10_dialog_content = "¿Qué es exactamente lo que buscas?",
  ui_story_5075_50751102_11_dialog_content = "Eso no es algo por lo que deberías preocuparte.",
  ui_story_5075_50751102_12_dialog_content = "Solo toma un descanso en este escondite por ahora. Una vez que todo se calme, <color=#FFB400>nosotros</color> te dejaremos ir.",
  ui_story_5075_50751102_13_dialog_content = "Por <color=#FFB400>\"nosotros,\"</color> ¿te refieres a tus aliados dentro del gobierno del Reino Ji?",
  ui_story_5075_50751102_14_dialog_content = "El Asesor Principal te lo dijo, ¿no es así?",
  ui_story_5075_50751102_15_dialog_content = "Ese viejo entrometido interfirió con muchas de nuestras acciones incluso antes de darse cuenta de nuestra presencia.",
  ui_story_5075_50751102_16_dialog_content = "Pero él ya no estará por aquí mucho más tiempo.",
  ui_story_5075_50751102_17_dialog_content = "Y esto es todo gracias a ti.",
  ui_story_5075_50751102_18_dialog_content = "¿Yo?",
  ui_story_5075_50751102_19_dialog_content = "Escuché tu conversación con el Asesor Jefe y Su Alteza el día que llegaste al palacio.",
  ui_story_5075_50751102_20_dialog_content = "No te dejes engañar por las altas murallas del palacio. Dentro de allí, es el lugar con menos secretos en el mundo.",
  ui_story_5075_50751102_21_dialog_content = "Probablemente se dio cuenta de que nuestro agente se estaba infiltrando lentamente en el gobierno, pero no pudo determinar quién.",
  ui_story_5075_50751102_22_dialog_content = "Por eso quiere usar a alguien como tú, un forastero.",
  ui_story_5075_50751102_23_dialog_content = "Pero su movimiento me ha dado una apertura.",
  ui_story_5075_50751102_24_dialog_content = "Sé que el anciano te pasó el insignia de la Oficina de Inspección a través de esa caja de comida.",
  ui_story_5075_50751102_25_dialog_content = "Si efectivamente utilizaste la fuerza de la Oficina de Inspección para resolver el aprieto actual, su acción simplemente se consideraría conveniencia.",
  ui_story_5075_50751102_26_dialog_content = "Hay lugar para justificación incluso si alguien lo investiga.",
  ui_story_5075_50751102_27_dialog_content = "Pero si alguien descubre que la insignia está contigo antes de que puedas hacer algo con ella...",
  ui_story_5075_50751102_28_dialog_content = "Siendo el Asesor Jefe y entregando un artículo tan vital a un extranjero, especialmente alguien de otro continente...",
  ui_story_5075_50751102_29_dialog_content = "Alguien cuyos movimientos están envueltos en misterio en los tiempos más tumultuosos de Haojin.",
  ui_story_5075_50751102_30_dialog_content = "¿Quién podría creer que no estás conspirando, tramando contra el Reino Ji?",
  ui_story_5075_50751102_31_dialog_content = "Todos en el gobierno seguramente lo condenarán por traición.",
  ui_story_5075_50751102_32_dialog_content = "Déjame ver, ¿dónde escondiste la insignia? ¿En tu bolsillo? ¿Manga?",
  ui_story_5075_50751102_33_dialog_content = "Puedes dejar de buscar. Ya no lo tengo conmigo.",
  ui_story_5075_50751102_34_dialog_content = "Cuando el Asesor Jefe me pidió que operara en secreto, tuve la sensación de que era por la gente que me rodeaba.",
  ui_story_5075_50751102_35_dialog_content = "Después de recibir esa caja de comida, estaba aún más convencido de que alguien en la Casa de Huéspedes Real no podía ser de confianza.",
  ui_story_5075_50751102_36_dialog_content = "Si ese es el caso, entonces solo era cuestión de tiempo antes de que lo descubrieras.",
  ui_story_5075_50751102_37_dialog_content = "Por eso tuve que salir de allí lo más pronto posible.",
  ui_story_5075_50751102_38_dialog_content = "¿Cuál es el punto? Aún no has encontrado la oportunidad de movilizar la Oficina de Inspección.",
  ui_story_5075_50751102_39_dialog_content = "Además, como alguien de una tierra lejana, el número de personas que conoces en Longzhou es extremadamente limitado.",
  ui_story_5075_50751102_40_dialog_content = "Incluso si conoces a la Princesa Zhuohua, ella está en el palacio y he ordenado a espías que la monitoreen todo el tiempo, no te dejando ninguna oportunidad de comunicarte con ella.",
  ui_story_5075_50751102_41_dialog_content = "A quien le des la insignia puede ser revelado con una simple investigación.",
  ui_story_5075_50751102_42_dialog_content = "Oh, ya veo. Es la familia Lin, ¿verdad?",
  ui_story_5075_50751102_43_dialog_content = "El Lin Guildmaster asumiría cualquier riesgo siempre que sea rentable.",
  ui_story_5075_50751102_44_dialog_content = "Pero dar el mando de la Oficina de Inspección a un comerciante con un historial manchado... ¡Jajaja!",
  ui_story_5075_50751102_45_dialog_content = "Incluso en el Reino de Ji, donde se valoran el comercio y los comerciantes, la absurdidad de tu acción es sin precedentes, lo que facilita atribuirte un delito.",
  ui_story_5075_50751102_46_dialog_content = "Por un segundo, realmente pensé que tenías algunas cartas escondidas, pero resulta que eres simplemente un niño ingenuo.",
  ui_story_5075_50751102_47_dialog_content = "Necesito vigilar a mi tripulación. No tengo tiempo que perder contigo.",
  ui_story_5075_50751102_48_dialog_content = "¿Quién dijo que le di el emblema a la familia Lin?",
  ui_story_5075_50751102_49_dialog_content = "Si no son los Lin, probablemente sean esos dos con los que estuviste antes.",
  ui_story_5075_50751102_50_dialog_content = "Plebeyos o comerciantes, no hay mucha diferencia allí—",
  ui_story_5075_50751102_51_dialog_content = "No era un plebeyo.",
  ui_story_5075_50751102_52_dialog_content = "<size=45>Fue la <color=#FFB400>Princesa Zhuohua</color>.</size>",
  ui_story_5075_50751102_53_dialog_content = "¿No escuchaste? Dije que hay espías alrededor de la princesa, y ella no puede posiblemente...",
  ui_story_5075_50751102_54_dialog_content = "<size=45>Ella estará aquí pronto.</size>",
  ui_story_5075_50751102_55_dialog_content = "El emblema es un símbolo de la Oficina de Inspección, la dirección pertenece a la familia Lin, y la que me guió es su mentora.",
  ui_story_5075_50751102_56_dialog_content = "Y todas están unidas por las begonias.",
  ui_story_5075_50751102_57_dialog_content = "¡Dantang es el único que podría aprovechar al máximo ambos!",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751102_59_dialog_content = "No te muevas o perderás la cabeza.",
  ui_story_5075_50751102_60_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_5075_50751102_61_dialog_content = "Dantang! Jiu!",
  ui_story_5075_50751102_62_dialog_content = "¡Tú... Cómo hiciste... Ah!",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>Dantang de repente tira de la cara del mayordomo de la Casa Real de Huéspedes.</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>Una máscara, delgada como el ala de una cigarra, se desprende, revelando un extraño nuevo rostro debajo.</color>",
  ui_story_5075_50751102_65_dialog_content = "De hecho, no eres el verdadero administrador de la Casa de Huéspedes Real, sino un impostor.",
  ui_story_5075_50751102_66_dialog_content = "... ¿Y qué si me atrapas? No cambiará nada.",
  ui_story_5075_50751102_67_dialog_content = "La sabiduría de nuestro señor es inigualable. Nosotros, los <color=#FFB400>Jinetes del Destino</color>, estamos en todas partes.",
  ui_story_5075_50751102_68_dialog_content = "Nuestro plan está casi terminado. ¡El sello en el fondo del mar ha sido roto y la pesadilla dormida ya ha despertado!",
  ui_story_5075_50751102_69_dialog_content = "Cuando Haojin caiga en el caos, nos lanzaremos y tomaremos el Reino Ji sin sudar.",
  ui_story_5075_50751102_70_dialog_content = "A menos que tengas a un dios de tu lado, de lo contrario—¡urgh!",
  ui_story_5075_50751102_71_dialog_content = "¿Alguien pidió ayuda?",
  ui_story_5075_50751102_72_dialog_content = "¡Grr! Pff-urgh!",
  ui_story_5075_50751102_73_dialog_content = "¿Chen'ni? ¿Qué estás haciendo aquí?",
  ui_story_5075_50751102_74_dialog_content = "Estaba persiguiendo al culpable que rompió el sello, pero finalmente perdí al pillo.",
  ui_story_5075_50751102_75_dialog_content = "Así que decidí seguir el rastro, investigando todos los lugares a los que fue el tipo y todas las personas que tuvieron contacto con él.",
  ui_story_5075_50751102_76_dialog_content = "¡Incluyendo aquí!",
  ui_story_5075_50751102_77_dialog_content = "¡Grr! ¡Urgh!",
  ui_story_5075_50751102_78_dialog_content = "Y hasta conocí al vendedor de figuritas de azúcar.",
  ui_story_5075_50751102_79_dialog_content = "¿El vendedor de figuritas de azúcar que hizo caramelos de flor de ciruelo?",
  ui_story_5075_50751102_80_dialog_content = "¡Ese es! Es tan generoso y me ofreció un montón de figuritas.",
  ui_story_5075_50751102_81_dialog_content = "Solo quería una cosa, que yo plantara una ramita de flor de ciruelo en todos los lugares a los que voy.",
  ui_story_5075_50751102_82_dialog_content = "¿Entonces lo hiciste?",
  ui_story_5075_50751102_83_dialog_content = "Por supuesto. Tengo mis ofrendas, así que tengo que cumplir mis promesas.",
  ui_story_5075_50751102_84_dialog_content = "También planté uno fuera de esta casa.",
  ui_story_5075_50751102_85_dialog_content = "Gracias a Dios... Dantang!",
  ui_story_5075_50751102_86_dialog_content = "Estoy aquí.",
  ui_story_5075_50751102_87_dialog_content = "Obtuve el insignia del Lin Guildmaster y la asistencia del Guardia de la Familia.",
  ui_story_5075_50751102_88_dialog_content = "Los guardias están listos para la orden de Zhong Xu de suprimir a los Eclipsites y a los demonios frenéticos en la ciudad.",
  ui_story_5075_50751102_89_dialog_content = "Una vez que la Oficina de Inspección haya lidiado con los llamados Fate Riders, también se unirán a la refriega.",
  ui_story_5075_50751102_90_dialog_content = "Gracias... por recordar la flor que amo.",
  ui_story_5075_50751102_91_dialog_content = "¡Jaja, solo me alegro de que haya funcionado! ¿Cómo se ven las cosas afuera?",
  ui_story_5075_50751102_92_dialog_content = "Todavía nos mantenemos en la ciudad, pero depende de Yuebai para las afueras.",
  ui_story_5075_50751102_93_dialog_content = "Bien. En cuanto a las afueras de la ciudad, el administrador de la Casa de Huéspedes Real... Este hombre acaba de decir que su plan está cerca de completarse.",
  ui_story_5075_50751102_94_dialog_content = "Es posible que Yoh se haya fusionado completamente con la niebla negra en este momento.",
  ui_story_5075_50751102_95_dialog_content = "¡Necesitamos encontrarlo y poner fin a esto de inmediato!",
  ui_story_5075_50751102_96_dialog_content = "Entonces ven conmigo.",
  ui_story_5075_50751102_97_dialog_content = "He organizado un pequeño barco para llevarnos directamente a la bahía.",
  ui_story_5075_50751102_98_dialog_content = "Dantang tiene la ciudad. Iré con Yuebai a buscar a Yoh... ¿Eh?",
  ui_story_5075_50751102_99_dialog_content = "Eh... ¿Doncella Dragón?",
  ui_story_5075_50751102_100_dialog_content = "No entiendo muy bien esto, pero alguien castigó al tipo que rompió el sello por mí, ¿verdad?",
  ui_story_5075_50751102_101_dialog_content = "¡Te acompañaré a la orilla del mar!",
  ui_story_5075_50751102_102_dialog_content = "La ilusión creada por Yoh podría ser demasiado formidable para que los poderes de un Caelestite la conquisten solo.",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_2_dialog_content = "Mmm... Lo siento, debo haberme quedado dormido. ¿Ya llegamos, Yue...?",
  ui_story_5075_50751201_3_dialog_content = "¿Ah?",
  ui_story_5075_50751201_4_dialog_content = "¿De quién estaba intentando decir el nombre hace un momento?",
  ui_story_5075_50751201_5_dialog_content = "Más importante aún, ¿qué estoy haciendo en este barco?",
  ui_story_5075_50751201_6_dialog_content = "Urgh... Me duele la cabeza.",
  ui_story_5075_50751201_7_dialog_content = "Oye, ¿estás soñando despierto otra vez? ¡Muévete y sigue moviendo esa carga! Pronto zarpamos.",
  ui_story_5075_50751201_8_dialog_content = "¿C-Cargar el cargamento? ¿Yo?",
  ui_story_5075_50751201_9_dialog_content = "No hay nadie más aquí.",
  ui_story_5075_50751201_10_dialog_content = "¿No fuiste tú quien dijo que tu pariente, Soroz o quien sea, se enfermó, y necesitabas trabajar para recolectar dinero para medicinas rápidamente?",
  ui_story_5075_50751201_11_dialog_content = "Quién sabe si este viaje al extranjero del que hablan será de un regreso seguro.",
  ui_story_5075_50751201_12_dialog_content = "Es bueno que el Gremio Lin pueda ser pequeño, pero están dispuestos a pagar mucho por este viaje, incluso dando la mitad por adelantado.",
  ui_story_5075_50751201_13_dialog_content = "Con este dinero, finalmente puedo conseguir buena comida para mi esposa e hijos.",
  ui_story_5075_50751201_14_dialog_content = "Tu familia no tendrá que preocuparse por el dinero para medicinas por un tiempo, ¿verdad?",
  ui_story_5075_50751201_15_dialog_content = "(Algo no está bien en esto, pero lo que él está diciendo tiene sentido...)",
  ui_story_5075_50751201_16_dialog_content = "(Argh... Me duele la cabeza de nuevo.)",
  ui_story_5075_50751201_17_dialog_content = "(Mejor solo cargo esta carga.)",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_19_dialog_content = "¿Ah? ¿Qué está pasando?",
  ui_story_5075_50751201_20_dialog_content = "¿De dónde viene toda esta niebla?",
  ui_story_5075_50751201_21_dialog_content = "¿Has perdido la cabeza de hambre? Hemos estado atrapados en esta niebla durante casi dos semanas, solo dando vueltas en círculos.",
  ui_story_5075_50751201_22_dialog_content = "Parece que todos nosotros en este barco podríamos encontrar nuestro fin aquí.",
  ui_story_5075_50751201_23_dialog_content = "Tengo a mi esposa e hijos esperándome en casa, no puedo morir ahora...",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>Su suspiro provoca una ola de llantos dolorosos.</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>La tripulación y los comerciantes yacen dispersos por la cubierta, sus alientos teñidos de desesperación cansada.</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5075_50751201_27_dialog_content = "(¿Acaba de chocar algo contra el barco?)",
  ui_story_5075_50751201_28_dialog_content = "¡Rápido... Ven y mira!",
  ui_story_5075_50751201_29_dialog_content = "¡Esos peces, esos peces están empujando el barco desde abajo!",
  ui_story_5075_50751201_30_dialog_content = "¡Son peces serpiente! ¡Tenemos suerte! Es invierno, ¡y siempre vuelven a Longzhou en esta época del año!",
  ui_story_5075_50751201_31_dialog_content = "¡Síguelos, y podemos salir de aquí!",
  ui_story_5075_50751201_32_dialog_content = "¿Ves eso? ¡Es una bendición divina! ¡Los dioses deben habernos escuchado!",
  ui_story_5075_50751201_33_dialog_content = "(¿Estoy alucinando o algo así? Ese pez serpiente en el frente... ¿Por qué se ve tan familiar?)",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_35_dialog_content = "Soy... un pez serpiente.",
  ui_story_5075_50751201_36_dialog_content = "Cazo mi comida mientras viajo por los mares y, ocasionalmente, busco el consejo de otros usuarios de Luminatics.",
  ui_story_5075_50751201_37_dialog_content = "Cada invierno, regresamos a Longzhou, el lugar de nuestro nacimiento.",
  ui_story_5075_50751201_38_dialog_content = "Un día, descubrimos un barco perdido en el mar.",
  ui_story_5075_50751201_39_dialog_content = "Nos siguió de regreso a las costas de Longzhou, donde su líder hizo un pacto con el nuestro.",
  ui_story_5075_50751201_40_dialog_content = "Desde aquel invierno, hemos escoltado ese barco en nuestros viajes a Longzhou.",
  ui_story_5075_50751201_41_dialog_content = "Guiamos su curso y, a cambio, nos ofrecieron comida.",
  ui_story_5075_50751201_42_dialog_content = "Fue un intercambio agradable, uno que debería habernos hecho felices.",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_44_dialog_content = "Jefe, ¿jefe? ¿Pensando en el pez serpiente otra vez?",
  ui_story_5075_50751201_45_dialog_content = "Lo siento, pero por alguna razón, uno de esos peces serpiente se ve muy familiar.",
  ui_story_5075_50751201_46_dialog_content = "Todos se ven iguales. ¿Qué hay para ver? Aquí, mira esto.",
  ui_story_5075_50751201_47_dialog_content = "Aquí está tu corte del viaje al extranjero.",
  ui_story_5075_50751201_48_dialog_content = "¡Eso es demasiado!",
  ui_story_5075_50751201_49_dialog_content = "Desde que los Lin iniciaron la ruta oceánica, hemos estado ganando cada vez más. Esto es solo una nimiedad.",
  ui_story_5075_50751201_50_dialog_content = "¿Te interesa hacer algo más de dinero?",
  ui_story_5075_50751201_51_dialog_content = "¿P-Puedo hacer aún más?",
  ui_story_5075_50751201_52_dialog_content = "Hablé con los demás antes de venir aquí. El negocio del gremio Lin se está expandiendo.",
  ui_story_5075_50751201_53_dialog_content = "Cada vez hay más necesidad de comerciar con lugares como Astra. ¡Ni siquiera un viaje al año se acercará a satisfacer la demanda!",
  ui_story_5075_50751201_54_dialog_content = "¿Qué tal si nos unimos y hablamos con el Guildmaster sobre agregar otra carrera?",
  ui_story_5075_50751201_55_dialog_content = "Dos viajes al año, ¿qué te parece?",
  ui_story_5075_50751201_56_dialog_content = "Pero, ¿creo que el pez serpiente solo regresa a Longzhou en invierno?",
  ui_story_5075_50751201_57_dialog_content = "La mayoría del tiempo simplemente están vagando por el mar. Un viaje adicional de regreso a Longzhou no debería importar mucho.",
  ui_story_5075_50751201_58_dialog_content = "Con el dinero extra que ganamos, podemos comprar más comida para peces para ellos, ¿verdad?",
  ui_story_5075_50751201_59_dialog_content = "No creo que al pez serpiente realmente le importe eso.",
  ui_story_5075_50751201_60_dialog_content = "Tsk, parece imposible convencerte de esto. No importa entonces. Todos los demás están a bordo, así que tu decisión de no ir no es un gran problema.",
  ui_story_5075_50751201_61_dialog_content = "Espera, yo no—",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_63_dialog_content = "Después, nuestro líder nos dijo que también tendríamos que regresar a Longzhou en el verano.",
  ui_story_5075_50751201_64_dialog_content = "Las aguas de verano están calientes y desagradables.",
  ui_story_5075_50751201_65_dialog_content = "Pero nuestros amigos a bordo del barco necesitaban nuestra ayuda.",
  ui_story_5075_50751201_66_dialog_content = "Así que acordamos.",
  ui_story_5075_50751201_67_dialog_content = "Aunque el viaje fue largo y agotador, estuvimos de acuerdo.",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_69_dialog_content = "Hoy, he reunido a todos aquí para hacer un anuncio.",
  ui_story_5075_50751201_70_dialog_content = "Hemos asegurado un trato comercial con Yangjing, y para satisfacer la demanda, debemos hacer otro largo viaje este año.",
  ui_story_5075_50751201_71_dialog_content = "Pero espera, nuestro acuerdo con el pez serpiente solo cubre un solo viaje por año.",
  ui_story_5075_50751201_72_dialog_content = "Pedirles que nos guíen a Longzhou en verano ya es una violación del contrato, sin mencionar—",
  ui_story_5075_50751201_73_dialog_content = "Este es un trato de Yangjing, algo con lo que muchos gremios sueñan.",
  ui_story_5075_50751201_74_dialog_content = "¿Te das cuenta de cuánto beneficio traerá este trato a los Lin?",
  ui_story_5075_50751201_75_dialog_content = "Entiendo que esta decisión es injusta para el pez serpiente, y personalmente me disculparé con el demonio después.",
  ui_story_5075_50751201_76_dialog_content = "Ese es nuestro plan ahora.",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_78_dialog_content = "Ese año, regresamos a Longzhou tres veces.",
  ui_story_5075_50751201_79_dialog_content = "Nuestro líder dijo que eso era solo temporal y que nuestros amigos estaban en problemas.",
  ui_story_5075_50751201_80_dialog_content = "Pero el próximo año también hubo tres viajes. El año siguiente no fue diferente.",
  ui_story_5075_50751201_81_dialog_content = "Varios de los nuestros ya habían desaparecido.",
  ui_story_5075_50751201_82_dialog_content = "Después de eso, nuestro líder falleció inesperadamente.",
  ui_story_5075_50751201_83_dialog_content = "Y así, me convertí en el nuevo líder del pez serpiente.",
  ui_story_5075_50751201_84_dialog_content = "Nuestros amigos a bordo del barco aparecieron un día. Me llevaron a tierra y me colocaron en un tanque dentro de un edificio de madera.",
  ui_story_5075_50751201_85_dialog_content = "El tanque era tan pequeño y estrecho.",
  ui_story_5075_50751201_86_dialog_content = "Fue insoportable.",
  ui_story_5075_50751201_87_dialog_content = "El cuarto año vio otros tres viajes a Longzhou.",
  ui_story_5075_50751201_88_dialog_content = "Pero incluso durante nuestros viajes, se negaron a dejarme nadar en el océano.",
  ui_story_5075_50751201_89_dialog_content = "Llevaron mi tanque a bordo de su barco y me mantuvieron bien alimentado. Dijeron que mi única preocupación era instruir a los de mi especie desde allí.",
  ui_story_5075_50751201_90_dialog_content = "Lo llamaron \"adoración\", una forma de mostrar su respeto a los demonios.",
  ui_story_5075_50751201_91_dialog_content = "¿Ya eres capaz de cambiar tu forma, eh?",
  ui_story_5075_50751201_92_dialog_content = "...",
  ui_story_5075_50751201_93_dialog_content = "Pero aún no puedes hablar, ¿verdad?",
  ui_story_5075_50751201_94_dialog_content = "¿Te gustaría aprender? Puedo enseñarte. Considéralo una compensación...",
  ui_story_5075_50751201_95_dialog_content = "No importa, de todos modos no puedes entender lo que estoy diciendo.",
  ui_story_5075_50751201_96_dialog_content = "Además, los errores que te he hecho no son algo que se pueda arreglar con unos pocos actos pequeños.",
  ui_story_5075_50751201_97_dialog_content = "(Sabía que él era su líder.)",
  ui_story_5075_50751201_98_dialog_content = "(Él me enseñó a hablar y leer su idioma.)",
  ui_story_5075_50751201_99_dialog_content = "(Pero también sabía que él era un hombre malvado, muy malvado.)",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>Chapoteo</color>",
  ui_story_5075_50751201_101_dialog_content = "¿Cuatro viajes?",
  ui_story_5075_50751201_102_dialog_content = "La familia Qi ha estado codiciando el título de Comerciante Imperial, queriendo desafiar a nuestro gremio Lin.",
  ui_story_5075_50751201_103_dialog_content = "Sin más logros notables, podríamos estar fuera del juego.",
  ui_story_5075_50751201_104_dialog_content = "No podemos permitir que la gloria centenaria de la familia Lin se empañe bajo nuestra vigilancia.",
  ui_story_5075_50751201_105_dialog_content = "¡Durante los últimos años, los peces serpiente han estado muriendo en números cada vez mayores! ¡No finjas que no lo sabes!",
  ui_story_5075_50751201_106_dialog_content = "¿Y? ¿Y qué?",
  ui_story_5075_50751201_107_dialog_content = "¿Cómo que \"¿Y qué?\"? ¿Qué planeas hacer al respecto?",
  ui_story_5075_50751201_108_dialog_content = "Cuando necesitábamos enviar más mercancías, comenzamos a hacer dos viajes. Después de recibir una solicitud urgente, subió a tres.",
  ui_story_5075_50751201_109_dialog_content = "¡La familia Lin debe su inmenso éxito al pez serpiente!",
  ui_story_5075_50751201_110_dialog_content = "Nos salvaron de una muerte segura e incluso acordaron ayudarnos, ¿y así es como les recompensamos?",
  ui_story_5075_50751201_111_dialog_content = "¡Deja de intentar ocultar tu avaricia con excusas tan grandilocuentes!",
  ui_story_5075_50751201_112_dialog_content = "PlayerName...",
  ui_story_5075_50751201_113_dialog_content = "Urgh... ¿Quién fue eso de ahora?",
  ui_story_5075_50751201_114_dialog_content = "Tomas pago de nuestro gremio Lin pero pareces más devoto al pez serpiente, ¿eh?",
  ui_story_5075_50751201_115_dialog_content = "No tenemos uso para alguien como tú. Estás despedido.",
  ui_story_5075_50751201_116_dialog_content = "Tengo que asistir a una reunión sobre el cuarto viaje. Ve a saldar tu pago mensual con el administrador tú mismo.",
  ui_story_5075_50751201_117_dialog_content = "... ¿Seguro que quieres seguir adelante con esto?",
  ui_story_5075_50751201_118_dialog_content = "¿Qué quieres?",
  ui_story_5075_50751201_119_dialog_content = "Voy a devolver al líder del pez serpiente al mar.",
  ui_story_5075_50751201_120_dialog_content = "¡Ahí! ¡Encontré el tanque!",
  ui_story_5075_50751201_121_dialog_content = "Lo siento, pero para devolverte al océano, tendré que sacarte del agua por un tiempo.",
  ui_story_5075_50751201_122_dialog_content = "¡Detenlo!",
  ui_story_5075_50751201_123_dialog_content = "¿De dónde vinieron todas estas personas? Tengo que encontrar una manera de pasar por ellos...",
  ui_story_5075_50751201_124_dialog_content = "¡Potencia de fuerza!",
  ui_story_5075_50751201_125_dialog_content = "¡Urgh!",
  ui_story_5075_50751201_126_dialog_content = "... ¿Eh? ¿Qué es ese poder?",
  ui_story_5075_50751201_127_dialog_content = "¡PlayerName!",
  ui_story_5075_50751201_128_dialog_content = "... Chen'ni?",
  ui_story_5075_50751201_129_dialog_content = "Ya era hora de que me notaras.",
  ui_story_5075_50751201_130_dialog_content = "Tan pronto como nuestro barco entró en la bahía, tú y Yuebai se quedaron dormidos. No pude despertarte sin importar lo que intenté.",
  ui_story_5075_50751201_131_dialog_content = "Estaba tan aburrido y quería que ustedes dos se levantaran.",
  ui_story_5075_50751201_132_dialog_content = "¡Lo recuerdo ahora! En el momento en que navegamos hacia la bahía, una enorme ola de niebla negra vino directamente hacia nosotros!",
  ui_story_5075_50751201_133_dialog_content = "Ese poder debe ser lo que nos atrapó en este sueño... ¿O es algún tipo de ilusión?",
  ui_story_5075_50751201_134_dialog_content = "De cualquier manera.",
  ui_story_5075_50751201_135_dialog_content = "¡Estás demasiado tranquilo con esto!",
  ui_story_5075_50751201_136_dialog_content = "Eso no es lo que es importante.",
  ui_story_5075_50751201_137_dialog_content = "Sería mejor que fueras a revisar a Yuebai ahora.",
  ui_story_5075_50751201_138_dialog_content = "Parece que está sufriendo mucho.",
  ui_story_5075_50751201_139_dialog_content = "¿Es esta la corrupción de la niebla negra? Chen'ni, ¿no puedes...",
  ui_story_5075_50751201_140_dialog_content = "Puedo, pero no esta vez.",
  ui_story_5075_50751201_141_dialog_content = "Pero por qué-",
  ui_story_5075_50751201_142_dialog_content = "No es bueno confiar en las deidades para todo.",
  ui_story_5075_50751201_143_dialog_content = "Tienes que ocuparte de tus propios negocios.",
  ui_story_5075_50751201_144_dialog_content = "... Entiendo.",
  ui_story_5075_50751201_145_option_content = "¡Escaneo psíquico!",
  ui_story_5075_50751201_146_dialog_content = "¡Yuebai! ¿Dónde estás?",
  ui_story_5075_50751201_147_dialog_content = "PlayerName.",
  ui_story_5075_50751201_148_dialog_content = "Este pez serpiente... ¿Eres tú, Yuebai?",
  ui_story_5075_50751201_149_dialog_content = "¡Detente!",
  ui_story_5075_50751201_150_dialog_content = "¡Esto no otra vez!",
  ui_story_5075_50751201_151_dialog_content = "... ¡Vamos, tenemos que llegar a la playa!",
  ui_story_5075_50751201_152_dialog_content = "Uf... Nosotros... Lo logramos.",
  ui_story_5075_50751201_153_dialog_content = "¿Por qué tengo que agotarme incluso en un sueño?",
  ui_story_5075_50751201_154_dialog_content = "Por ahora, simplemente te meteremos en el agua, Yuebai. Después de eso, nosotros...",
  ui_story_5075_50751201_155_dialog_content = "¿Yuebai?",
  ui_story_5075_50751201_156_dialog_content = "(Perdí de vista a ella tan pronto como entró...)",
  ui_story_5075_50751201_157_dialog_content = "(¡El agua... Está llena de niebla negra!)",
  ui_story_5075_50751201_158_dialog_content = "...",
  ui_story_5075_50751201_159_dialog_content = "(Líder, estoy cansado. Líder, tengo hambre. Líder, me duele.)",
  ui_story_5075_50751201_160_dialog_content = "(Odio esto. Quiero volver. Líder, por favor sálvame.)",
  ui_story_5075_50751201_161_dialog_content = "(Nos salva. Líder... Sálvanos.)",
  ui_story_5075_50751201_162_dialog_content = "(Los demás me están llamando.)",
  ui_story_5075_50751201_163_dialog_content = "(Tan confuso. Tan caótico. Estas voces... Los corazones de los peces serpiente están clamando.)",
  ui_story_5075_50751201_164_dialog_content = "Esas. Voces.",
  ui_story_5075_50751201_165_dialog_content = "Ellos. Llaman. Fuera. Todos los días.",
  ui_story_5075_50751201_166_dialog_content = "Siempre. Siempre.",
  ui_story_5075_50751201_167_dialog_content = "Ellos. Odian.",
  ui_story_5075_50751201_168_dialog_content = "Yoh.",
  ui_story_5075_50751201_169_dialog_content = "Ya veo.",
  ui_story_5075_50751201_170_dialog_content = "Lo que experimenté justo ahora fueron tus propios recuerdos.",
  ui_story_5075_50751201_171_dialog_content = "Los. Lins.",
  ui_story_5075_50751201_172_dialog_content = "Traidores. Ellos.",
  ui_story_5075_50751201_173_dialog_content = "La. Gente. No. Se. Puede. Confiar.",
  ui_story_5075_50751201_174_dialog_content = "Tú. Eres. Pez. También.",
  ui_story_5075_50751201_175_dialog_content = "Debería. ¡Detestar!",
  ui_story_5075_50751201_176_dialog_content = "¡Yuebai! ¿Puedes oírme?",
  ui_story_5075_50751201_177_dialog_content = "¡Vengo a buscarte!",
  ui_story_5075_50751201_178_dialog_content = "No es necesario, PlayerName.",
  ui_story_5075_50751201_179_dialog_content = "¿Ah?",
  ui_story_5075_50751201_180_dialog_content = "La familia Lin hizo esto a Yoh.",
  ui_story_5075_50751201_181_dialog_content = "Y dado que hoy se me otorgó plena autoridad sobre la familia Lin, Yoh está completamente justificado en exigir su venganza sobre mí.",
  ui_story_5075_50751201_182_dialog_content = "...",
  ui_story_5075_50751201_183_dialog_content = "¿La niebla negra se está deteniendo?",
  ui_story_5075_50751201_184_dialog_content = "No... Esto no está bien...",
  ui_story_5075_50751201_185_dialog_content = "Yo... No...",
  ui_story_5075_50751201_186_dialog_content = "¿Qué le pasa a Yoh? Parece que tiene mucho dolor...",
  ui_story_5075_50751201_187_dialog_content = "Eso es porque esto no es lo que él realmente quiere.",
  ui_story_5075_50751201_188_dialog_content = "El Yoh que conozco se preocupa tanto por sus amigos como por los de su propia especie. No querría que su odio lastimara a ellos o a cualquier otro amigo.",
  ui_story_5075_50751201_189_dialog_content = "Además, no todos nosotros somos tan malvados como nuestros predecesores.",
  ui_story_5075_50751201_190_dialog_content = "Estoy seguro de que viste lo que PlayerName intentó hacer.",
  ui_story_5075_50751201_191_dialog_content = "Si él hubiera sido parte de la familia Lin en ese momento... Estoy seguro de que habría hecho exactamente lo mismo.",
  ui_story_5075_50751201_192_dialog_content = "...",
  ui_story_5075_50751201_193_dialog_content = "La familia Lin te ha mantenido atrapado durante demasiado tiempo.",
  ui_story_5075_50751201_194_dialog_content = "No permitiré que nadie más te mantenga encadenado por el odio.",
  ui_story_5075_50751201_195_dialog_content = "También puedo escuchar las voces de los peces serpiente.",
  ui_story_5075_50751201_196_dialog_content = "Por eso voy a salvarte.",
  ui_story_5075_50751201_197_dialog_content = "¡No!",
  ui_story_5075_50751201_198_dialog_content = "¡Yo. Odio!",
  ui_story_5075_50751201_199_dialog_content = "Tú. Eres. Demasiado.",
  ui_story_5075_50751201_200_dialog_content = "<size=45>¡Traidor!</size>",
  ui_story_5075_50751202_1_dialog_content = "¡Genial! Finalmente estás despierto. Sabes, los niños que duermen mucho limitan su propio crecimiento.",
  ui_story_5075_50751202_2_dialog_content = "¿En serio? Entonces, si empiezo a acostarme y despertarme más temprano... ¿Todavía puedo crecer un poco más?",
  ui_story_5075_50751202_3_dialog_content = "¡Puedes intentar rezar a mí!",
  ui_story_5075_50751202_4_dialog_content = "Y Yuebai también.",
  ui_story_5075_50751202_5_dialog_content = "Ya no soy un niño.",
  ui_story_5075_50751202_6_dialog_content = "Oh, eres uno comparado conmigo.",
  ui_story_5075_50751202_7_dialog_content = "Así que no frunzas el ceño todo el tiempo. Después de todo, Yoh simplemente no quería pelear contigo y se escapó.",
  ui_story_5075_50751202_8_dialog_content = "Mientras él siga allí, es pan comido sacarlo del mar.",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>De repente, Chen'ni levanta su mano y lanza un rayo de luz dorada al mar.</color>",
  ui_story_5075_50751202_10_dialog_content = "Probablemente no debería preguntar sobre lo que acabas de hacer, ¿verdad?",
  ui_story_5075_50751202_11_dialog_content = "Bueno, ya no me importa, así que podría romper el resto de los sellos.",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>La previamente tranquila superficie del mar de repente se agita violentamente, con olas gigantes elevándose.</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>Una figura se eleva desde el océano hasta el aire.</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>Innumerables remolinos desgarran la superficie del mar, de la cual emerge una inmensa niebla negra.</color>",
  ui_story_5075_50751202_16_dialog_content = "¿Es ese el Yoh al que has estado aludiendo? Es bastante joven.",
  ui_story_5075_50751202_17_dialog_content = "Yo. Conozco. Tú.",
  ui_story_5075_50751202_18_dialog_content = "Chen. Dragón.",
  ui_story_5075_50751202_19_dialog_content = "¿Me conoce por la ira que lo posee? Eso es mucho tiempo para guardar rencor.",
  ui_story_5075_50751202_20_dialog_content = "Yo. Quiero. Venganza.",
  ui_story_5075_50751202_21_dialog_content = "No. Tú. Interfieras.",
  ui_story_5075_50751202_22_dialog_content = "O. Si no.",
  ui_story_5075_50751202_23_dialog_content = "Inundación. Ciudad.",
  ui_story_5075_50751202_24_dialog_content = "Ay, no me digas que eres...",
  ui_story_5075_50751202_25_dialog_content = "(Esta es la primera vez que veo a Chen'ni tan seria.)",
  ui_story_5075_50751202_26_dialog_content = "(¿Realmente no puede hacer nada por Yoh?)",
  ui_story_5075_50751202_27_dialog_content = "Entonces, ¿quiere decir que si Chen'ni interviene, inundará todo Haojin?",
  ui_story_5075_50751202_28_dialog_content = "Él está tomando a toda la ciudad como rehén.",
  ui_story_5075_50751202_29_dialog_content = "Entonces estás...",
  ui_story_5075_50751202_30_dialog_content = "¿Amenazándome?",
  ui_story_5075_50751202_31_dialog_content = "¿Ah?",
  ui_story_5075_50751202_32_dialog_content = "¡Esto es genial! ¡Nadie me ha amenazado durante unos siglos!",
  ui_story_5075_50751202_33_dialog_content = "Pero pensándolo bien, realmente no tengo nada que ver con esto.",
  ui_story_5075_50751202_34_dialog_content = "Los eventos parecen complicados y no los entiendo del todo.",
  ui_story_5075_50751202_35_dialog_content = "Pero ustedes mortales rompieron el sello, y la animosidad de Yoh también es un problema entre mortales y diabólicos.",
  ui_story_5075_50751202_36_dialog_content = "Entonces, debería ser manejado entre mortales y diabólicos.",
  ui_story_5075_50751202_37_dialog_content = "¡Sí, tengo mucho sentido!",
  ui_story_5075_50751202_38_dialog_content = "¡Definitivamente este no es el momento para que tú seas \"lógico\"!",
  ui_story_5075_50751202_39_dialog_content = "Sin embargo, por muy ordenado que sea, no me gusta que me amenacen.",
  ui_story_5075_50751202_40_dialog_content = "Entonces-",
  ui_story_5075_50751202_41_dialog_content = "(¡Chen'ni acaba de despegar y voló hasta Yoh!)",
  ui_story_5075_50751202_42_dialog_content = "¡Golpe, golpe!",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>Chen'ni levanta su puño, golpeando ligeramente la cabeza de Yoh.</color>",
  ui_story_5075_50751202_44_dialog_content = "Estoy haciendo un movimiento. ¿Qué vas a hacer al respecto?",
  ui_story_5075_50751202_45_dialog_content = "¿Chen'ni?",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>Como si quisiera expresar la ira de Yoh, la superficie del mar estalla.</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>Capas sucesivas de olas masivas se elevan. En lugar de disminuir, siguen creciendo aún más en medio del tumulto resonante del mar.</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>La playa donde estamos parados se inunda rápidamente.</color>",
  ui_story_5075_50751202_50_dialog_content = "¡A este ritmo, todos vamos a ahogarnos!",
  ui_story_5075_50751202_51_dialog_content = "No te preocupes, soy bastante ágil en el agua. Te salvaré si empiezas a ahogarte.",
  ui_story_5075_50751202_52_dialog_content = "¡Preferiría no empezar ese proceso en primer lugar!",
  ui_story_5075_50751202_53_dialog_content = "Ups, casi me olvido de ustedes dos.",
  ui_story_5075_50751202_54_dialog_content = "(¿Estamos volando?)",
  ui_story_5075_50751202_55_dialog_content = "Mi poder sobrenatural es útil, ¿no es así?",
  ui_story_5075_50751202_56_dialog_content = "¿Qué pasa con Yoh?",
  ui_story_5075_50751202_57_dialog_content = "¿No dijo algo sobre <color=#FFB400>inundar la ciudad</color>? Ahora mismo está en camino a Haojin.",
  ui_story_5075_50751202_58_dialog_content = "¿N-No es eso un giro de eventos aún peor?",
  ui_story_5075_50751202_59_dialog_content = "¿Por qué tuviste que provocarlo de esa manera?",
  ui_story_5075_50751202_60_dialog_content = "No seas un manojo de nervios, PlayerName.",
  ui_story_5075_50751202_61_dialog_content = "He vivido mucho tiempo y también he estado observando las criaturas en Longzhou durante mucho tiempo.",
  ui_story_5075_50751202_62_dialog_content = "Ya sea Yoh o tú.",
  ui_story_5075_50751202_63_dialog_content = "Tampoco deberías subestimarlos.",
  ui_story_5075_50751301_1_dialog_content = "La voluntad del cielo—",
  ui_story_5075_50751301_2_dialog_content = "¡Rugido!",
  ui_story_5075_50751301_3_dialog_content = "Ugh, derriba uno y otro se levanta.",
  ui_story_5075_50751301_4_dialog_content = "La niebla negra en la ciudad se está volviendo aún más espesa. Comienzo a extrañar el tiempo cuando no podía verla.",
  ui_story_5075_50751301_5_dialog_content = "Incluso la cuerda no es suficiente para atar a estos demonios frenéticos. Si tan solo tuviera una forma de expulsar el rencor de sus cuerpos...",
  ui_story_5075_50751301_6_dialog_content = "¡Abran paso! ¡Tengo la cura!",
  ui_story_5075_50751301_7_dialog_content = "¿T-Tú estás dando medicina a los demonios?",
  ui_story_5075_50751301_8_dialog_content = "¿No es obvio?",
  ui_story_5075_50751301_9_dialog_content = "Pero su pérdida de control no está siendo causada por una enfermedad, sino por la corrupción nacida del rencor—",
  ui_story_5075_50751301_10_dialog_content = "Entonces para ti, ¿los médicos solo pueden tratar enfermedades?",
  ui_story_5075_50751301_11_dialog_content = "Dado que esa energía tiene que entrar en un fiendling para surtir efecto, se puede equiparar a una toxina.",
  ui_story_5075_50751301_12_dialog_content = "Y hay una cura para cada toxina.",
  ui_story_5075_50751301_13_dialog_content = "La oscura niebla ha invadido la ciudad. Incluso Tinytail... mi hermano está afectado.",
  ui_story_5075_50751301_14_dialog_content = "Pero obtuve una poción para equilibrar la Lumina interna de mi maestro para él. Mejoró mucho después de tomarla.",
  ui_story_5075_50751301_15_dialog_content = "Por eso corro afuera e intento ayudar.",
  ui_story_5075_50751301_16_dialog_content = "¡Ja!",
  ui_story_5075_50751301_17_dialog_content = "Tu hermano... ¿Es así? Entonces eso debe significar que tú también eres un <color=#FFB400>diablillo</color>.",
  ui_story_5075_50751301_18_dialog_content = "¿Qué, tienes algo en contra de los diablillos?",
  ui_story_5075_50751301_19_dialog_content = "¡Para nada! Solo estaba pensando que eres un médico bastante increíble.",
  ui_story_5075_50751301_20_dialog_content = "¿De verdad lo crees? Bueno, al menos reconoces el talento cuando lo ves.",
  ui_story_5075_50751301_21_dialog_content = "Pero en realidad no soy tan especial...",
  ui_story_5075_50751301_22_dialog_content = "Tengo la cura conmigo, pero los diablillos están descontrolados, y es difícil para mí administrársela.",
  ui_story_5075_50751301_23_dialog_content = "¡Déjame eso a mí!",
  ui_story_5075_50751301_24_dialog_content = "¡Noquearé a cada demonio que vea y te los llevaré para que los trates!",
  ui_story_5075_50751301_25_dialog_content = "¡Tranquilo, no tan alto!",
  ui_story_5075_50751301_26_dialog_content = "Nos escapamos solos. Tendremos un gran problema si nos atrapan.",
  ui_story_5075_50751301_27_dialog_content = "¡Oh, lo entiendo! Yo también solía hacer cosas así cuando era niño.",
  ui_story_5075_50751301_28_dialog_content = "No te preocupes, estaré atento y me aseguraré de que nadie te vea.",
  ui_story_5075_50751301_29_dialog_content = "Mi nombre es Luo Song, y este es mi compañero, Ah Ding.",
  ui_story_5075_50751301_30_dialog_content = "¡Rugido!",
  ui_story_5075_50751301_31_dialog_content = "Soy Liqing, y este es Tinytail, mi hermano mayor.",
  ui_story_5075_50751301_32_dialog_content = "¡Ja!",
  ui_story_5075_50751301_33_dialog_content = "¡Un placer trabajar contigo!",
  ui_story_5075_50751301_34_dialog_content = "¡Ha-auuu!",
  ui_story_5075_50751301_35_dialog_content = "¡Chirrido!",
  ui_story_5075_50751301_36_dialog_content = "Solo espera aquí por mí, Dr. Liqing. ¡Voy a explorar adelante!",
  ui_story_5075_50751301_37_dialog_content = "¡Hey, espera!",
  ui_story_5075_50751301_38_dialog_content = "¿No tienes paciencia?",
  ui_story_5075_50751301_39_dialog_content = "Ayuda... ¡Necesito ayuda!",
  ui_story_5075_50751301_40_dialog_content = "¡Quédate atrás! ¡El palo en mi mano no es para mostrar!",
  ui_story_5075_50751301_41_dialog_content = "¡Chirrido!",
  ui_story_5075_50751301_42_dialog_content = "¡Monstruos, no crean que somos fáciles de intimidar! ¡Ja-ah!",
  ui_story_5075_50751301_43_dialog_content = "¡Alto, todos! Urgh—",
  ui_story_5075_50751301_44_dialog_content = "¡Luo Song!",
  ui_story_5075_50751301_45_dialog_content = "¿Qué estás haciendo? ¿Quién te dijo que te lanzaras al medio de ellos?",
  ui_story_5075_50751301_46_dialog_content = "Genial, ahora recibiste un golpe en el hombro y un puñetazo en el vientre.",
  ui_story_5075_50751301_47_dialog_content = "Jaja, esto es una emergencia, ¿no es así?",
  ui_story_5075_50751301_48_dialog_content = "Estoy bien, así que solo dale a este pequeño demonio su medicina mientras lo sostengo.",
  ui_story_5075_50751301_49_dialog_content = "... No puedo decidir si eres cuidadoso o descuidado.",
  ui_story_5075_50751301_50_dialog_content = "Yo, quiero decir, lo siento... por golpearte...",
  ui_story_5075_50751301_51_dialog_content = "No te preocupes por eso. Fui yo quien saltó entre todos ustedes de repente.",
  ui_story_5075_50751301_52_dialog_content = "Pero, pero eso es un diablillo! ¿Por qué lo estabas defendiendo?",
  ui_story_5075_50751301_53_dialog_content = "¡En realidad, él te estaba defendiendo!",
  ui_story_5075_50751301_54_dialog_content = "Oh...",
  ui_story_5075_50751301_55_dialog_content = "Es normal que alguien se defienda si un fiendling los ataca. Pero debes saber que los fiendlings no tienen la intención de atacar a las personas.",
  ui_story_5075_50751301_56_dialog_content = "Todos son víctimas inocentes, igual que tú.",
  ui_story_5075_50751301_57_dialog_content = "Y como nadie tiene la culpa aquí, no se debería permitir que nadie salga lastimado.",
  ui_story_5075_50751301_58_dialog_content = "¿No es así como deberían ser las cosas?",
  ui_story_5075_50751301_59_dialog_content = "Muy bien, este fiendling está mucho mejor después de la cura.",
  ui_story_5075_50751301_60_dialog_content = "Debemos haber cubierto la mayoría de Haojin y curado a la mayoría de los fiendlings hasta ahora.",
  ui_story_5075_50751301_61_dialog_content = "Grr.",
  ui_story_5075_50751301_62_dialog_content = "¿Ves eso? Están siendo manipulados para atacar a las personas, y son perfectamente dóciles una vez que vuelven a la normalidad.",
  ui_story_5075_50751301_63_dialog_content = "... Si esto es de otra persona, no lo compraré.",
  ui_story_5075_50751301_64_dialog_content = "Pero ya que viene de ti, creo que es verdad.",
  ui_story_5075_50751301_65_dialog_content = "¡Gracias por salvar mi vida! Correré la voz y les diré que busquen tu ayuda si un demonio lastima a alguien.",
  ui_story_5075_50751301_66_dialog_content = "¿En serio? ¡Eso sería muy apreciado, gracias!",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751301_68_dialog_content = "¿Qué está pasando? ¿Por qué el cielo se oscurece tan de repente?",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>Golpeteo de pitter.</color>",
  ui_story_5075_50751301_70_dialog_content = "¿Esta lloviendo?",
  ui_story_5075_50751301_71_dialog_content = "Espera, esto no es lluvia.",
  ui_story_5075_50751301_72_dialog_content = "<size=45>La noche tampoco está cayendo. Una enorme ola de marea está cubriendo el cielo.</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>¿Se está inundando Haojin?</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>Las calles están llenas de gente huyendo en pánico.</color>",
  ui_story_5075_50751302_2_dialog_content = "¡Espíritus malvados! ¡Los espíritus malvados están trayendo una inundación para ahogarnos a todos!",
  ui_story_5075_50751302_3_dialog_content = "CORRER-",
  ui_story_5075_50751302_4_dialog_content = "Doncella Dragón, por favor protégenos. Doncella Dragón, por favor ayúdanos...",
  ui_story_5075_50751302_5_dialog_content = "Este ya no es un problema que podamos resolver por nuestra cuenta.",
  ui_story_5075_50751302_6_dialog_content = "¡Bájanos, Chen'ni! ¡Al menos déjanos ayudar a esas personas a llegar a un lugar seguro!",
  ui_story_5075_50751302_7_dialog_content = "Dama Chen'ni.",
  ui_story_5075_50751302_8_dialog_content = "No creo que sea necesario.",
  ui_story_5075_50751302_9_dialog_content = "Pero-",
  ui_story_5075_50751302_10_dialog_content = "Escucha con atención, PlayerName.",
  ui_story_5075_50751302_11_dialog_content = "¡Ay! Tropecé con un ladrillo... Duele mucho.",
  ui_story_5075_50751302_12_dialog_content = "¿Qué lugar es este... Dónde están Mamá y Papá?",
  ui_story_5075_50751302_13_dialog_content = "*llora*",
  ui_story_5075_50751302_14_dialog_content = "Graah!",
  ui_story_5075_50751302_15_dialog_content = "¡Ayuda! ¡Alguien me salve!",
  ui_story_5075_50751302_16_dialog_content = "¡Chirrido!",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>Justo antes de que el golpe del Eclipsite aterrice, el demonio se apresura y lo aparta.</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>El ataque se desvía ligeramente y falla.</color>",
  ui_story_5075_50751302_19_dialog_content = "Espera, eres...",
  ui_story_5075_50751302_20_dialog_content = "Este no es lo suficientemente fuerte. ¡Consigue otro!",
  ui_story_5075_50751302_21_dialog_content = "¡Los petardos estallan, ahuyentando a los demonios, desterrando la mala suerte de una manera alegre!",
  ui_story_5075_50751302_22_dialog_content = "Chirrido...",
  ui_story_5075_50751302_23_dialog_content = "Eres de aquel entonces...",
  ui_story_5075_50751302_24_dialog_content = "Graah!",
  ui_story_5075_50751302_25_dialog_content = "¡Cuidado!",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>El chico se lanza hacia adelante, recoge al pequeño demonio y rueda sobre el suelo cubierto de barro.</color>",
  ui_story_5075_50751302_27_dialog_content = "¡Ah Ding! ¡Golpea ahora!",
  ui_story_5075_50751302_28_dialog_content = "Grr...",
  ui_story_5075_50751302_29_dialog_content = "¿Eh? ¿No eres ese niño de antes?",
  ui_story_5075_50751302_30_dialog_content = "Agua... ¡Está cayendo a raudales!",
  ui_story_5075_50751302_31_dialog_content = "¡Chirrido!",
  ui_story_5075_50751302_32_dialog_content = "¡Espera, no me dejes atrás!",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>Es como si el cielo se estuviera derrumbando.</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>Con un ruido atronador, finalmente las olas masivas están rompiendo desde arriba.</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>Ante el poder abrumador, la pequeña ciudad construida por los Aurorianos en el suelo es completamente impotente.</color>",
  ui_story_5075_50751302_36_dialog_content = "¡Ahhhhhhhh!",
  ui_story_5075_50751302_37_dialog_content = "...",
  ui_story_5075_50751302_38_dialog_content = "Yo, ¿no estoy muerto? ¿Qué pasó?",
  ui_story_5075_50751302_39_dialog_content = "... Mira allá arriba.",
  ui_story_5075_50751302_40_dialog_content = "¡Chirrido!",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>El pequeño diabólico flota en el aire, creando una barrera invisible arriba.</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>Está conteniendo la ola justo en frente.</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>Bajo la presión, el demonio tiembla, pero aún levanta sus pequeñas garras, sosteniendo esa barrera protectora.</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>Entonces, otra barrera aparece no muy lejos.</color>",
  ui_story_5075_50751302_45_dialog_content = "¡Rugido!",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>Y luego, otro más.</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>Las barreras creadas por los demonios se entrelazan para cubrir una vasta extensión.</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>Las olas, tan pesadas como mil toneladas, presionan sobre la ciudad de Haojin, pero no pueden avanzar ni una pulgada.</color>",
  ui_story_5075_50751302_49_dialog_content = "Eso es...",
  ui_story_5075_50751302_50_dialog_content = "Esta tierra nunca ha pertenecido solo a los Aurorianos.",
  ui_story_5075_50751302_51_dialog_content = "Los diabólicos también tienen que proteger su hogar.",
  ui_story_5075_50751302_52_dialog_content = "Incluso si ese viejo Lin no lo hubiera buscado, Yoh habría revisado el sello por sus amigos.",
  ui_story_5075_50751302_53_dialog_content = "La mayoría de los aurorianos no quieren admitirlo, pero los diabólicos también tienen derecho a la tierra.",
  ui_story_5075_50751302_54_dialog_content = "¿Estás escuchando, PlayerName?",
  ui_story_5075_50751302_55_dialog_content = "Sí, escuché eso.",
  ui_story_5075_50751302_56_dialog_content = "Y creo que todos deberían escuchar eso también.",
  ui_story_5075_50751302_57_dialog_content = "Bueno, ciertamente puedo ayudar a difundir la palabra.",
  ui_story_5075_50751302_58_dialog_content = "¡Hagámoslo!",
  ui_story_5075_50751302_59_option_content = "¡Escaneo psíquico!",
  ui_story_5075_50751302_60_dialog_content = "Esos de dos patas, son malos, siempre nos patean cuando nos ven.",
  ui_story_5075_50751302_61_dialog_content = "Pero esos bípedos también son buenos, porque pueden atrapar presas deliciosas.",
  ui_story_5075_50751302_62_dialog_content = "A veces comparten su comida con nosotros.",
  ui_story_5075_50751302_63_dialog_content = "Espera, ¿qué es esto?",
  ui_story_5075_50751302_64_dialog_content = "¿Es esta la voz... de los fiendlings?",
  ui_story_5075_50751302_65_dialog_content = "Explotado por cosas calientes, aterrador.",
  ui_story_5075_50751302_66_dialog_content = "Ser expulsado, da miedo.",
  ui_story_5075_50751302_67_dialog_content = "Este lugar también es nuestro hogar.",
  ui_story_5075_50751302_68_dialog_content = "¡Pero nosotros también tenemos miedo! Siempre robas cosas y arruinas nuestra comida.",
  ui_story_5075_50751302_69_dialog_content = "¡Y tú incluso usas magia que nosotros no podemos! N-No sabemos cómo lidiar contigo!",
  ui_story_5075_50751302_70_dialog_content = "Esos de dos patas, tontos. Dejan cosas en la esquina, no pueden encontrarlas y nos culpan a nosotros.",
  ui_story_5075_50751302_71_dialog_content = "Esos de dos patas, tan tontos. Dejan comida en el patio pero no dejan un cartel, y termina siendo comida por otros.",
  ui_story_5075_50751302_72_dialog_content = "Pero aquellos con dos piernas también son inteligentes. La última vez que me lastimé la pierna, usaron una tabla para soportarla, y mejoró.",
  ui_story_5075_50751302_73_dialog_content = "¿Estamos siendo demasiado crueles con ellos...?",
  ui_story_5075_50751302_74_dialog_content = "Sí, se llaman fiendlings, pero en realidad, son solo bichos salvajes que recientemente han comenzado a entender las cosas.",
  ui_story_5075_50751302_75_dialog_content = "Son tanto tontos como inteligentes. Son malos, pero amables. Nos golpean y piden disculpas. Esos bípedos son realmente extraños.",
  ui_story_5075_50751302_76_dialog_content = "Pero no hay nada que podamos hacer.",
  ui_story_5075_50751302_77_dialog_content = "Nada que podamos hacer.",
  ui_story_5075_50751302_78_dialog_content = "Compartimos una casa, después de todo.",
  ui_story_5075_50751302_79_dialog_content = "El agua viene, y no pueden escapar.",
  ui_story_5075_50751302_80_dialog_content = "El agua viene, y la casa tampoco puede escapar.",
  ui_story_5075_50751302_81_dialog_content = "El agua es mala. Vete—",
  ui_story_5075_50751302_82_dialog_content = "Aléjate de—",
  ui_story_5075_50751302_83_dialog_content = "<size=45>¡Nuestro HOGAR!</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>En la barrera que envuelve a toda la ciudad, un repentino resplandor dorado gira, y las olas que no podían caer son dispersadas por la fuerza explosiva.</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>Se convierten en una lluvia amarga, lloviznando silenciosamente sobre Haojin.</color>",
  ui_story_5075_50751302_86_dialog_content = "La lluvia de hace un momento... ¿Lo hiciste tú, Chen'ni?",
  ui_story_5075_50751302_87_dialog_content = "¿Qué?",
  ui_story_5075_50751302_88_dialog_content = "Eh... No importa.",
  ui_story_5075_50751302_89_dialog_content = "Esos pequeños fiendlings son realmente impresionantes.",
  ui_story_5075_50751302_90_dialog_content = "Ahora todo lo que queda es lidiar con Yoh.",
  ui_story_5075_50751302_91_dialog_content = "...",
  ui_story_5075_50751302_92_dialog_content = "¿También los escuchaste, verdad? Los corazones de todas esas personas y demonios?",
  ui_story_5075_50751302_93_dialog_content = "Pueden cometer errores y pelear de vez en cuando, o incluso lastimarse por todo tipo de razones.",
  ui_story_5075_50751302_94_dialog_content = "Pero también trabajan juntos y se ayudan mutuamente, para poder coexistir en el mundo.",
  ui_story_5075_50751302_95_dialog_content = "Todos ellos son criaturas vivientes nacidas en Longzhou. No tienen ninguna razón para odiarse entre sí, natural o de otro tipo.",
  ui_story_5075_50751302_96_dialog_content = "Por lo cual, al menos, ninguno de ellos debería tener que morir para que el otro viva.",
  ui_story_5075_50751302_97_dialog_content = "Además...",
  ui_story_5075_50751302_98_dialog_content = "Entre todas esas voces de hace un momento, escuché una disculpa destinada solo para ti.",
  ui_story_5075_50751302_99_dialog_content = "Yoh.",
  ui_story_5075_50751302_100_dialog_content = "Lo siento.",
  ui_story_5075_50751401_1_dialog_content = "Disculparse.",
  ui_story_5075_50751401_2_dialog_content = "Por qué.",
  ui_story_5075_50751401_3_dialog_content = "¡Por supuesto que es!",
  ui_story_5075_50751401_4_dialog_content = "No. Remordimiento.",
  ui_story_5075_50751401_5_dialog_content = "No... ¡Urgh!",
  ui_story_5075_50751401_6_dialog_content = "¡Está volando de regreso a la bahía! ¡Después de él!",
  ui_story_5075_50751401_7_dialog_content = "Yoh!",
  ui_story_5075_50751401_8_dialog_content = "Sacudido por una o dos palabras... ¡Qué cobarde!",
  ui_story_5075_50751401_9_dialog_content = "No... ¡Urgh!",
  ui_story_5075_50751401_10_dialog_content = "¡Si este es el nivel de odio del que eres capaz, podrías darme tu cuerpo!",
  ui_story_5075_50751401_11_dialog_content = "Yoh... ¡Está resistiendo el control de la niebla negra!",
  ui_story_5075_50751401_12_dialog_content = "(¡Eso significa que podríamos tener una oportunidad ahora mismo!)",
  ui_story_5075_50751401_13_dialog_content = "Humph. El cuerpo es decente, pero demasiado débil en voluntad.",
  ui_story_5075_50751401_14_dialog_content = "Qué vergüenza es para un demonio ser manipulado con facilidad por los Aurorianos.",
  ui_story_5075_50751401_15_dialog_content = "Ha sido un largo tiempo, Chen'ni.",
  ui_story_5075_50751401_16_dialog_content = "No realmente. Solo han sido dos siestas.",
  ui_story_5075_50751401_17_dialog_content = "Sigues siendo tu antiguo yo.",
  ui_story_5075_50751401_18_dialog_content = "Es bastante difícil para nosotros cambiar, incluso si queremos.",
  ui_story_5075_50751401_19_dialog_content = "Por otro lado, el mundo mortal cambió mucho, lo cual definitivamente te perdiste al permanecer en el mar todo este tiempo.",
  ui_story_5075_50751401_20_dialog_content = "Tienen pájaros mecánicos de seguimiento automático, vibrantes pinturas occidentales y barcos que pueden cruzar el océano.",
  ui_story_5075_50751401_21_dialog_content = "Humph. No importa cuán bien creen, siguen siendo nada más que criaturas inferiores.",
  ui_story_5075_50751401_22_dialog_content = "¿Juzgas eso por la duración de la vida?",
  ui_story_5075_50751401_23_dialog_content = "¿No crees que eso es raro?",
  ui_story_5075_50751401_24_dialog_content = "Los Aurorianos tienen una vida corta, pero son ellos quienes ahora dominan el continente.",
  ui_story_5075_50751401_25_dialog_content = "Por el contrario, una forma de vida superior como nosotros, según tú, rara vez se ve.",
  ui_story_5075_50751401_26_dialog_content = "¿Debes degradarte de esta manera?",
  ui_story_5075_50751401_27_dialog_content = "Nosotros, los nobles diablillos, compartimos la misma línea de sangre que los <color=#FFB400>Primordiales</color>.. ¡Los humildes aurorianos no merecen ser mencionados en la misma frase que nosotros!",
  ui_story_5075_50751401_28_dialog_content = "¡Pero ahora, incluso un Auroriano sin poder podría burlarse y jugar con los diablillos!",
  ui_story_5075_50751401_29_dialog_content = "¿Vas a ignorar la gravedad de esta situación?",
  ui_story_5075_50751401_30_dialog_content = "El poder y la línea de sangre de los diabólicos reinan supremos sobre los de los aurorianos.",
  ui_story_5075_50751401_31_dialog_content = "¿Por qué deberíamos rebajarnos y compartir Longzhou con ellos?",
  ui_story_5075_50751401_32_option_content = "¡Potencia de fuerza!",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_34_dialog_content = "¡Potencia de fuerza!",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5075_50751401_36_dialog_content = "(No sirve de nada, apenas puedo sentir la presencia del verdadero Yoh. No hay forma de llegar a él en este momento.)",
  ui_story_5075_50751401_37_dialog_content = "PlayerName, ¿puedes enviar mis pensamientos a la mente de Yoh?",
  ui_story_5075_50751401_38_dialog_content = "Haré lo mejor que pueda, pero no estoy seguro de que pueda oírnos en su estado.",
  ui_story_5075_50751401_39_dialog_content = "Está bien.",
  ui_story_5075_50751401_40_dialog_content = "Como habitantes de las vastas profundidades del océano, el pez serpiente nunca se ahogaría tan fácilmente.",
  ui_story_5075_50751401_41_dialog_content = "Está bien entonces, prepárate.",
  ui_story_5075_50751401_42_option_content = "¡Potencia de fuerza!",
  ui_story_5075_50751401_43_dialog_content = "Yoh, ¿puedes escucharme?",
  ui_story_5075_50751401_44_dialog_content = "...",
  ui_story_5075_50751401_45_dialog_content = "Antes de irme, el Guildmaster me dijo que nunca se había disculpado contigo en persona.",
  ui_story_5075_50751401_46_dialog_content = "Dijo que al hacerlo, te estaría obligando a tolerar su despreciable comportamiento por la bondad de tu corazón.",
  ui_story_5075_50751401_47_dialog_content = "Dado que lo hizo deliberadamente y aceptó los beneficios que vinieron con el crimen, no tiene derecho a pedir perdón.",
  ui_story_5075_50751401_48_dialog_content = "Eso también es cierto para los Lin.",
  ui_story_5075_50751401_49_dialog_content = "Si crees que también soy un traidor contra mi ascendencia de pez serpiente, entonces naturalmente eso también me incluye a mí.",
  ui_story_5075_50751401_50_dialog_content = "Ejerce tu venganza como creas conveniente, y la aceptaremos.",
  ui_story_5075_50751401_51_dialog_content = "Pero debe ser de ti y solo de ti, sin la manipulación de nadie, en persona.",
  ui_story_5075_50751401_52_dialog_content = "¿O es tan insignificante el rencor que guarda el pez serpiente que lo confiarías a alguien más?",
  ui_story_5075_50751401_53_dialog_content = "No.",
  ui_story_5075_50751401_54_dialog_content = "¡Estoy obteniendo una respuesta!",
  ui_story_5075_50751401_55_dialog_content = "Yoh, voy a intentar expulsar los pensamientos negativos que están controlando tu cuerpo.",
  ui_story_5075_50751401_56_dialog_content = "¡Por favor, intenta trabajar conmigo!",
  ui_story_5075_50751401_57_dialog_content = "PlayerName y Yuebai seguro son lentos.",
  ui_story_5075_50751401_58_dialog_content = "¿Qué dijiste?",
  ui_story_5075_50751401_59_dialog_content = "Digo, ya no tengo ganas de hablar contigo.",
  ui_story_5075_50751401_60_dialog_content = "Acaso...",
  ui_story_5075_50751401_61_dialog_content = "Detén la farsa. Tú no eres mi pariente.",
  ui_story_5075_50751401_62_dialog_content = "No eres mi pariente.",
  ui_story_5075_50751401_63_dialog_content = "!",
  ui_story_5075_50751401_64_dialog_content = "Cuando desperté por primera vez, intenté contactar a mis compañeros.",
  ui_story_5075_50751401_65_dialog_content = "Pero todos seguían durmiendo. Desde Longzhou hasta Cloud Island, muy pocos respondieron.",
  ui_story_5075_50751401_66_dialog_content = "Así que la única razón por la que incluso te hablé fue porque tenías la vibra del dragón negro.",
  ui_story_5075_50751401_67_dialog_content = "Pero tú no eres ese dragón negro en absoluto, solo eres una colección de emociones negativas que robó algunos recuerdos de tu recipiente.",
  ui_story_5075_50751401_68_dialog_content = "Dejaste solo arrogancia en el Dragón Negro y solo odio en Yoh.",
  ui_story_5075_50751401_69_dialog_content = "Eso es porque son las únicas dos cosas que tienes.",
  ui_story_5075_50751401_70_dialog_content = "Sigues enfatizando el patriotismo, pero no tienes ninguna simpatía por los demonios.",
  ui_story_5075_50751401_71_dialog_content = "Afirmas ser noble, pero solo te aferras a la cobardía.",
  ui_story_5075_50751401_72_dialog_content = "Ni siquiera tienes una personalidad de la que hablar y te escondes detrás de una fachada.",
  ui_story_5075_50751401_73_dialog_content = "¿De verdad crees que puedes reclamar ser una forma de vida superior?",
  ui_story_5075_50751401_74_dialog_content = "¿Qué tiene de malo no tener personalidad? ¡Soy un verdadero inmortal!",
  ui_story_5075_50751401_75_dialog_content = "¡Incluso las llamadas deidades como tú no pueden igualarme en longevidad! Yo...",
  ui_story_5075_50751401_76_dialog_content = "¡Ahora, antes de que recupere su compostura!",
  ui_story_5075_50751401_77_option_content = "¡Potencia de fuerza!",
  ui_story_5075_50751401_78_dialog_content = "Es. Mi. Cuerpo.",
  ui_story_5075_50751401_79_dialog_content = "¡Salir!",
  ui_story_5075_50751401_80_dialog_content = "¡Urgh!",
  ui_story_5075_50751401_81_dialog_content = "¿Qué?",
  ui_story_5075_50751401_82_dialog_content = "¡Gracias a tu distracción, Chen'ni, pudimos encontrarlo!",
  ui_story_5075_50751401_83_dialog_content = "Ahora solo tenemos que ayudar a Yoh a expulsarlo desde adentro...",
  ui_story_5075_50751401_84_dialog_content = "¡Piensa otra vez!",
  ui_story_5075_50751402_1_dialog_content = "Tsk, tsk... Solo una cáscara inútil. ¿Qué importa si te la devuelvo?",
  ui_story_5075_50751402_2_dialog_content = "Aquí es donde está enterrado mi cuerpo original.",
  ui_story_5075_50751402_3_dialog_content = "¡Incluso en este estado, no soy algo que puedas manejar!",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>El mar en la distancia se agita una vez más.</color>",
  ui_story_5075_50751402_5_dialog_content = "(Pero me niego a ver a Haojin bajo el agua otra vez.)",
  ui_story_5075_50751402_6_dialog_content = "Chen'ni, dijiste que podía usar esto para pedirte un deseo, ¿verdad?",
  ui_story_5075_50751402_7_dialog_content = "¿Oh?",
  ui_story_5075_50751402_8_dialog_content = "¿Qué deseo tienes en mente?",
  ui_story_5075_50751402_9_dialog_content = "Esa cosa no es un Aurorian ni un demonio, ni siquiera un Eclipsite.",
  ui_story_5075_50751402_10_dialog_content = "No es más que una masa desencarnada de intención malvada.",
  ui_story_5075_50751402_11_dialog_content = "Oh Todopoderoso Dragón Divino Benevolente, ¿podrías por favor deshacerte de este mal y devolver la paz a este lugar una vez más?",
  ui_story_5075_50751402_12_dialog_content = "Concedido.",
  ui_story_5075_50751402_13_dialog_content = "Tsk, tsk... Han pasado ochocientos años, y tu virtuosa Doncella Dragón no levantó un dedo cuando inundé Haojin.",
  ui_story_5075_50751402_14_dialog_content = "Las ofrendas deben ser insuficientes, por lo que sufre una disminución de poder—",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>En un fugaz momento, un loto dorado irradia brillantez.</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>Una figura etérea y cristalina se eleva entre el mar y el cielo.</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>La espléndida luz dorada se propaga como ondas, y dondequiera que llega, los espíritus malvados desaparecen en el aire.</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>Dentro de la ciudad de Haojin</color>",
  ui_story_5075_50751402_19_dialog_content = "Gruñido...",
  ui_story_5075_50751402_20_dialog_content = "Los espíritus malignos en la ciudad... ¿Todos han desaparecido?",
  ui_story_5075_50751402_21_dialog_content = "¡Mira! ¡Mira el cielo!",
  ui_story_5075_50751402_22_dialog_content = "¡Es la Doncella Dragón! La Doncella Dragón se ha manifestado, ayudándonos a ahuyentar el mal!",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>El remanente de Eclipsite, tomando la forma de un dragón negro, se gira y huye sin ninguna vacilación.</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>Solo para que la figura etérea lo inmovilizara con un simple movimiento de dedo.</color>",
  ui_story_5075_50751402_25_dialog_content = "Si crees que estoy debilitado, ¿por qué tienes miedo de luchar?",
  ui_story_5075_50751402_26_dialog_content = "Tsk, tsk, tsk...",
  ui_story_5075_50751402_27_dialog_content = "Nunca pensé que después de tanto tiempo, aún mantendrías este nivel de fuerza.",
  ui_story_5075_50751402_28_dialog_content = "¡Pero aún no has ganado!",
  ui_story_5075_50751402_29_dialog_content = "¡Mientras la fuerza del Archlord Eclipsite permanezca, soy prácticamente inmortal!",
  ui_story_5075_50751402_30_dialog_content = "Si destrozas esta parte de mí, mi poder simplemente se reunirá y me devolverá a la vida.",
  ui_story_5075_50751402_31_dialog_content = "Seguramente puedes eliminarme una o dos veces, pero ¿puedes seguir acabando conmigo mil o diez mil veces?",
  ui_story_5075_50751402_32_dialog_content = "Yo—",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>No llega a terminar la frase.</color>",
  ui_story_5075_50751402_34_dialog_content = "Las cosas sin mente y forma no necesitan existir en el mundo.",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>La figura etérea lo aplasta.</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>Al instante siguiente, la niebla negra surge una vez más sobre el mar.</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>El resentimiento y el Darkflow se fusionan en un núcleo turbio en el centro de la niebla negra, tomando forma rápidamente.</color>",
  ui_story_5075_50751402_38_dialog_content = "Odio admitirlo, pero él tiene razón. No hay forma de que podamos proteger este lugar para siempre.",
  ui_story_5075_50751402_39_dialog_content = "Sin una solución permanente, no podemos garantizar que nadie salga lastimado la próxima vez, y la vez después de esa...",
  ui_story_5075_50751402_40_dialog_content = "¿De qué lado estás, PlayerName?",
  ui_story_5075_50751402_41_dialog_content = "Pero...",
  ui_story_5075_50751402_42_dialog_content = "Se dice que durante milenios, protegí los barcos que navegaban por el mar.",
  ui_story_5075_50751402_43_dialog_content = "Pero en los últimos cien años antes de despertar, los mortales continuaron viajando.",
  ui_story_5075_50751402_44_dialog_content = "Son capaces de protegerse a sí mismos sin intervención divina.",
  ui_story_5075_50751402_45_dialog_content = "¡Eso es lo que me encanta escuchar!",
  ui_story_5075_50751402_46_dialog_content = "Esa voz.",
  ui_story_5075_50751402_47_dialog_content = "Xuan Ji!",
  ui_story_5075_50751402_48_dialog_content = "Mucho tiempo sin verte, PlayerName.",
  ui_story_5075_50751402_49_dialog_content = "Veo que llegué a tiempo para el final.",
  ui_story_5075_50751402_50_dialog_content = "¡Permíteme mostrarte lo último y genial del Reino Ye!",
  ui_story_5075_50751402_51_dialog_content = "Operación estable. Objetivo bloqueado. Máximo poder.",
  ui_story_5075_50751402_52_dialog_content = "<size=45>¡Fuego!</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>Una deslumbrante luz dorada atraviesa el mar, y un trueno artificial atraviesa la niebla negra desde el centro.</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>Antes de que la niebla negra, intentando condensarse, pueda llenar la brecha anterior, se destroza una vez más.</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>Después de un fuerte bombardeo, el mar finalmente vuelve a la calma.</color>",
  ui_story_5075_50751402_61_dialog_content = "¿No va a volver?",
  ui_story_5075_50751402_62_dialog_content = "Correcto. Desapareció por completo sin dejar rastro antes de tener la oportunidad de reaccionar.",
  ui_story_5075_50751402_63_dialog_content = "¿Es esto también uno de tus pequeños inventos mientras yo dormía?",
  ui_story_5075_50751402_64_dialog_content = "¡N-No metas tu cabeza en el barril!",
  ui_story_5075_50751402_65_dialog_content = "Relájate, lo apagué.",
  ui_story_5075_50751402_66_dialog_content = "¿No tienes asuntos importantes en el Reino Ye, Xuan Ji?",
  ui_story_5075_50751402_67_dialog_content = "Sí, pero ¿quién sabía que recibiría una llamada de la princesa Dantang a mitad de camino?",
  ui_story_5075_50751402_68_dialog_content = "Supuse que Ji estaba en un apuro mayor, así que tomé el control del <color=#FFB400>cañón arcano</color> más avanzado para refuerzos.",
  ui_story_5075_50751402_69_dialog_content = "Solo para que Su Alteza esté ausente...",
  ui_story_5075_50751402_70_dialog_content = "Aunque verte es suficiente, PlayerName!",
  ui_story_5075_50751402_71_dialog_content = "Dantang está en la ciudad ahora mismo.",
  ui_story_5075_50751402_72_dialog_content = "Ya que todo ha vuelto a la normalidad, ¿por qué no regresas con nosotros y pasas el Festival de Primavera aquí en Haojin?",
  ui_story_5075_50751402_73_dialog_content = "Oh, recuerdo lo impresionante que es la ceremonia de Año Nuevo para repeler monstruos en Haojin.",
  ui_story_5075_50751402_74_dialog_content = "Lástima que tenga que apurarme a volver a Ye por asuntos pendientes.",
  ui_story_5075_50751402_75_dialog_content = "También deberías volver y no perderte la celebración. Nos reuniremos más tarde.",
  ui_story_5075_50751402_76_dialog_content = "No olvides saludar a la princesa Dantang de mi parte.",
  ui_story_5075_50751402_77_dialog_content = "Bien entonces, mucha suerte con tu asunto oficial.",
  ui_story_5075_50751402_78_dialog_content = "¡Enviaré un pájaro mecánico si algo sucede!",
  ui_story_5075_50751402_79_dialog_content = "Hmm, esto se siente como una decepción.",
  ui_story_5075_50751402_80_dialog_content = "Vine todo el camino desde Ye con el blaster arcano solo para un breve cameo.",
  ui_story_5075_50751402_81_dialog_content = "Pero aunque nadie me aclamó como un héroe entonces, ahora estoy consiguiendo un séquito bastante grande.",
  ui_story_5075_50751402_82_dialog_content = "Señora Xuan Ji.",
  ui_story_5075_50751402_83_dialog_content = "Has tomado armas altamente clasificadas sin permiso.",
  ui_story_5075_50751402_84_dialog_content = "Y hasta has contrabandeado estas armas a otro reino. Ahora eres sospechoso de traición.",
  ui_story_5075_50751402_X84_dialog_content = "Bueno, es discutible si tu gente representa al Reino Ye...",
  ui_story_5075_50751402_85_dialog_content = "¿El rey te envió?",
  ui_story_5075_50751402_86_dialog_content = "En efecto, nosotros, bajo el mando secreto del <color=#FFB400>Rey de Ye</color>, vamos a arrestarte. ¿Desafiarás esta orden?",
  ui_story_5075_50751402_87_dialog_content = "... Para nada.",
  ui_story_5075_50751402_88_dialog_content = "Soy ciudadano de Ye, sin mencionar que fui asesor estatal y luminaria.",
  ui_story_5075_50751402_89_dialog_content = "Me niego a seguir a cualquiera que perjudique los intereses de Ye, pero nunca desobedeceré la orden del rey.",
  ui_story_5075_50751402_90_dialog_content = "Me declaro culpable.",
  ui_story_5075_50751402_91_dialog_content = "...",
  ui_story_5075_50751402_92_dialog_content = "Vamos, no estés tan decepcionado.",
  ui_story_5075_50751402_93_dialog_content = "Esta es mi primera vez pasando el Año Nuevo en la cárcel, así que agradecería que me avisaras cuando no siga el protocolo.",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>¡Bang! ¡Bang!</color>",
  ui_story_5075_50751501_2_dialog_content = "¡Guau, un espectáculo de fuegos artificiales!",
  ui_story_5075_50751501_3_dialog_content = "Después de solo una noche, toda la ciudad está llena de festividad.",
  ui_story_5075_50751501_4_dialog_content = "Los espíritus malvados han sido purgados, y el malentendido entre las personas y los demonios ha sido resuelto.",
  ui_story_5075_50751501_5_dialog_content = "Todos deberían poder disfrutar de un Festival de Primavera despreocupado mañana.",
  ui_story_5075_50751501_6_dialog_content = "¿Yoh también está regresando al mar?",
  ui_story_5075_50751501_7_dialog_content = "Sí. Dice que necesita estar solo por un tiempo para decidir qué hacer a continuación.",
  ui_story_5075_50751501_8_dialog_content = "¿Crees que va a vengarse de la familia Lin?",
  ui_story_5075_50751501_9_dialog_content = "No estoy seguro.",
  ui_story_5075_50751501_10_dialog_content = "Pero al menos, logramos resolver nuestras diferencias pasadas. En cuanto al futuro...",
  ui_story_5075_50751501_11_dialog_content = "Esa es una pregunta para mañana, ¿no crees?",
  ui_story_5075_50751501_12_dialog_content = "\"Merry Año Nuevo,\" ¿verdad?",
  ui_story_5075_50751501_13_dialog_content = "Li Tianxian no estaba mintiendo después de todo. ¡Este antiguo encantamiento realmente funciona!",
  ui_story_5075_50751501_14_dialog_content = "?",
  ui_story_5075_50751501_15_dialog_content = "... Jejeje.",
  ui_story_5075_50751501_16_dialog_content = "¿P-Por qué te ríes, Yuebai? Esto no es algún tipo de broma, ¿verdad?",
  ui_story_5075_50751501_17_dialog_content = "No.",
  ui_story_5075_50751501_18_dialog_content = "Realmente es un hechizo poderoso.",
  ui_story_5075_50751501_19_dialog_content = "Todavía tengo asuntos que atender con la familia Lin. Hasta la próxima.",
  ui_story_5075_50751501_20_dialog_content = "Seguro, hasta luego.",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>¡Crepitar y estallido!</color>",
  ui_story_5075_50751501_22_dialog_content = "¿Qué está pasando?",
  ui_story_5075_50751501_23_dialog_content = "¡La ceremonia para repeler monstruos viene en esta dirección!",
  ui_story_5075_50751501_24_dialog_content = "¿Chen'ni? ¿Dónde has estado todo este tiempo?",
  ui_story_5075_50751501_25_dialog_content = "¿Y cuándo conseguiste todos esos bocadillos?",
  ui_story_5075_50751501_26_dialog_content = "De alguna manera hice la ronda con mis cuernos de dragón a la vista, ¡y los vendedores simplemente me llenaron con estos!",
  ui_story_5075_50751501_27_dialog_content = "Oh, es cierto, PlayerName no tiene cuernos ni cola.",
  ui_story_5075_50751501_28_dialog_content = "No te sientas triste. Compartiré el botín contigo.",
  ui_story_5075_50751501_29_dialog_content = "Gracias, pero eso no me molesta mucho.",
  ui_story_5075_50751501_30_dialog_content = "Mira, Luo Song es uno de los artistas.",
  ui_story_5075_50751501_31_dialog_content = "¡En serio! Y mira, también hay un montón de diablillos con él.",
  ui_story_5075_50751501_32_dialog_content = "Los petardos estallan, ahuyentando a los monstruos, desterrando la desgracia de una manera alegre.",
  ui_story_5075_50751501_33_dialog_content = "Las bendiciones se despliegan con auspiciosos presagios. ¡Dando la bienvenida a la primavera, la felicidad ilumina cada rostro!",
  ui_story_5075_50751501_34_dialog_content = "Espera, pensé que se suponía que debían ahuyentar a los monstruos. ¿Por qué los diablillos también son perseguidores?",
  ui_story_5075_50751501_35_dialog_content = "Cambió este año, no ahuyentando a los diablillos, sino a los espíritus malignos en su lugar.",
  ui_story_5075_50751501_36_dialog_content = "¿No viste la manifestación de la Doncella Dragón anoche? Ella erradicó todos los espíritus malvados, dejando a los demonios intactos.",
  ui_story_5075_50751501_37_dialog_content = "Eso significa que incluso la Doncella Dragón considera a los fiendlings inofensivos, ¿verdad?",
  ui_story_5075_50751501_38_dialog_content = "¡Escucha! ¡Necesitas aprender a trabajar en equipo si quieres derrotar a un oponente poderoso!",
  ui_story_5075_50751501_39_dialog_content = "¡Al combinar tus fortalezas únicas, tu poder aumentará dramáticamente!",
  ui_story_5075_50751501_40_dialog_content = "¡Bien Ah Ding, haz que tu nuevo amigo te ayude a mostrarle a todos lo que quiero decir!",
  ui_story_5075_50751501_41_dialog_content = "¡Ja!",
  ui_story_5075_50751501_42_dialog_content = "¡Rugido!",
  ui_story_5075_50751501_43_dialog_content = "¿Estoy viendo cosas?",
  ui_story_5075_50751501_44_dialog_content = "¿Por qué ese gato se ve tan familiar?",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>¡Crepitar y estallido!</color>",
  ui_story_5075_50751501_46_dialog_content = "Los petardos estallan, ahuyentando a los monstruos... ¡Ay!",
  ui_story_5075_50751501_47_dialog_content = "Lo siento, no estaba mirando por dónde iba y te choqué... Oh.",
  ui_story_5075_50751501_48_dialog_content = "¿Si?",
  ui_story_5075_50751501_49_dialog_content = "Oh, es el chico que estaba molestando a ese pequeño demonio antes.",
  ui_story_5075_50751501_50_dialog_content = "Entonces, eh... Señorita, tú también eres un diablillo, ¿verdad?",
  ui_story_5075_50751501_51_dialog_content = "¡Aquí tienes un caramelo para ti!",
  ui_story_5075_50751501_52_dialog_content = "Y... si conoces a algún demonio al que hayamos sido malos, ¡por favor diles que lo siento!",
  ui_story_5075_50751501_53_dialog_content = "Se escapó...",
  ui_story_5075_50751501_54_dialog_content = "Supongo que las opiniones de la gente hacia los fiendlings realmente están empezando a cambiar.",
  ui_story_5075_50751501_55_dialog_content = "Hmm... ¡Wow!",
  ui_story_5075_50751501_56_dialog_content = "Es muy dulce.",
  ui_story_5075_50751501_57_dialog_content = "Pensé que ver esto te haría sentir feliz, Chen'ni.",
  ui_story_5075_50751501_58_dialog_content = "Estoy feliz.",
  ui_story_5075_50751501_59_dialog_content = "Entonces, ¿por qué se siente como...",
  ui_story_5075_50751501_60_dialog_content = "Tu felicidad no es diferente a la felicidad que sentiste ayer o incluso el día anterior.",
  ui_story_5075_50751501_61_dialog_content = "Bueno, así es como es en el mundo.",
  ui_story_5075_50751501_62_dialog_content = "La gente se vuelve contra los fiendlings un día por miedo, y al siguiente los tratan bien por culpa.",
  ui_story_5075_50751501_63_dialog_content = "¿Quién sabe cómo verán a los diablillos mañana?",
  ui_story_5075_50751501_64_dialog_content = "Es posible que ayer hayas obtenido un bocadillo delicioso, uno terrible hoy y luego uno delicioso nuevamente mañana.",
  ui_story_5075_50751501_65_dialog_content = "Siempre habrá buenos y malos, pero los buenos no permanecerán buenos, y los malos no permanecerán malos.",
  ui_story_5075_50751501_66_dialog_content = "Creo que me gusta así.",
  ui_story_5075_50751501_67_dialog_content = "Yo... no puedo decir que realmente entiendo lo que estás sintiendo, Chen'ni.",
  ui_story_5075_50751501_68_dialog_content = "Pero después de todo por lo que pasamos, creo que tiene un poco más de sentido ahora.",
  ui_story_5075_50751501_69_dialog_content = "En tus ojos, cada ser vivo es exactamente igual. No te hace ninguna diferencia si son personas, demonios o cualquier otra cosa.",
  ui_story_5075_50751501_70_dialog_content = "Todos los seres tienen un significado detrás de su existencia.",
  ui_story_5075_50751501_71_dialog_content = "Y porque respetas ese significado, intentas no interferir en nuestro mundo.",
  ui_story_5075_50751501_72_dialog_content = "No es que no te importemos, sino que te preocupas por todos por igual.",
  ui_story_5075_50751501_73_dialog_content = "Si ese es el caso, estoy seguro de que nuestros problemas de estos últimos días deben haberte parecido terriblemente insignificantes.",
  ui_story_5075_50751501_74_dialog_content = "Esperamos no haberte decepcionado demasiado.",
  ui_story_5075_50751501_75_dialog_content = "Entonces, ¿qué vas a hacer ahora, Chen'ni?",
  ui_story_5075_50751501_76_dialog_content = "Salí porque me despertaron de manera grosera.",
  ui_story_5075_50751501_77_dialog_content = "Así que volveré a dormir en un rato.",
  ui_story_5075_50751501_78_dialog_content = "¿Tan pronto?",
  ui_story_5075_50751501_79_dialog_content = "¡Emisario! El rey pide tu presencia en el palacio.",
  ui_story_5075_50751501_80_dialog_content = "Uh, claro.",
  ui_story_5075_50751501_81_dialog_content = "Chen'ni, ¿quieres venir? ¿Chen'ni?",
  ui_story_5075_50751501_82_dialog_content = "¿Ya se fue, eh?",
  ui_story_5075_50751501_83_dialog_content = "Gracias por todo, PlayerName.",
  ui_story_5075_50751501_84_dialog_content = "Esta vez—",
  ui_story_5075_50751501_85_dialog_content = "¡PlayerName! ¡PlayerName!",
  ui_story_5075_50751501_86_dialog_content = "He escuchado todo de Dantang. Ella dijo que tomaste el control en una crisis, mostrando una sabiduría y valentía sin igual.",
  ui_story_5075_50751501_87_dialog_content = "¡No solo expusiste a los villanos en la corte del Reino Ji, sino que también se te atribuye el oportuno retroceso de la inundación de ayer!",
  ui_story_5075_50751501_88_dialog_content = "Creo que no exageré la cuenta de esta manera, Príncipe Heredero.",
  ui_story_5075_50751501_89_dialog_content = "De todos modos, ahora sé que PlayerName es un gran héroe!",
  ui_story_5075_50751501_90_dialog_content = "Eres increíble, héroe! <size=45>¡Quiero casarme con PlayerName!</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>... ¿Qué?</size>",
  ui_story_5075_50751501_92_dialog_content = "Como dice el dicho, marido y mujer son como uno solo. ¡Con una prometida increíble como tú, seguramente también seré un héroe!",
  ui_story_5075_50751501_93_dialog_content = "<size=45>¡Ejem!</size>",
  ui_story_5075_50751501_94_dialog_content = "¡Alguien escolte al príncipe de regreso inmediatamente!",
  ui_story_5075_50751501_95_dialog_content = "Dile al tutor que le enseñe el significado del matrimonio y que lo haga dejar todas estas tonterías por las que casi caí...",
  ui_story_5075_50751501_96_dialog_content = "Sin embargo, sus otros comentarios no están equivocados.",
  ui_story_5075_50751501_97_dialog_content = "La crisis en Haojin fue un error de cálculo de mi parte, y gracias a ti se evitó el desastre.",
  ui_story_5075_50751501_98_dialog_content = "Por lo tanto, siéntete libre de decirme lo que quieras, y seguramente lo concederé.",
  ui_story_5075_50751501_99_dialog_content = "En ese caso, ¡Dantang y yo nos gustaría compartir nuestro plan contigo para mejorar las relaciones entre nuestras dos tierras!",
  ui_story_5075_50751501_100_dialog_content = "¿Eso es todo? ¿No deseas oro, tesoros o posiciones de poder?",
  ui_story_5075_50751501_101_dialog_content = "Para ser honesto, eso no es del todo falso. Pero vine a Longzhou como el enviado oficial de Astra.",
  ui_story_5075_50751501_102_dialog_content = "Completar mi misión es mi máxima prioridad.",
  ui_story_5075_50751501_103_dialog_content = "Jajaja, para un joven talento como tú, de alguna manera no quiero dejarte volver.",
  ui_story_5075_50751501_104_dialog_content = "Pero ya que no estás dispuesto a quedarte en Longzhou, ¿qué te parece esto?",
  ui_story_5075_50751501_105_dialog_content = "Por la presente te declaro Ciudadano Honorario del Reino de Ji.",
  ui_story_5075_50751501_106_dialog_content = "No importa a dónde vayas o qué hagas de ahora en adelante, el Reino de Ji siempre te dará la bienvenida.",
  ui_story_5075_50751501_107_dialog_content = "¡Gracias, Señor!",
  ui_story_5075_50751501_108_dialog_content = "Uf... Pasamos mucho tiempo en el palacio y se está haciendo tarde.",
  ui_story_5075_50751501_109_dialog_content = "Después de que el mayordomo fue arrestado, también se deshicieron de todos esos guardias y sirvientas.",
  ui_story_5075_50751501_110_dialog_content = "Creo que esta es la primera vez que estoy completamente solo aquí.",
  ui_story_5075_50751501_111_dialog_content = "... Es tan tranquilo.",
  ui_story_5075_50751501_112_dialog_content = "Ahora que las cosas finalmente se han calmado, no estoy seguro de qué hacer conmigo mismo.",
  ui_story_5075_50751501_113_dialog_content = "Oh sí, el Festival de Primavera es mañana.",
  ui_story_5075_50751501_114_dialog_content = "Por lo que he oído, todas las familias en Longzhou se van a quedar despiertas toda la noche hoy mientras comen y pasan el rato juntas.",
  ui_story_5075_50751501_115_dialog_content = "Es su forma de despedirse del último año y dar la bienvenida al nuevo año.",
  ui_story_5075_50751501_116_dialog_content = "Tal vez debería hacer algo así también... Nah, no tiene sentido quedarme despierto toda la noche solo.",
  ui_story_5075_50751501_117_dialog_content = "Me pregunto qué estarán haciendo todos...",
  ui_story_5075_50751501_118_dialog_content = "Esperando a que PlayerName me note.",
  ui_story_5075_50751501_119_dialog_content = "¿Eh? ¿C-Cuándo entraste aquí?",
  ui_story_5075_50751501_120_dialog_content = "Estaba aquí antes de que volvieras.",
  ui_story_5075_50751501_121_dialog_content = "Solo para verte deambular sin prestar atención a nada, así que tuve que mostrarme.",
  ui_story_5075_50751501_122_dialog_content = "Así que viste eso, ¿eh...",
  ui_story_5075_50751501_123_dialog_content = "Pensé que ya te habías ido.",
  ui_story_5075_50751501_124_dialog_content = "Dijiste que ibas a volver al mar en un rato, después de todo.",
  ui_story_5075_50751501_125_dialog_content = "Es cierto. No planeo quedarme mucho tiempo.",
  ui_story_5075_50751501_126_dialog_content = "Voy a volver en unas pocas décadas.",
  ui_story_5075_50751501_127_dialog_content = "¿Espera, qué? ¿Unas pocas décadas son solo \"un rato\" para ti?",
  ui_story_5075_50751501_128_dialog_content = "¿Es eso demasiado rápido?",
  ui_story_5075_50751501_129_dialog_content = "Me gusta pasar el rato contigo.",
  ui_story_5075_50751501_130_dialog_content = "Así que si no te importa, es posible que me quede por un par de cien años.",
  ui_story_5075_50751501_131_dialog_content = "... Lo siento, olvidé que los demonios mayores tienen un sentido del tiempo completamente diferente al nuestro.",
  ui_story_5075_50751501_132_dialog_content = "¿Pero cómo es que no tienes nada aquí, PlayerName?",
  ui_story_5075_50751501_133_dialog_content = "Debería ser hora de una comida de Eve Año Nuevo.",
  ui_story_5075_50751501_134_dialog_content = "Jaja, supongo que olvidé.",
  ui_story_5075_50751501_135_dialog_content = "Bueno, estas son láminas de queso de soja que acabo de recibir como ofrenda. Tómalo.",
  ui_story_5075_50751501_136_dialog_content = "Gracias... Uh, ¿láminas de tofu?",
  ui_story_5075_50751501_137_dialog_content = "¡PlayerName! ¡Chen'ni!",
  ui_story_5075_50751501_138_dialog_content = "¿Dónde están ustedes dos?",
  ui_story_5075_50751501_139_dialog_content = "¿Es eso Luo Song?",
  ui_story_5075_50751501_140_dialog_content = "¡Luo Song! ¡Aqui!",
  ui_story_5075_50751501_141_dialog_content = "¡Ah, ahí están! Me alegra haberlos encontrado finalmente a los dos.",
  ui_story_5075_50751501_142_dialog_content = "Debería haber preguntado dónde te alojabas antes de irme.",
  ui_story_5075_50751501_143_dialog_content = "Espera, ¿has estado caminando por las calles gritando nuestros nombres todo este tiempo?",
  ui_story_5075_50751501_144_dialog_content = "Ja ja, sé que no fue la forma más inteligente de buscarte, pero funcionó, ¿no?",
  ui_story_5075_50751501_145_dialog_content = "Después de todo lo que hemos pasado, no te importa que celebre el año nuevo contigo, ¿verdad?",
  ui_story_5075_50751501_146_dialog_content = "¡Claro que no!",
  ui_story_5075_50751501_147_dialog_content = "Alegra oírlo.",
  ui_story_5075_50751501_148_dialog_content = "De todos modos, ayudé a una anciana a mover algunas cosas antes, y ella me dio esta bolsa de apio por mis problemas.",
  ui_story_5075_50751501_149_dialog_content = "Al menos, podemos usarlo para preparar algo para esta noche.",
  ui_story_5075_50751501_150_dialog_content = "Vaya, este lugar está aún más desierto que mi puesto de adivinación.",
  ui_story_5075_50751501_151_dialog_content = "Li Tianxian, ¿tú también estás aquí?",
  ui_story_5075_50751501_152_dialog_content = "Para aprovecharme... quiero decir, para ver cómo estás, ya que estás en tierra extranjera y todo.",
  ui_story_5075_50751501_153_dialog_content = "No puedo creer que ni siquiera tengas una comida preparada. Supongo que tienes suerte de que esté aquí.",
  ui_story_5075_50751501_154_dialog_content = "Aquí, un regalo de Año Nuevo de mi parte.",
  ui_story_5075_50751501_155_dialog_content = "Aprecio el gesto y todo, pero ¿por qué me das un montón de vegetales silvestres?",
  ui_story_5075_50751501_156_dialog_content = "Esta no es una verdura ordinaria. Es bolsa de pastor y es difícil de encontrar en invierno.",
  ui_story_5075_50751501_157_dialog_content = "Tuve que conseguir el lote de un invernadero, y me costó todas las ganancias que obtuve de las figuritas de azúcar.",
  ui_story_5075_50751501_158_dialog_content = "Representa fortuna y riqueza, ¡así que tus arcas estarán llenas durante todo el año!",
  ui_story_5075_50751501_159_dialog_content = "Y también tienes láminas de tofu. Eso es auspicioso y trae prosperidad para las generaciones venideras.",
  ui_story_5075_50751501_160_dialog_content = "El apio tampoco está mal. Significa dinero a través del trabajo duro.",
  ui_story_5075_50751501_161_dialog_content = "Ven a darme una mano, PlayerName—",
  ui_story_5075_50751501_162_dialog_content = "Un miembro del gremio nos envió un carro completo de raíces de loto frescas. Pensé que no preparaste ningún ingrediente esta noche, así que traje algunos para ti.",
  ui_story_5075_50751501_163_dialog_content = "¿Un carro entero?",
  ui_story_5075_50751501_164_dialog_content = "Solo tómalo. Todo de calidad, ya sabes.",
  ui_story_5075_50751501_165_dialog_content = "Veo señales que apuntan a una buena fortuna para ti en todas partes.",
  ui_story_5075_50751501_166_dialog_content = "¿Crees que todo es auspicioso, verdad?",
  ui_story_5075_50751501_167_dialog_content = "Es el Año Nuevo, por supuesto que todo es auspicioso.",
  ui_story_5075_50751501_168_dialog_content = "Podía escuchar a Li estafando desde una milla de distancia.",
  ui_story_5075_50751501_169_dialog_content = "Aunque es agradable hablar con felicidad en el Eve de Año Nuevo.",
  ui_story_5075_50751501_170_dialog_content = "Ha pasado un tiempo, PlayerName.",
  ui_story_5075_50751501_171_dialog_content = "¿Dantang? ¿Jiu? ¿No deberías estar celebrando el año nuevo de vuelta en el palacio?",
  ui_story_5075_50751501_172_dialog_content = "Se supone que debemos.",
  ui_story_5075_50751501_173_dialog_content = "Pero debido a tus méritos durante los últimos días, PlayerName, el rey me asignó una tarea especial.",
  ui_story_5075_50751501_174_dialog_content = "Me aseguraré de que tengas un Año Nuevo agradable.",
  ui_story_5075_50751501_175_dialog_content = "Hay carritos de comida afuera del palacio. Cocinaré yo mismo y prepararé los platos apropiados para las fiestas.",
  ui_story_5075_50751501_176_dialog_content = "Oh, me gustaría ofrecer mi bendición también.",
  ui_story_5075_50751501_177_dialog_content = "Con este plato de lirios de día de color amarillo dorado, PlayerName...",
  ui_story_5075_50751501_178_dialog_content = "Te deseo un futuro brillante.",
  ui_story_5075_50751501_179_dialog_content = "Supongo que te ofreceré vainas de guisantes. Significan una cosecha completa en Longzhou.",
  ui_story_5075_50751501_180_dialog_content = "¡Guau, veo a tanta gente!",
  ui_story_5075_50751501_181_dialog_content = "Y estaba preocupado de que PlayerName fuera a pasar el Año Nuevo Eve solo.",
  ui_story_5075_50751501_182_dialog_content = "Es bueno que nuestro joven amigo sea tan popular.",
  ui_story_5075_50751501_183_dialog_content = "Zhong Xu! Liqing! ¡Ustedes también están aquí!",
  ui_story_5075_50751501_184_dialog_content = "¿De dónde vino toda esta comida en la mesa? ¡Ah, ya sé!",
  ui_story_5075_50751501_185_dialog_content = "Estás haciendo el Diez Escénico, ¿verdad?",
  ui_story_5075_50751501_186_dialog_content = "¿Qué es eso?",
  ui_story_5075_50751501_187_dialog_content = "Es un famoso plato tradicional de Ji con docenas de vegetales finamente rebanados y salteados.",
  ui_story_5075_50751501_188_dialog_content = "Eso combina todos los auspicios en un plato.",
  ui_story_5075_50751501_189_dialog_content = "Es una necesidad del Festival de Primavera en Ji.",
  ui_story_5075_50751501_190_dialog_content = "Pero veo que todavía falta algo aquí.",
  ui_story_5075_50751501_191_dialog_content = "Permítanme contribuir con mostaza de hoja a la causa y desear a todos una gran carrera.",
  ui_story_5075_50751501_192_dialog_content = "Agregaré un poco de hierba de cerdo por si acaso.",
  ui_story_5075_50751501_193_dialog_content = "No es solo una verdura, sino también una hierba anti-toxina.",
  ui_story_5075_50751501_194_dialog_content = "Realmente estás poniendo a prueba mis habilidades culinarias con ingredientes tan exóticos.",
  ui_story_5075_50751501_195_dialog_content = "Oh, no será un desafío para usted en absoluto, Su Alteza.",
  ui_story_5075_50751501_196_dialog_content = "¿Estás seguro, Jiu? ¿Por qué no vienes a echarme una mano en la cocina entonces?",
  ui_story_5075_50751501_197_dialog_content = "Yo también ayudaré.",
  ui_story_5075_50751501_198_dialog_content = "Déjame la degustación a mí.",
  ui_story_5075_50751501_199_dialog_content = "¡Puedo hacer la degustación!",
  ui_story_5075_50751501_200_dialog_content = "Bien, no puedo pelear contigo por eso, así que por favor, adelante.",
  ui_story_5075_50751501_201_dialog_content = "Saliré y ordenaré los ingredientes. Solo dime lo que necesitas y lo traeré.",
  ui_story_5075_50751501_202_dialog_content = "También traje algunas decoraciones para colocar en toda la habitación.",
  ui_story_5075_50751501_203_dialog_content = "Eso es maravilloso. Estaba pensando que este lugar podría usar más festividad.",
  ui_story_5075_50751501_204_dialog_content = "Aquí llega el Diez Escénico en el que todos han tenido una mano.",
  ui_story_5075_50751501_205_dialog_content = "Antes de que la campana del Templo de la Doncella Dragón suene en unos minutos para dar la bienvenida oficialmente al Año Nuevo...",
  ui_story_5075_50751501_206_dialog_content = "Mi gratitud por todo lo que has hecho por mí en el pasado año, PlayerName.",
  ui_story_5075_50751501_207_dialog_content = "No soy bueno con las palabras, así que solo diré \"¡Gracias!\"",
  ui_story_5075_50751501_208_dialog_content = "Agradezco su negocio el año pasado y espero su patrocinio el próximo año.",
  ui_story_5075_50751501_209_dialog_content = "Estoy agradecido por tu ayuda en nuestros viajes anteriores, joven amigo. Te deseo un hermoso Año Nuevo.",
  ui_story_5075_50751501_210_dialog_content = "Te agradezco por todo. ¡Mantente saludable para que no tengas que venir a verme para un tratamiento!",
  ui_story_5075_50751501_211_dialog_content = "Podemos haber recién nos conocido, pero ya te considero un buen amigo.",
  ui_story_5075_50751501_212_dialog_content = "¡Brindemos por el nuevo año! Te deseo la fuerza que necesitas para vencer cualquier espíritu maligno que se cruce en tu camino!",
  ui_story_5075_50751501_213_dialog_content = "¡Salud, y Feliz Año Nuevo!",
  ui_story_5075_50751501_214_dialog_content = "*traga*",
  ui_story_5075_50751501_215_dialog_content = "¡Ey, ni siquiera tomé un sorbo! No te vayas con eso...",
  ui_story_5075_50751501_216_dialog_content = "PlayerName, PlayerName.",
  ui_story_5075_50751501_217_dialog_content = "¿Qué pasa, Chen'ni?",
  ui_story_5075_50751501_218_dialog_content = "Baja la cabeza.",
  ui_story_5075_50751501_219_dialog_content = "Vale, pero ¿qué estás haciendo?",
  ui_story_5075_50751501_220_dialog_content = "Déjame acariciarte.",
  ui_story_5075_50751501_221_dialog_content = "Sé feliz y contento todos los días.",
  ui_story_5075_50751501_222_dialog_content = "¡Esto viene directamente de una deidad, así que puedes confiar en eso!",
  ui_story_5075_50751501_223_dialog_content = "<color=#e8d9bb>Dong—dong—</color>",
  ui_story_5075_50751501_224_dialog_content = "<color=#e8d9bb>La campana del Templo de la Doncella Dragón suena desde las Montañas del Sur, resonando en toda la ciudad.</color>",
  ui_story_5075_50751501_225_dialog_content = "<color=#e8d9bb>Suena ciento ocho veces, limpiando preocupaciones y trayendo buena suerte y salud.</color>",
  ui_story_5075_50751501_226_dialog_content = "Ese sonido... Debe señalar el inicio del Festival de Primavera y un nuevo año.",
  ui_story_5075_50751501_227_dialog_content = "PlayerName.",
  ui_story_5075_50751501_228_dialog_content = "PlayerName.",
  ui_story_5075_50751501_229_dialog_content = "PlayerName.",
  ui_story_5075_50751501_230_dialog_content = "PlayerName.",
  ui_story_5075_50751501_231_dialog_content = "Joven amigo.",
  ui_story_5075_50751501_232_dialog_content = "PlayerName.",
  ui_story_5075_50751501_233_dialog_content = "PlayerName.",
  ui_story_5075_50751501_234_dialog_content = "PlayerName.",
  ui_story_5075_50751501_235_dialog_content = "<size=45>¡Feliz Año Nuevo!</size>"
}
return config
